__CR('t:arduino',[{"t":"아두이노 첫걸음","l":[{"t":"아두이노란?","q":[{"t":"choice","k":"언어","q":"아두이노 프로그래밍 언어는 무엇을 기반으로 하나요?","o":["Python","C/C++","JavaScript","SQL"],"a":1,"ex":"아두이노 스케치는 C/C++ 문법을 사용합니다."},{"t":"choice","k":"구조","q":"아두이노 코드에서 처음에 딱 한 번만 실행되는 함수는?","o":["setup()","loop()","main()","start()"],"a":0,"ex":"setup() 에서 초기 설정(핀 모드 등)을 합니다."},{"t":"choice","k":"개념","q":"아두이노는 기본적으로 무엇인가요?","o":["인터넷에서 웹 페이지를 보여 주는 브라우저 프로그램","자료를 저장하고 찾아 주는 데이터베이스","하드웨어를 관리하는 컴퓨터 운영체제","전자 회로를 제어하는 마이크로컨트롤러 보드"],"a":3,"ex":"아두이노는 센서·모터·LED 등을 제어하는 작은 컴퓨터 보드입니다."},{"t":"choice","k":"구조","q":"setup() 이후 계속 반복해서 실행되는 함수는?","o":["setup()","repeat()","loop()","again()"],"a":2,"ex":"loop() 안의 코드가 무한 반복됩니다."}],"th":{"sum":"아두이노는 작은 컴퓨터가 달린 보드다. 전기 신호를 읽고 내보내서 **바깥 세상과 이어지는** 것이 목적이다.","body":[{"h":"컴퓨터와 다른 점","t":"화면도 키보드도 없다. 대신 핀이라는 금속 다리가 있어서 전선을 꽂는다. 프로그램은 컴퓨터에서 작성해 USB 로 보드에 옮겨 넣는다. 옮기고 나면 컴퓨터 없이 전원만 있으면 혼자 돈다."},{"h":"setup 과 loop","t":"`setup()` 은 전원이 켜질 때 **한 번만** 돈다. 준비 작업을 여기에 적는다. `loop()` 는 그 뒤로 **끝없이 반복**된다. 준비 작업을 실수로 loop 에 적으면 매번 다시 준비하느라 이상하게 동작한다."},{"h":"코드가 맞아도 안 될 수 있다","t":"아두이노는 배선이 함께 맞아야 동작한다. 코드가 완벽해도 전선 하나가 빠져 있으면 아무 일도 일어나지 않는다. '안 되면 코드보다 배선을 먼저 본다' 가 기본이다."}],"code":{"c":"void setup() {\n    pinMode(13, OUTPUT);   // 한 번만\n}\n\nvoid loop() {\n    digitalWrite(13, HIGH);  // 끝없이 반복\n}","cap":"setup 은 한 번, loop 는 계속"},"key":["핀으로 바깥 세상과 잇는다","`setup` 은 한 번, `loop` 는 반복","안 되면 배선을 먼저 본다"]}},{"t":"핀과 제어","q":[{"t":"choice","k":"함수","q":"핀을 입력(INPUT) 또는 출력(OUTPUT)으로 설정하는 함수는?","o":["digitalWrite()","pinMode()","begin()","setPin()"],"a":1,"ex":"pinMode(13, OUTPUT) 처럼 핀의 역할을 정합니다."},{"t":"choice","k":"함수","q":"프로그램을 잠시(밀리초 단위) 멈추게 하는 함수는?","o":["wait()","sleep()","delay()","stop()"],"a":2,"ex":"delay(1000) 은 1초 동안 멈춥니다."},{"t":"choice","k":"함수","q":"디지털 핀에 HIGH/LOW(켜기/끄기) 를 출력하는 함수는?","o":["delay() 함수","print() 함수","analogRead() 함수","digitalWrite()"],"a":3,"ex":"digitalWrite(13, HIGH) 로 LED 를 켭니다."},{"t":"choice","k":"제어","q":"LED 를 켜려면 핀에 어떤 값을 줘야 하나요?","o":["HIGH","OUTPUT","0","LOW"],"a":0,"ex":"HIGH 는 전압을 걸어 켜고, LOW 는 끕니다."}],"th":{"sum":"핀은 전기가 드나드는 문이다. 각 핀을 '내보내는 문' 으로 쓸지 '받아들이는 문' 으로 쓸지 먼저 정해 준다.","body":[{"h":"먼저 방향을 정한다","t":"`pinMode(13, OUTPUT)` 은 13번 핀을 내보내기용으로 쓰겠다는 선언이다. 읽으려면 `INPUT` 이다. 이걸 빠뜨리면 값이 제대로 나가지도 들어오지도 않는다 — `setup()` 에서 한 번 정해 둔다."},{"h":"디지털은 둘, 아날로그는 여럿","t":"`digitalWrite` 는 켬(HIGH)과 끔(LOW) 둘 중 하나만 보낸다. `analogRead` 는 0~5V 사이의 값을 0~1023 숫자로 읽는다. 밝기나 온도처럼 정도가 있는 값은 아날로그 쪽이다."},{"h":"delay 는 모든 것을 멈춘다","t":"`delay(1000)` 은 1초 동안 **아무것도 못 하게** 만든다. 그동안 버튼을 눌러도 반응하지 않는다. 여러 일을 함께 하려면 `millis()` 로 시각을 재서 '지날 때가 됐는지' 확인하는 방식으로 바꾼다."}],"code":{"c":"void setup() {\n    pinMode(13, OUTPUT);\n    pinMode(2, INPUT);\n}\n\nvoid loop() {\n    if (digitalRead(2) == HIGH)\n        digitalWrite(13, HIGH);\n}","cap":"방향을 먼저 정하고 쓴다"},"key":["`pinMode` 로 방향을 먼저 정한다","디지털은 켬·끔, 아날로그는 0~1023","`delay` 는 그동안 아무것도 못 한다"]}},{"t":"직접 이어 보기 — LED 를 켜는 회로","th":{"sum":"LED 는 **저항 없이 물리면 탄다.** 그리고 방향이 있어서 거꾸로 꽂으면 아예 안 켜진다.","body":[{"h":"왜 저항이 필요한가","t":"LED 는 전압이 조금만 넘어도 전류가 급격히 늘어난다. 5V 를 그대로 물리면 견딜 수 있는 전류를 훌쩍 넘겨 순식간에 망가진다. 220Ω 정도를 **직렬로** 끼워 전류를 제한한다 — LED 옆이 아니라 전류가 지나가는 길목에 있어야 한다."},{"h":"방향이 있다","t":"긴 다리(애노드, +)가 전원 쪽, 짧은 다리(캐소드, −)가 GND 쪽이다. 거꾸로 꽂으면 전류가 흐르지 않아 그냥 안 켜진다 — 고장이 아니라서 더 헷갈린다."},{"h":"회로는 돌아와야 한다","t":"핀에서 나간 전류가 GND 로 **돌아와야** 회로가 완성된다. GND 를 빼먹으면 아무 일도 일어나지 않는다. 아두이노에서 가장 흔한 '왜 안 되지' 의 정체다."}],"code":{"c":"void setup() { pinMode(13, OUTPUT); }\nvoid loop() { digitalWrite(13, HIGH); }\n// 코드가 맞아도 배선이 틀리면 안 켜진다","cap":"코드보다 배선이 먼저다"},"key":["LED 앞에는 저항을 직렬로","긴 다리가 +, 짧은 다리가 −","GND 로 돌아와야 회로가 닫힌다"]},"q":[{"k":"LED 켜기 — 저항을 거쳐서","cat":"internals","q":"13번 핀으로 LED 를 켜는 회로를 만드세요. <b>반드시 220Ω 저항을 거쳐야</b> 하고, LED 의 짧은 다리는 GND 로 가야 합니다.","ex":"저항은 LED 옆에 놓는 게 아니라 전류가 지나가는 길목에 끼워야 합니다. D13 → 저항 → LED(+) → LED(−) → GND 순서로 한 줄이 되어야 해요. 저항을 빼고 바로 이으면 LED 가 탑니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D13","D2","5V","GND"]},{"id":"r","label":"220Ω 저항","pins":["1","2"]},{"id":"led","label":"LED","pins":["+","−"]}],"checks":[{"d":"D13 이 LED 의 + 로 이어진다","link":["uno.D13","led.+"]},{"d":"그 사이에 220Ω 저항이 끼어 있다","link":["uno.D13","led.+"],"through":"r"},{"d":"LED 의 − 가 GND 로 간다","link":["led.−","uno.GND"]},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["uno.D13","r.1"],["r.2","led.+"],["led.−","uno.GND"]]},{"k":"합선 고치기","cat":"internals","q":"누군가 5V 와 GND 를 <b>바로 이어</b> 놓았습니다. 이 선을 지우고, LED 가 <b>5V 로 상시 점등</b>되도록 저항을 거쳐 다시 이으세요.","ex":"5V 와 GND 를 바로 이으면 아무것도 막지 않는 길이 생겨 큰 전류가 흐릅니다(합선). 보드가 보호 회로로 버티더라도 절대 만들면 안 되는 배선이에요. 먼저 그 선을 지운 뒤 저항과 LED 를 사이에 넣으세요.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D13","5V","GND"]},{"id":"r","label":"330Ω 저항","pins":["1","2"]},{"id":"led","label":"LED","pins":["+","−"]}],"checks":[{"d":"5V 와 GND 를 바로 잇는 선이 없다","apart":["uno.5V","uno.GND"],"wires":true},{"d":"5V 가 LED 의 + 로 이어진다","link":["uno.5V","led.+"]},{"d":"그 사이에 저항이 끼어 있다","link":["uno.5V","led.+"],"through":"r"},{"d":"LED 의 − 가 GND 로 간다","link":["led.−","uno.GND"]}],"start":[["uno.5V","uno.GND"]],"sol":[["uno.5V","r.1"],["r.2","led.+"],["led.−","uno.GND"]]}]}],"ord":1},{"t":"입력과 통신","l":[{"t":"센서 읽기","q":[{"t":"choice","k":"함수","q":"온도·빛 같은 아날로그 센서 값을 읽는 함수는?","o":["pinMode()","delay()","analogRead()","digitalWrite()"],"a":2,"ex":"analogRead(A0) 은 0~1023 범위 값을 읽습니다."},{"t":"choice","k":"개념","q":"analogRead() 가 돌려주는 값의 범위는? (10비트)","o":["0~255","0~1023","0~65535","0~1"],"a":1,"ex":"10비트라 0부터 1023까지입니다."},{"t":"choice","k":"함수","q":"버튼처럼 켜짐/꺼짐만 있는 디지털 입력을 읽는 함수는?","o":["digitalRead()","print()","loop()","analogWrite()"],"a":0,"ex":"digitalRead(핀) 은 HIGH 또는 LOW 를 돌려줍니다."},{"t":"choice","k":"부품","q":"빛의 밝기를 감지하는 대표적인 센서는?","o":["저항(resistor)","버저(buzzer)","LED(발광 다이오드)","조도 센서(CDS)"],"a":3,"ex":"조도(빛) 센서로 밝기를 읽어 제어할 수 있습니다."}],"th":{"sum":"센서 값은 아날로그는 `analogRead`(0~1023), 디지털은 `digitalRead`로 읽고, PC와의 통신·디버깅은 `Serial`로 하며 코드를 보드로 옮기는 과정을 **업로드**라 한다.","body":[{"h":"센서 읽기","t":"온도·빛처럼 연속적으로 변하는 아날로그 센서 값은 analogRead(pin) 함수로 읽는다. 아두이노의 ADC는 10비트라서 반환값 범위는 0~1023이다. 버튼처럼 켜짐/꺼짐만 있는 디지털 입력은 digitalRead(pin)로 읽어 HIGH 또는 LOW를 얻는다. 빛의 밝기를 감지하는 대표적 센서는 조도 센서(광센서, CDS/포토레지스터)다."},{"h":"통신과 업로드","t":"아두이노가 PC와 값을 주고받거나 디버깅 메시지를 출력할 때 쓰는 것이 시리얼(Serial) 통신이다. Serial.begin(speed) 함수로 통신을 시작하며 속도(보드레이트, 예: 9600)를 정한다. 작성한 코드를 컴파일해 아두이노 보드로 옮겨 실제로 동작시키는 과정을 업로드(upload)라 한다."}],"code":{"c":"void setup() {\n  Serial.begin(9600);        // 시리얼 통신 시작\n}\nvoid loop() {\n  int v = analogRead(A0);    // 0~1023\n  Serial.println(v);         // PC로 값 출력\n  delay(500);\n}","cap":"아날로그 센서 값을 읽어 시리얼로 출력"},"key":["아날로그 = analogRead(0~1023, 10비트), 디지털 = digitalRead","빛 감지 센서 = 조도 센서(CDS)","PC 통신·디버깅 = Serial, 시작 = Serial.begin(속도), 코드 옮기기 = 업로드"]}},{"t":"통신과 업로드","q":[{"t":"choice","k":"통신","q":"아두이노가 PC 와 값을 주고받거나 디버깅 출력에 쓰는 것은?","o":["Serial","HDMI","USB 마우스","WiFi만"],"a":0,"ex":"Serial.print() 로 PC 화면에 값을 출력해 확인합니다."},{"t":"choice","k":"함수","q":"Serial 통신을 시작하며 속도를 정하는 함수는?","o":["Serial.start()","Serial.begin()","Serial.open()","Serial.on()"],"a":1,"ex":"setup() 에서 Serial.begin(9600) 처럼 시작합니다."},{"t":"choice","k":"과정","q":"작성한 코드를 아두이노 보드로 옮기는 과정을 뭐라 하나요?","o":["컴파일만","백업","업로드","다운로드"],"a":2,"ex":"아두이노 IDE 에서 업로드하면 보드에서 실행됩니다."},{"t":"choice","k":"개념","q":"소리를 내는 데 쓰는 부품은?","o":["점퍼선(전선)","브레드보드(빵판)","저항(레지스터)","버저(피에조)"],"a":3,"ex":"버저로 소리(알람·멜로디)를 낼 수 있습니다."}],"th":{"sum":"센서 값은 아날로그는 `analogRead`(0~1023), 디지털은 `digitalRead`로 읽고, PC와의 통신·디버깅은 `Serial`로 하며 코드를 보드로 옮기는 과정을 **업로드**라 한다.","body":[{"h":"센서 읽기","t":"온도·빛처럼 연속적으로 변하는 아날로그 센서 값은 analogRead(pin) 함수로 읽는다. 아두이노의 ADC는 10비트라서 반환값 범위는 0~1023이다. 버튼처럼 켜짐/꺼짐만 있는 디지털 입력은 digitalRead(pin)로 읽어 HIGH 또는 LOW를 얻는다. 빛의 밝기를 감지하는 대표적 센서는 조도 센서(광센서, CDS/포토레지스터)다."},{"h":"통신과 업로드","t":"아두이노가 PC와 값을 주고받거나 디버깅 메시지를 출력할 때 쓰는 것이 시리얼(Serial) 통신이다. Serial.begin(speed) 함수로 통신을 시작하며 속도(보드레이트, 예: 9600)를 정한다. 작성한 코드를 컴파일해 아두이노 보드로 옮겨 실제로 동작시키는 과정을 업로드(upload)라 한다."}],"code":{"c":"void setup() {\n  Serial.begin(9600);        // 시리얼 통신 시작\n}\nvoid loop() {\n  int v = analogRead(A0);    // 0~1023\n  Serial.println(v);         // PC로 값 출력\n  delay(500);\n}","cap":"아날로그 센서 값을 읽어 시리얼로 출력"},"key":["아날로그 = analogRead(0~1023, 10비트), 디지털 = digitalRead","빛 감지 센서 = 조도 센서(CDS)","PC 통신·디버깅 = Serial, 시작 = Serial.begin(속도), 코드 옮기기 = 업로드"]}},{"t":"직접 이어 보기 — 버튼 읽기","th":{"sum":"입력 핀은 아무것도 연결되지 않으면 **값이 떠다닌다**(플로팅). 0도 1도 아닌 상태라 읽을 때마다 달라진다.","body":[{"h":"풀다운·풀업 저항","t":"버튼을 누르지 않았을 때 핀을 확실한 값으로 붙잡아 두는 저항이다. 10kΩ 을 GND 로 걸면 평소 LOW(풀다운), 5V 로 걸면 평소 HIGH(풀업)다. 이게 없으면 손을 가까이 대는 것만으로도 값이 바뀐다."},{"h":"내장 풀업","t":"`pinMode(2, INPUT_PULLUP)` 을 쓰면 보드 안의 저항이 붙어 배선이 하나 줄어든다. 대신 **눌렀을 때 LOW** 가 되어 논리가 뒤집힌다 — 이걸 모르면 버튼이 거꾸로 동작한다."}],"code":{"c":"pinMode(2, INPUT_PULLUP);\nif (digitalRead(2) == LOW) { /* 눌림 */ }\n// 내장 풀업은 눌렀을 때 LOW 다","cap":"안 눌렀을 때의 값을 정해 둬야 한다"},"key":["아무것도 안 걸면 값이 떠다닌다","풀다운은 평소 LOW, 풀업은 평소 HIGH","내장 풀업은 논리가 뒤집힌다"]},"q":[{"k":"버튼 + 풀다운 저항","cat":"internals","q":"2번 핀으로 버튼을 읽는 회로를 만드세요. 버튼을 누르면 <b>5V 가 2번 핀에</b> 닿고, 안 눌렀을 때는 <b>10kΩ 저항을 거쳐 GND</b> 로 붙잡혀 있어야 합니다.","ex":"풀다운 저항이 없으면 버튼을 안 눌렀을 때 2번 핀이 아무 데도 연결되지 않아 값이 떠다닙니다. 저항을 GND 로 걸어 평소 LOW 로 붙잡아 둬야 해요. 저항 없이 GND 에 바로 이으면 버튼을 눌렀을 때 5V 와 GND 가 합선됩니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D2","5V","GND"]},{"id":"btn","label":"버튼","pins":["1","2"],"noInternal":true},{"id":"rd","label":"10kΩ 풀다운","pins":["1","2"]}],"checks":[{"d":"버튼 한쪽이 5V 에 붙는다","link":["btn.1","uno.5V"]},{"d":"버튼 다른 쪽이 2번 핀으로 간다","link":["btn.2","uno.D2"]},{"d":"2번 핀이 저항을 거쳐 GND 로 붙잡힌다","link":["uno.D2","uno.GND"],"through":"rd"},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["btn.1","uno.5V"],["btn.2","uno.D2"],["uno.D2","rd.1"],["rd.2","uno.GND"]]},{"k":"내장 풀업으로 배선 줄이기","cat":"internals","q":"<code>INPUT_PULLUP</code> 을 쓰면 외부 저항이 필요 없습니다. 버튼 한쪽을 <b>3번 핀</b>에, 다른 쪽을 <b>GND</b> 에 이으세요. 5V 는 쓰지 않습니다.","ex":"내장 풀업은 보드 안에서 핀을 5V 쪽으로 붙잡아 둡니다. 그래서 버튼은 GND 로만 내리면 되고, 누르면 LOW 가 돼요 — 논리가 뒤집히는 것을 코드에서 감안해야 합니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D3","5V","GND"]},{"id":"btn","label":"버튼","pins":["1","2"],"noInternal":true}],"checks":[{"d":"버튼 한쪽이 3번 핀에 붙는다","link":["btn.1","uno.D3"]},{"d":"버튼 다른 쪽이 GND 로 간다","link":["btn.2","uno.GND"]},{"d":"5V 는 쓰지 않는다","apart":["uno.5V","uno.D3"],"wires":true},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["btn.1","uno.D3"],["btn.2","uno.GND"]]}]}],"ord":2},{"t":"디지털·아날로그 입출력과 PWM 듀티 제어","l":[{"t":"핀 모드와 디지털 입력의 함정","q":[{"t":"choice","k":"uno-pinmode-output-basic","q":"Arduino Uno에서 13번 핀에 LED를 연결해 켜고 끄려 합니다. setup()에 넣어야 할 코드로 가장 알맞은 것은?","ex":"핀에서 전압을 내보내려면 pinMode로 OUTPUT을 지정해야 하며, INPUT은 읽기 전용 설정입니다.\n💡 개념: pinMode는 핀 방향(입력/출력)을 정하고, digitalWrite는 그 출력 핀에 HIGH/LOW를 씁니다.\n🛠 실무: 출력 지정을 빼먹으면 LED가 아주 흐리게만 켜지는 이상 증상이 나와 배선을 의심하다 시간을 버리기 쉽습니다.","o":["digitalRead(13, OUTPUT);","pinMode(13, INPUT);","pinMode(13, OUTPUT);","analogWrite(13, OUTPUT);"],"a":2},{"t":"choice","k":"uno-input-pullup-press-level","q":"버튼 한쪽을 Uno의 4번 핀, 반대쪽을 GND에 연결하고 pinMode(4, INPUT_PULLUP)을 했습니다. 버튼을 눌렀을 때 digitalRead(4)의 값은?","ex":"내부 풀업이 평소 핀을 5V로 당겨 HIGH이고, 버튼을 누르면 핀이 GND에 연결되어 LOW로 떨어집니다.\n💡 개념: INPUT_PULLUP은 눌림이 LOW인 액티브 로우 논리이므로 조건문을 == LOW로 써야 합니다.\n🛠 실무: 외부 풀업 저항을 따로 달지 않아도 되어 배선이 줄고, 플로팅 오동작도 함께 사라집니다.","o":["1023","HIGH","LOW","누를 때마다 무작위"],"a":2},{"t":"choice","k":"uno-pullup-resistor-need","q":"INPUT_PULLUP 대신 pinMode(4, INPUT)만 쓰면서 버튼을 GND에 연결한 회로를 안정적으로 만들려면 추가로 필요한 것은?","ex":"내부 풀업을 쓰지 않는다면 핀과 5V 사이에 외부 풀업 저항을 달아 평소 HIGH를 만들어 줘야 합니다.\n💡 개념: INPUT_PULLUP은 ATmega328P 칩 안에 있는 풀업 저항을 소프트웨어로 켜는 것과 같습니다.\n🛠 실무: 긴 배선이나 노이즈가 심한 환경에서는 값이 작은 외부 풀업이 내부 풀업보다 더 안정적입니다.","o":["Serial.begin의 보율을 115200으로 올린다","핀과 5V 사이에 외부 풀업 저항을 단다","PWM 가능 핀으로 버튼을 옮긴다","analogRead로 버튼을 읽는다"],"a":1},{"t":"choice","k":"uno-floating-input-cause","q":"Uno의 2번 핀을 pinMode(2, INPUT)으로 두고 아무것도 연결하지 않은 채 digitalRead(2)를 반복하면 값이 HIGH와 LOW를 마구 오갑니다. 원인은?","ex":"연결이 없는 입력 핀은 주변 노이즈에 따라 전압이 떠다니는 플로팅 상태가 되어 값이 불안정합니다.\n💡 개념: 디지털 입력은 반드시 HIGH나 LOW 어느 한쪽으로 확정시켜 줄 풀업 또는 풀다운이 필요합니다.\n🛠 실무: 스위치 입력이 가끔 저절로 눌린 것처럼 동작하면 가장 먼저 플로팅을 의심하세요.","o":["핀이 어디에도 연결되지 않아 전압이 떠 있는 플로팅 상태이기 때문","digitalRead 는 원래 난수를 반환하도록 설계된 함수이기 때문","2번 핀이 PWM 전용 핀이라 디지털 읽기가 불가능하기 때문","10비트 ADC의 양자화 오차가 디지털 입력에 섞이기 때문"],"a":0},{"t":"input","k":"uno-pullup-mode-name","q":"Arduino Uno에서 내부 풀업 저항을 켜서 플로팅을 막는 pinMode의 세 번째 인자(모드) 이름을 그대로 적어보세요. (예: 영문 대문자 또는 소문자)","ex":"정답은 INPUT_PULLUP이며 pinMode(pin, INPUT_PULLUP) 형태로 씁니다.\n💡 개념: 이 모드를 쓰면 평소 HIGH, 버튼을 누르면 LOW로 읽히는 액티브 로우 구조가 됩니다.\n🛠 실무: 버튼 입력 코드는 대부분 INPUT_PULLUP을 기본으로 쓰고 회로에서 저항을 생략합니다.","a":["INPUT_PULLUP","input_pullup","INPUT PULLUP","인풋 풀업"]}],"th":{"sum":"Arduino Uno(ATmega328P)의 핀은 디지털 HIGH/LOW 입출력과 10비트 ADC 입력, 8비트 PWM 출력을 담당합니다. PWM은 평균 전압을 흉내 낼 뿐 진짜 아날로그 출력(DAC)이 아니라는 점이 핵심입니다.","body":[{"h":"pinMode와 디지털 입출력","t":"Arduino Uno에서 핀은 pinMode(pin, OUTPUT)으로 출력, INPUT 또는 INPUT_PULLUP으로 입력이 됩니다. 출력 핀은 digitalWrite(pin, HIGH/LOW)로 5V 또는 0V를 내보냅니다. 입력 핀은 digitalRead(pin)으로 HIGH(1) 또는 LOW(0)만 읽습니다. 즉 디지털 입출력에는 중간값이 없습니다."},{"h":"플로팅 입력과 INPUT_PULLUP","t":"아무 데도 연결되지 않은 입력 핀은 전압이 떠다니며(floating) HIGH와 LOW를 제멋대로 오갑니다. pinMode(pin, INPUT_PULLUP)을 쓰면 ATmega328P 내부 풀업 저항이 켜져 평소 핀이 5V 쪽으로 당겨져 HIGH로 고정됩니다. 버튼의 반대편을 GND에 연결했다면 버튼을 눌렀을 때 핀이 GND로 떨어져 LOW로 읽힙니다. 그래서 INPUT_PULLUP 버튼 코드는 눌림을 LOW로 판정합니다."},{"h":"analogRead는 10비트 ADC","t":"Uno의 A0~A5는 10비트 ADC에 연결되어 analogRead()가 0~1023의 정수를 돌려줍니다. 기준 전압이 5V일 때 한 단계는 약 5V / 1024 = 약 4.9mV입니다. 전압으로 바꾸려면 value * 5.0 / 1023.0 같은 식을 씁니다. analogRead는 값을 읽는 입력 전용이며 출력과는 무관합니다."},{"h":"analogWrite는 8비트 PWM 듀티","t":"analogWrite(pin, 0~255)는 8비트 듀티비를 지정해 핀을 아주 빠르게 켜고 끕니다. 128이면 대략 50% 시간만 HIGH라 LED가 절반 밝기로 보이고 평균 전압이 약 2.5V처럼 측정됩니다. 하지만 순간 전압은 여전히 0V 아니면 5V이므로 진짜 아날로그 전압을 만드는 DAC와 다릅니다. Uno에서 PWM이 가능한 핀은 3, 5, 6, 9, 10, 11뿐이고 나머지 디지털 핀에 analogWrite를 하면 의도한 밝기 조절이 되지 않습니다."}],"code":{"c":"const int BTN = 2;   // 버튼: 한쪽은 핀2, 반대쪽은 GND\nconst int LED = 9;   // Uno PWM 가능 핀\n\nvoid setup() {\n  pinMode(BTN, INPUT_PULLUP); // 내부 풀업 ON, 평소 HIGH\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);          // 0~1023 (10비트)\n  int duty = map(raw, 0, 1023, 0, 255); // 0~255 (8비트 PWM)\n  if (digitalRead(BTN) == LOW) duty = 0; // 눌리면 LOW\n  analogWrite(LED, duty);\n  Serial.println(raw * 5.0 / 1023.0); // 전압 환산\n}","cap":"가변저항 값을 10비트로 읽어 8비트 PWM 듀티로 바꿔 LED 밝기를 조절하고, INPUT_PULLUP 버튼으로 끕니다."},"key":["analogRead는 10비트라 0~1023을 반환하고 5V 기준 한 단계는 약 4.9mV다","analogWrite는 0~255의 8비트 듀티이며 PWM은 평균 전압일 뿐 DAC가 아니다","Uno의 PWM 핀은 3, 5, 6, 9, 10, 11로 제한된다","INPUT_PULLUP은 플로팅을 막고 GND에 연결된 버튼이 눌릴 때 LOW로 읽히게 한다"]}},{"t":"analogRead 10비트와 전압 분해능","q":[{"t":"choice","k":"uno-analogread-range","q":"Arduino Uno에서 analogRead(A0)가 반환할 수 있는 값의 범위는?","ex":"Uno의 ADC는 10비트라 2의 10승인 1024단계, 즉 0부터 1023까지의 정수를 반환합니다.\n💡 개념: 0~255는 analogWrite의 8비트 듀티 범위이고, 0~4095는 12비트 ADC를 가진 다른 보드의 값입니다.\n🛠 실무: 보드를 ESP32 등으로 옮기면 ADC 비트 수가 달라지므로 1023을 상수로 박아둔 코드는 반드시 다시 확인해야 합니다.","o":["0 ~ 65535","0 ~ 1023","0 ~ 4095","0 ~ 255"],"a":1},{"t":"choice","k":"uno-analogread-digital-pin","q":"Uno에서 디지털 핀 7에 연결된 스위치의 온오프 상태를 읽으려 합니다. 가장 알맞은 함수는?","ex":"온오프 두 상태만 필요하므로 HIGH/LOW를 돌려주는 digitalRead가 알맞습니다.\n💡 개념: analogRead는 A0~A5의 아날로그 입력 핀에서 연속적인 전압을 0~1023으로 읽을 때 씁니다.\n🛠 실무: 아날로그 핀 A0~A5도 digitalRead로 디지털 입력처럼 쓸 수 있어 핀이 모자랄 때 유용합니다.","o":["digitalRead(7)","pinMode(7, HIGH)","analogRead(7)","analogWrite(7, 255)"],"a":0},{"t":"choice","k":"uno-adc-step-voltage","q":"기준 전압이 5V인 Uno에서 10비트 analogRead 한 단계(LSB)에 해당하는 전압은 대략 얼마입니까?","ex":"5V를 1024단계로 나누면 한 단계는 약 0.00488V, 즉 약 4.9mV입니다.\n💡 개념: 약 19.6mV는 5V를 256단계로 나눈 8비트 분해능이라 Uno의 ADC와 다릅니다.\n🛠 실무: 더 미세한 전압을 봐야 하면 analogReference로 기준 전압을 1.1V 내부 기준으로 낮추거나 외부 ADC를 씁니다.","o":["약 5V","약 0.5V","약 19.6mV","약 4.9mV"],"a":3},{"t":"choice","k":"uno-adc-to-voltage-calc","q":"5V 기준 Uno에서 analogRead(A0)가 512를 반환했습니다. 입력 전압은 대략 얼마입니까?","ex":"512는 0~1023 범위의 거의 정확한 중간이므로 5V의 절반인 약 2.5V입니다.\n💡 개념: 전압 = 값 * 5.0 / 1023.0 식으로 환산하며 512는 약 2.50V가 나옵니다.\n🛠 실무: 전압 분배 회로로 5V가 넘는 신호를 낮춰 넣을 때는 분배비를 곱해 원래 전압으로 되돌려야 합니다.","o":["약 5.0V","약 3.3V","약 2.5V","약 0.5V"],"a":2},{"t":"choice","k":"uno-adc-resolution-meaning","q":"같은 5V 범위를 10비트 ADC 대신 8비트 ADC로 읽으면 생기는 변화로 옳은 것은?","ex":"비트 수는 전압 범위가 아니라 그 범위를 몇 단계로 쪼개는지를 결정하므로 256단계로 거칠어집니다.\n💡 개념: 분해능이 낮아지면 작은 전압 변화가 같은 숫자로 뭉뚱그려져 감지되지 않습니다.\n🛠 실무: 미세한 센서 변화를 봐야 하는 계측 프로젝트에서는 ADC 비트 수가 곧 성능 한계가 됩니다.","o":["전압을 아예 읽지 못하고 HIGH/LOW만 나온다","샘플 값이 0~1023에서 0~2047로 늘어난다","단계 수가 1024에서 256으로 줄어 한 단계당 전압 폭이 커진다","측정할 수 있는 최대 전압이 5V 에서 2.5V 로 절반으로 줄어든다"],"a":2}],"th":{"sum":"Arduino Uno(ATmega328P)의 핀은 디지털 HIGH/LOW 입출력과 10비트 ADC 입력, 8비트 PWM 출력을 담당합니다. PWM은 평균 전압을 흉내 낼 뿐 진짜 아날로그 출력(DAC)이 아니라는 점이 핵심입니다.","body":[{"h":"pinMode와 디지털 입출력","t":"Arduino Uno에서 핀은 pinMode(pin, OUTPUT)으로 출력, INPUT 또는 INPUT_PULLUP으로 입력이 됩니다. 출력 핀은 digitalWrite(pin, HIGH/LOW)로 5V 또는 0V를 내보냅니다. 입력 핀은 digitalRead(pin)으로 HIGH(1) 또는 LOW(0)만 읽습니다. 즉 디지털 입출력에는 중간값이 없습니다."},{"h":"플로팅 입력과 INPUT_PULLUP","t":"아무 데도 연결되지 않은 입력 핀은 전압이 떠다니며(floating) HIGH와 LOW를 제멋대로 오갑니다. pinMode(pin, INPUT_PULLUP)을 쓰면 ATmega328P 내부 풀업 저항이 켜져 평소 핀이 5V 쪽으로 당겨져 HIGH로 고정됩니다. 버튼의 반대편을 GND에 연결했다면 버튼을 눌렀을 때 핀이 GND로 떨어져 LOW로 읽힙니다. 그래서 INPUT_PULLUP 버튼 코드는 눌림을 LOW로 판정합니다."},{"h":"analogRead는 10비트 ADC","t":"Uno의 A0~A5는 10비트 ADC에 연결되어 analogRead()가 0~1023의 정수를 돌려줍니다. 기준 전압이 5V일 때 한 단계는 약 5V / 1024 = 약 4.9mV입니다. 전압으로 바꾸려면 value * 5.0 / 1023.0 같은 식을 씁니다. analogRead는 값을 읽는 입력 전용이며 출력과는 무관합니다."},{"h":"analogWrite는 8비트 PWM 듀티","t":"analogWrite(pin, 0~255)는 8비트 듀티비를 지정해 핀을 아주 빠르게 켜고 끕니다. 128이면 대략 50% 시간만 HIGH라 LED가 절반 밝기로 보이고 평균 전압이 약 2.5V처럼 측정됩니다. 하지만 순간 전압은 여전히 0V 아니면 5V이므로 진짜 아날로그 전압을 만드는 DAC와 다릅니다. Uno에서 PWM이 가능한 핀은 3, 5, 6, 9, 10, 11뿐이고 나머지 디지털 핀에 analogWrite를 하면 의도한 밝기 조절이 되지 않습니다."}],"code":{"c":"const int BTN = 2;   // 버튼: 한쪽은 핀2, 반대쪽은 GND\nconst int LED = 9;   // Uno PWM 가능 핀\n\nvoid setup() {\n  pinMode(BTN, INPUT_PULLUP); // 내부 풀업 ON, 평소 HIGH\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);          // 0~1023 (10비트)\n  int duty = map(raw, 0, 1023, 0, 255); // 0~255 (8비트 PWM)\n  if (digitalRead(BTN) == LOW) duty = 0; // 눌리면 LOW\n  analogWrite(LED, duty);\n  Serial.println(raw * 5.0 / 1023.0); // 전압 환산\n}","cap":"가변저항 값을 10비트로 읽어 8비트 PWM 듀티로 바꿔 LED 밝기를 조절하고, INPUT_PULLUP 버튼으로 끕니다."},"key":["analogRead는 10비트라 0~1023을 반환하고 5V 기준 한 단계는 약 4.9mV다","analogWrite는 0~255의 8비트 듀티이며 PWM은 평균 전압일 뿐 DAC가 아니다","Uno의 PWM 핀은 3, 5, 6, 9, 10, 11로 제한된다","INPUT_PULLUP은 플로팅을 막고 GND에 연결된 버튼이 눌릴 때 LOW로 읽히게 한다"]}},{"t":"PWM 듀티와 DAC의 차이","q":[{"t":"choice","k":"uno-analogwrite-range","q":"Arduino Uno에서 analogWrite(9, x)의 x가 가질 수 있는 값의 범위는?","ex":"analogWrite는 8비트 듀티를 받으므로 0부터 255까지이며 255가 항상 HIGH(듀티 100%)입니다.\n💡 개념: 0~1023은 analogRead의 10비트 입력 범위라 방향이 반대입니다.\n🛠 실무: analogRead 값을 그대로 analogWrite에 넣으면 값이 잘리므로 map(raw, 0, 1023, 0, 255)로 변환합니다.","o":["0 ~ 1023","0 ~ 255","0 ~ 5","0 ~ 100"],"a":1},{"t":"choice","k":"uno-pwm-pin-list","q":"Arduino Uno에서 analogWrite로 PWM 출력이 가능한 핀들만 모아 놓은 것은?","ex":"Uno에서 PWM은 타이머에 연결된 3, 5, 6, 9, 10, 11번 핀에서만 나오며 보드에도 물결 표시가 되어 있습니다.\n💡 개념: A0~A5는 아날로그 입력 핀이지 PWM 출력 핀이 아닙니다.\n🛠 실무: PWM 아닌 핀에 analogWrite를 하면 값이 128 미만은 LOW, 이상은 HIGH로만 나와 밝기 조절이 안 됩니다.","o":["0, 1, 2, 4, 7, 8","0번부터 13번까지 모든 디지털 핀","3, 5, 6, 9, 10, 11","A0 ~ A5 전부"],"a":2},{"t":"choice","k":"uno-pwm-not-dac","q":"analogWrite(9, 128)을 실행한 Uno의 9번 핀을 오실로스코프로 관찰했습니다. 실제 파형에 대한 설명으로 옳은 것은?","ex":"PWM은 디지털 핀을 빠르게 켜고 꺼서 평균 전압을 조절하는 방식이라 순간 전압은 0V 아니면 5V입니다.\n💡 개념: 듀티 128/255는 약 50%이므로 평균값이 약 2.5V로 측정될 뿐 진짜 2.5V가 아닙니다.\n🛠 실무: 실제 아날로그 전압이 필요하면 RC 저역통과 필터를 붙이거나 MCP4725 같은 외부 DAC를 씁니다.","o":["0V와 5V를 빠르게 오가며 약 절반의 시간만 HIGH인 사각파가 나온다","핀이 계속 정확히 2.5V 를 유지하는 평평한 직류 전압이 그대로 유지되어 나온다","핀이 HIGH로 고정되고 전류만 절반으로 제한된다","0V에서 5V까지 부드럽게 오르내리는 사인파가 나온다"],"a":0},{"t":"input","k":"uno-pwm-duty-half-value","q":"Uno에서 LED를 대략 50% 밝기로 만들려면 analogWrite(9, ?)의 물음표에 넣을 값은 얼마입니까? (0~255 범위의 숫자로 답하세요)","ex":"0~255의 절반은 약 127~128이므로 128을 넣으면 듀티가 약 50%가 됩니다.\n💡 개념: 듀티비 = 값 / 255이며 255는 100%, 0은 0%입니다.\n🛠 실무: 사람 눈은 밝기를 로그처럼 느껴 듀티 50%가 절반 밝기로 보이지 않으므로 감마 보정 테이블을 쓰기도 합니다.","a":["128","127","127.5","약 128"]},{"t":"choice","k":"uno-dac-vs-pwm-choice","q":"센서 교정용으로 정확한 1.8V 직류를 만들어 다른 장비에 넣어야 합니다. Uno만 가지고 있을 때 가장 적절한 접근은?","ex":"Uno에는 진짜 DAC가 없으므로 PWM을 RC 필터로 평활하거나 외부 DAC를 붙여야 안정된 직류를 얻습니다.\n💡 개념: analogRead는 입력 전용이고 digitalWrite 반복은 결국 필터 없는 PWM과 같습니다.\n🛠 실무: RC 필터는 응답이 느려지므로 빠른 파형이 필요하면 I2C나 SPI로 붙는 DAC 칩이 낫습니다.","o":["analogWrite로 듀티를 맞추면 그 자체로 정확한 1.8V 직류가 나오므로 그대로 쓴다","digitalWrite(9, HIGH)를 아주 짧게 반복 호출해 전압을 낮춘다","analogRead(A0)를 반복 호출하면 A0에 1.8V가 출력된다","PWM 출력에 RC 저역통과 필터를 달거나 외부 DAC 모듈을 사용한다"],"a":3}],"th":{"sum":"Arduino Uno(ATmega328P)의 핀은 디지털 HIGH/LOW 입출력과 10비트 ADC 입력, 8비트 PWM 출력을 담당합니다. PWM은 평균 전압을 흉내 낼 뿐 진짜 아날로그 출력(DAC)이 아니라는 점이 핵심입니다.","body":[{"h":"pinMode와 디지털 입출력","t":"Arduino Uno에서 핀은 pinMode(pin, OUTPUT)으로 출력, INPUT 또는 INPUT_PULLUP으로 입력이 됩니다. 출력 핀은 digitalWrite(pin, HIGH/LOW)로 5V 또는 0V를 내보냅니다. 입력 핀은 digitalRead(pin)으로 HIGH(1) 또는 LOW(0)만 읽습니다. 즉 디지털 입출력에는 중간값이 없습니다."},{"h":"플로팅 입력과 INPUT_PULLUP","t":"아무 데도 연결되지 않은 입력 핀은 전압이 떠다니며(floating) HIGH와 LOW를 제멋대로 오갑니다. pinMode(pin, INPUT_PULLUP)을 쓰면 ATmega328P 내부 풀업 저항이 켜져 평소 핀이 5V 쪽으로 당겨져 HIGH로 고정됩니다. 버튼의 반대편을 GND에 연결했다면 버튼을 눌렀을 때 핀이 GND로 떨어져 LOW로 읽힙니다. 그래서 INPUT_PULLUP 버튼 코드는 눌림을 LOW로 판정합니다."},{"h":"analogRead는 10비트 ADC","t":"Uno의 A0~A5는 10비트 ADC에 연결되어 analogRead()가 0~1023의 정수를 돌려줍니다. 기준 전압이 5V일 때 한 단계는 약 5V / 1024 = 약 4.9mV입니다. 전압으로 바꾸려면 value * 5.0 / 1023.0 같은 식을 씁니다. analogRead는 값을 읽는 입력 전용이며 출력과는 무관합니다."},{"h":"analogWrite는 8비트 PWM 듀티","t":"analogWrite(pin, 0~255)는 8비트 듀티비를 지정해 핀을 아주 빠르게 켜고 끕니다. 128이면 대략 50% 시간만 HIGH라 LED가 절반 밝기로 보이고 평균 전압이 약 2.5V처럼 측정됩니다. 하지만 순간 전압은 여전히 0V 아니면 5V이므로 진짜 아날로그 전압을 만드는 DAC와 다릅니다. Uno에서 PWM이 가능한 핀은 3, 5, 6, 9, 10, 11뿐이고 나머지 디지털 핀에 analogWrite를 하면 의도한 밝기 조절이 되지 않습니다."}],"code":{"c":"const int BTN = 2;   // 버튼: 한쪽은 핀2, 반대쪽은 GND\nconst int LED = 9;   // Uno PWM 가능 핀\n\nvoid setup() {\n  pinMode(BTN, INPUT_PULLUP); // 내부 풀업 ON, 평소 HIGH\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);          // 0~1023 (10비트)\n  int duty = map(raw, 0, 1023, 0, 255); // 0~255 (8비트 PWM)\n  if (digitalRead(BTN) == LOW) duty = 0; // 눌리면 LOW\n  analogWrite(LED, duty);\n  Serial.println(raw * 5.0 / 1023.0); // 전압 환산\n}","cap":"가변저항 값을 10비트로 읽어 8비트 PWM 듀티로 바꿔 LED 밝기를 조절하고, INPUT_PULLUP 버튼으로 끕니다."},"key":["analogRead는 10비트라 0~1023을 반환하고 5V 기준 한 단계는 약 4.9mV다","analogWrite는 0~255의 8비트 듀티이며 PWM은 평균 전압일 뿐 DAC가 아니다","Uno의 PWM 핀은 3, 5, 6, 9, 10, 11로 제한된다","INPUT_PULLUP은 플로팅을 막고 GND에 연결된 버튼이 눌릴 때 LOW로 읽히게 한다"]}},{"t":"직접 이어 보기 — 아날로그 입력과 PWM","th":{"sum":"아날로그 입력(A0~)은 0~5V 를 0~1023 숫자로 읽는다. PWM 출력(~ 표시 핀)은 켜고 끄기를 빠르게 반복해 밝기를 흉내 낸다.","body":[{"h":"가변저항의 세 다리","t":"양끝은 5V 와 GND 에 걸고, 가운데(와이퍼)를 아날로그 핀으로 보낸다. 손잡이를 돌리면 가운데 전압이 0~5V 사이에서 움직인다. 양끝을 거꾸로 걸면 방향만 반대가 되고, **가운데를 안 걸면** 값이 떠다닌다."},{"h":"PWM 은 진짜 아날로그가 아니다","t":"`analogWrite(9, 128)` 은 절반쯤 켜 두는 것이 아니라, 아주 빠르게 켰다 껐다 해서 절반처럼 보이게 하는 것이다. LED 밝기나 모터 속도에는 잘 맞지만, 진짜 전압이 필요한 곳에는 못 쓴다."}],"code":{"c":"int v = analogRead(A0);        // 0~1023\nanalogWrite(9, v / 4);         // 0~255\n// 9번은 ~ 가 붙은 PWM 핀이어야 한다","cap":"읽은 값의 범위와 쓰는 값의 범위가 다르다"},"key":["가변저항 가운데를 아날로그 핀으로","PWM 은 빠르게 껐다 켜는 것","`analogRead` 0~1023, `analogWrite` 0~255"]},"q":[{"k":"가변저항으로 밝기 조절","cat":"internals","q":"가변저항으로 LED 밝기를 조절하는 회로를 만드세요. 가변저항 양끝은 <b>5V·GND</b>, 가운데는 <b>A0</b> 로 보내고, LED 는 <b>PWM 핀 D9</b> 에서 저항을 거쳐 켭니다.","ex":"가변저항은 양끝에 전압을 걸어 두고 가운데에서 나눠진 전압을 꺼내 쓰는 부품입니다. 양끝 중 하나만 걸거나 가운데를 안 걸면 A0 값이 떠다녀요. LED 쪽은 D13 과 똑같이 저항을 직렬로 끼웁니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A0","D9","5V","GND"]},{"id":"pot","label":"가변저항","pins":["1","W","3"]},{"id":"r","label":"220Ω 저항","pins":["1","2"]},{"id":"led","label":"LED","pins":["+","−"]}],"checks":[{"d":"가변저항 한쪽 끝이 5V 에 붙는다","link":["pot.1","uno.5V"]},{"d":"다른 쪽 끝이 GND 에 붙는다","link":["pot.3","uno.GND"]},{"d":"가운데(W)가 A0 로 간다","link":["pot.W","uno.A0"]},{"d":"D9 가 저항을 거쳐 LED 로 간다","link":["uno.D9","led.+"],"through":"r"},{"d":"LED 의 − 가 GND 로 간다","link":["led.−","uno.GND"]}],"start":[],"sol":[["pot.1","uno.5V"],["pot.3","uno.GND"],["pot.W","uno.A0"],["uno.D9","r.1"],["r.2","led.+"],["led.−","uno.GND"]]},{"k":"잘못된 배선 고치기 — 가운데를 안 걸었다","cat":"internals","q":"가변저항의 <b>가운데 다리가 A0 가 아니라 5V 에</b> 잘못 이어져 있습니다. 잘못된 선을 지우고 바르게 이으세요.","ex":"가운데를 5V 에 붙이면 손잡이를 돌려도 A0 값이 변하지 않습니다. 게다가 가운데와 한쪽 끝이 같은 전위가 되어 그 구간이 합선처럼 동작해요. 가운데는 반드시 읽을 핀으로 보냅니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A0","5V","GND"]},{"id":"pot","label":"가변저항","pins":["1","W","3"]}],"checks":[{"d":"가운데(W)가 A0 로 간다","link":["pot.W","uno.A0"]},{"d":"가운데가 5V 에 직접 붙어 있지 않다","apart":["pot.W","uno.5V"],"wires":true},{"d":"한쪽 끝이 5V 에 붙는다","link":["pot.1","uno.5V"]},{"d":"다른 쪽 끝이 GND 에 붙는다","link":["pot.3","uno.GND"]}],"start":[["pot.1","uno.5V"],["pot.3","uno.GND"],["pot.W","uno.5V"]],"sol":[["pot.1","uno.5V"],["pot.3","uno.GND"],["pot.W","uno.A0"]]}]}],"ord":3},{"t":"센서 폴링·외부 인터럽트·millis 논블로킹 타이밍","l":[{"t":"폴링 대신 인터럽트를 쓰는 순간","q":[{"t":"choice","k":"uno-interrupt-pins-list","q":"Arduino Uno에서 attachInterrupt로 외부 인터럽트를 붙일 수 있는 디지털 핀은?","ex":"Uno(ATmega328P)의 외부 인터럽트 INT0/INT1은 디지털 2번과 3번 핀에 연결되어 있습니다.\n💡 개념: 0번과 1번은 UART의 RX/TX로 쓰이고 인터럽트 번호가 아닙니다.\n🛠 실무: 다른 핀에서 변화를 감지하려면 핀 체인지 인터럽트나 관련 라이브러리를 써야 합니다.","o":["0번과 1번","2번과 3번","9번과 10번","13번 하나뿐"],"a":1},{"t":"choice","k":"uno-polling-definition","q":"Arduino Uno에서 loop() 안에서 digitalRead(2)를 계속 호출해 버튼이 눌렸는지 반복 확인하는 방식을 무엇이라 합니까?","ex":"코드가 주기적으로 상태를 직접 확인하는 방식이 폴링이며 인터럽트와 대비됩니다.\n💡 개념: 인터럽트는 반대로 하드웨어가 변화를 감지해 코드를 불러 주는 방식입니다.\n🛠 실무: 폴링은 구현이 단순하지만 loop()가 오래 걸리는 작업에 묶이면 짧은 신호를 놓칠 수 있습니다.","o":["인터럽트(interrupt)","폴링(polling)","슬립 모드(sleep mode)","디바운싱(debouncing)"],"a":1},{"t":"choice","k":"uno-interrupt-use-case","q":"회전 인코더가 아주 짧은 펄스를 빠르게 보내는데 loop()에서 다른 계산도 해야 합니다. 펄스를 놓치지 않으려면?","ex":"짧은 펄스는 폴링 주기 사이에 사라질 수 있으므로 하드웨어가 즉시 잡아 주는 인터럽트가 적합합니다.\n💡 개념: 인터럽트는 실행 중인 코드를 잠시 멈추고 ISR로 뛰어들기 때문에 타이밍이 급한 이벤트에 강합니다.\n🛠 실무: 인코더, 유량계, 타코미터처럼 펄스를 세는 장치는 대부분 인터럽트로 구현합니다.","o":["loop() 안에 delay(1) 을 넣어 루프가 도는 속도를 일정하게 맞춘다","Serial 보율을 300으로 낮춰 CPU 부담을 줄인다","analogRead로 펄스를 읽어 임계값과 비교한다","펄스 핀을 인터럽트 핀에 연결하고 attachInterrupt로 카운트한다"],"a":3},{"t":"choice","k":"uno-attachinterrupt-helper","q":"attachInterrupt에 핀 번호를 전달할 때 2 대신 digitalPinToInterrupt(2)를 쓰는 이유로 가장 알맞은 것은?","ex":"보드마다 핀 번호와 인터럽트 번호의 대응이 달라 이를 변환해 주는 매크로가 digitalPinToInterrupt입니다.\n💡 개념: 속도나 디바운싱과는 무관하며 순수하게 번호 매핑용입니다.\n🛠 실무: 이 매크로를 쓰면 Uno에서 Leonardo나 Mega로 옮겨도 코드를 고칠 필요가 줄어듭니다.","o":["인터럽트 처리 속도가 두 배 빨라지기 때문","ISR 안에서도 delay() 함수를 문제없이 쓸 수 있게 해 주기 때문","핀 번호를 보드에 맞는 인터럽트 번호로 변환해 이식성을 지켜 주기 때문","그 함수가 자동으로 디바운싱까지 처리해 주기 때문"],"a":2},{"t":"input","k":"uno-isr-shared-var-keyword","q":"ISR과 loop()가 함께 접근하는 전역 변수 앞에 반드시 붙여야 하는 C++ 키워드는 무엇입니까? (영문 소문자로 입력)","ex":"정답은 volatile로, 컴파일러가 변수 값을 레지스터에 캐시하지 않고 매번 메모리에서 읽게 만듭니다.\n💡 개념: volatile이 없으면 ISR이 값을 바꿔도 loop()가 옛 값을 계속 보는 버그가 생깁니다.\n🛠 실무: 여러 바이트 변수는 volatile만으로 부족해 읽는 동안 noInterrupts()로 잠깐 막아 주기도 합니다.","a":["volatile","VOLATILE","볼라타일"]}],"th":{"sum":"Arduino Uno에서 이벤트를 놓치지 않으려면 폴링과 인터럽트의 차이를 알아야 하고, delay()의 블로킹 특성을 millis() 패턴으로 대체해야 합니다. ISR은 짧게 쓰고 공유 변수는 volatile로 선언합니다.","body":[{"h":"폴링과 인터럽트","t":"폴링은 loop()에서 digitalRead를 반복해 상태가 변했는지 계속 확인하는 방식입니다. 코드가 다른 일로 바쁠 때 짧게 지나가는 신호는 폴링으로 놓칠 수 있습니다. 인터럽트는 하드웨어가 신호 변화를 감지해 현재 실행 중인 코드를 멈추고 즉시 ISR을 호출합니다. Uno에서 attachInterrupt를 쓸 수 있는 외부 인터럽트 핀은 2번과 3번입니다."},{"h":"ISR의 제약","t":"ISR은 최대한 짧아야 하며 보통 플래그를 세우거나 카운터만 올리고 즉시 빠져나옵니다. ISR 안에서는 인터럽트가 꺼져 있어 delay()가 동작하지 않고 millis()도 증가하지 않으며 긴 Serial 출력도 피해야 합니다. ISR과 loop()가 함께 쓰는 변수는 컴파일러 최적화로 값이 캐시되지 않도록 volatile로 선언합니다. 무거운 계산이나 출력은 loop()에서 플래그를 확인한 뒤 처리합니다."},{"h":"delay는 블로킹, millis는 논블로킹","t":"delay(1000)은 1초 동안 CPU를 그 자리에 묶어 두므로 그동안 버튼 확인이나 센서 읽기 같은 다른 일을 전혀 못 합니다. millis()는 보드가 켜진 뒤 흐른 밀리초를 돌려주므로 이전 시각과의 차이를 비교해 시간이 됐을 때만 동작을 실행할 수 있습니다. 이 방식이면 loop()가 계속 돌면서 여러 작업을 번갈아 처리할 수 있습니다. 두 개 이상의 주기가 다른 작업을 동시에 굴릴 때 필수 패턴입니다."},{"h":"디바운싱과 센서 읽기 주기","t":"기계식 버튼은 눌리는 순간 접점이 수 밀리초 동안 떨렸다 붙었다를 반복해 한 번 눌러도 여러 번 눌린 것으로 읽힙니다. 마지막 변화 시각을 저장해 두고 약 20~50ms가 지난 뒤에야 상태를 인정하는 디바운싱으로 해결합니다. 센서도 데이터시트가 정한 최소 변환 시간이 있어 DHT11처럼 초당 1회 정도만 읽어야 하는 경우가 있습니다. 필요 이상으로 자주 읽으면 값이 부정확하거나 이전 값이 그대로 반복됩니다."}],"code":{"c":"volatile unsigned long pulseCount = 0; // ISR과 공유 -> volatile\nunsigned long lastReport = 0;\nconst unsigned long PERIOD = 1000;\n\nvoid onPulse() {   // ISR: 짧게! delay/Serial 금지\n  pulseCount++;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(2, INPUT_PULLUP);            // Uno 외부 인터럽트 핀\n  attachInterrupt(digitalPinToInterrupt(2), onPulse, FALLING);\n}\n\nvoid loop() {\n  unsigned long now = millis();        // 논블로킹 타이밍\n  if (now - lastReport >= PERIOD) {\n    lastReport = now;\n    noInterrupts();\n    unsigned long c = pulseCount;      // 안전하게 복사\n    interrupts();\n    Serial.println(c);                 // 무거운 일은 loop에서\n  }\n}","cap":"ISR은 카운터만 올리고, millis() 비교로 1초마다 논블로킹으로 결과를 출력합니다."},"key":["delay()는 블로킹이라 그동안 아무 일도 못 하므로 millis() 경과 비교 패턴을 쓴다","ISR은 짧게 유지하고 delay()나 긴 Serial 출력을 넣지 않으며 내부에서 millis()는 증가하지 않는다","ISR과 loop()가 공유하는 변수는 반드시 volatile로 선언한다","기계식 버튼은 채터링 때문에 20~50ms 수준의 디바운싱이 필요하다"]}},{"t":"ISR 안에서 하면 안 되는 것","q":[{"t":"choice","k":"uno-isr-millis-frozen","q":"ISR 안에서 millis()를 호출했을 때의 특징으로 옳은 것은?","ex":"millis()는 타이머0 오버플로 인터럽트로 갱신되는데 ISR 실행 중에는 그 인터럽트가 처리되지 않아 값이 멈춥니다.\n💡 개념: 값을 읽는 것 자체는 가능하지만 ISR이 길어져도 값이 늘지 않아 시간 측정에 쓸 수 없습니다.\n🛠 실무: ISR에서 시각을 기록해야 하면 진입 순간의 millis()를 한 번만 저장하고 계산은 loop()에서 합니다.","o":["ISR 안에서는 항상 0을 반환한다","ISR 안에서는 millis() 의 정밀도가 그대로 마이크로초 단위까지 올라간다","ISR이 실행되는 동안에는 값이 증가하지 않고 진입 시점의 값으로 고정된다","ISR 안에서 호출하면 컴파일 에러가 난다"],"a":2},{"t":"choice","k":"uno-isr-forbidden-delay","q":"ISR 안에 delay(500)을 넣으면 어떤 일이 벌어집니까?","ex":"delay()는 타이머 인터럽트에 의존하는데 ISR 안에서는 인터럽트가 비활성이라 시간이 흐르지 않고 멈춥니다.\n💡 개념: 컴파일은 통과하므로 오류 없이 조용히 오작동하는 위험한 실수입니다.\n🛠 실무: ISR에서는 플래그만 세우고 지연이 필요한 처리는 loop()에서 millis()로 수행합니다.","o":["정상적으로 0.5초를 기다린 뒤 ISR이 끝난다","ISR 안에서는 delay 가 자동으로 millis 를 쓰는 논블로킹 대기로 바뀌어 정상 동작한다","컴파일 오류가 발생해 업로드 자체가 되지 않는다","ISR 안에서는 인터럽트가 꺼져 있어 delay가 제대로 동작하지 않고 시스템이 멈춘 것처럼 된다"],"a":3},{"t":"choice","k":"uno-isr-keep-short","q":"ISR을 최대한 짧게 유지해야 하는 이유로 가장 알맞은 것은?","ex":"ISR 중에는 인터럽트가 막혀 있어 길어질수록 다른 인터럽트, 시리얼 수신, 타이머 갱신이 밀립니다.\n💡 개념: ISR은 카운터 증가나 플래그 설정 정도의 아주 짧은 작업만 담는 것이 원칙입니다.\n🛠 실무: 디버깅용 Serial.println을 ISR에 임시로 넣었다가 수신 데이터가 깨지는 사고가 흔합니다.","o":["ISR이 실행되는 동안 다른 인터럽트와 타이머 처리가 지연되어 이벤트를 놓치기 때문","ISR이 길면 플래시 메모리를 32KB 넘게 쓰기 때문","ISR이 길면 보율이 자동으로 낮아지기 때문","ISR 코드가 길어지면 컴파일러가 volatile 선언을 그대로 무시해 버리기 때문"],"a":0},{"t":"choice","k":"uno-isr-flag-pattern","q":"인터럽트로 감지한 이벤트에 대해 SD 카드 기록처럼 무거운 작업을 해야 합니다. 올바른 구조는?","ex":"ISR은 플래그만 세우고 실제 무거운 작업은 loop()에서 수행하는 것이 표준 패턴입니다.\n💡 개념: 이렇게 나누면 인터럽트 응답성은 유지하면서 긴 작업도 안전하게 처리할 수 있습니다.\n🛠 실무: 플래그를 처리한 뒤에는 곧바로 false로 되돌려 같은 이벤트를 중복 처리하지 않게 합니다.","o":["ISR 안에서 SD 카드 기록까지 모두 끝낸다","ISR에서 volatile 플래그만 true로 세우고 loop()에서 플래그를 보고 기록한다","SD 기록 함수 자체를 ISR로 등록한다","attachInterrupt 를 아예 호출하지 않고 delay 만으로 타이밍을 맞추어 기록한다"],"a":1},{"t":"choice","k":"uno-isr-serial-print","q":"ISR 안에서 긴 문자열을 Serial.println으로 출력하는 코드가 위험한 이유는?","ex":"9600bps 기준 한 글자에 약 1ms가 걸릴 만큼 시리얼 전송은 느려 ISR이 오래 잡히게 됩니다.\n💡 개념: 시리얼 송신도 인터럽트 기반이라 ISR 안에서는 버퍼가 비워지지 않아 멈출 수 있습니다.\n🛠 실무: 인터럽트 디버깅은 ISR에서 값을 변수에 담고 loop()에서 출력하는 방식으로 합니다.","o":["Serial 출력이 SRAM 2KB를 즉시 모두 소모하기 때문","Serial.println 이 내부에서 인터럽트를 완전히 영구히 꺼 버리기 때문이다","ISR 안에서는 Serial 객체가 아예 생성되지 않기 때문","시리얼 전송이 상대적으로 느려 ISR이 길어지고 다른 인터럽트 처리가 밀리기 때문"],"a":3}],"th":{"sum":"Arduino Uno에서 이벤트를 놓치지 않으려면 폴링과 인터럽트의 차이를 알아야 하고, delay()의 블로킹 특성을 millis() 패턴으로 대체해야 합니다. ISR은 짧게 쓰고 공유 변수는 volatile로 선언합니다.","body":[{"h":"폴링과 인터럽트","t":"폴링은 loop()에서 digitalRead를 반복해 상태가 변했는지 계속 확인하는 방식입니다. 코드가 다른 일로 바쁠 때 짧게 지나가는 신호는 폴링으로 놓칠 수 있습니다. 인터럽트는 하드웨어가 신호 변화를 감지해 현재 실행 중인 코드를 멈추고 즉시 ISR을 호출합니다. Uno에서 attachInterrupt를 쓸 수 있는 외부 인터럽트 핀은 2번과 3번입니다."},{"h":"ISR의 제약","t":"ISR은 최대한 짧아야 하며 보통 플래그를 세우거나 카운터만 올리고 즉시 빠져나옵니다. ISR 안에서는 인터럽트가 꺼져 있어 delay()가 동작하지 않고 millis()도 증가하지 않으며 긴 Serial 출력도 피해야 합니다. ISR과 loop()가 함께 쓰는 변수는 컴파일러 최적화로 값이 캐시되지 않도록 volatile로 선언합니다. 무거운 계산이나 출력은 loop()에서 플래그를 확인한 뒤 처리합니다."},{"h":"delay는 블로킹, millis는 논블로킹","t":"delay(1000)은 1초 동안 CPU를 그 자리에 묶어 두므로 그동안 버튼 확인이나 센서 읽기 같은 다른 일을 전혀 못 합니다. millis()는 보드가 켜진 뒤 흐른 밀리초를 돌려주므로 이전 시각과의 차이를 비교해 시간이 됐을 때만 동작을 실행할 수 있습니다. 이 방식이면 loop()가 계속 돌면서 여러 작업을 번갈아 처리할 수 있습니다. 두 개 이상의 주기가 다른 작업을 동시에 굴릴 때 필수 패턴입니다."},{"h":"디바운싱과 센서 읽기 주기","t":"기계식 버튼은 눌리는 순간 접점이 수 밀리초 동안 떨렸다 붙었다를 반복해 한 번 눌러도 여러 번 눌린 것으로 읽힙니다. 마지막 변화 시각을 저장해 두고 약 20~50ms가 지난 뒤에야 상태를 인정하는 디바운싱으로 해결합니다. 센서도 데이터시트가 정한 최소 변환 시간이 있어 DHT11처럼 초당 1회 정도만 읽어야 하는 경우가 있습니다. 필요 이상으로 자주 읽으면 값이 부정확하거나 이전 값이 그대로 반복됩니다."}],"code":{"c":"volatile unsigned long pulseCount = 0; // ISR과 공유 -> volatile\nunsigned long lastReport = 0;\nconst unsigned long PERIOD = 1000;\n\nvoid onPulse() {   // ISR: 짧게! delay/Serial 금지\n  pulseCount++;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(2, INPUT_PULLUP);            // Uno 외부 인터럽트 핀\n  attachInterrupt(digitalPinToInterrupt(2), onPulse, FALLING);\n}\n\nvoid loop() {\n  unsigned long now = millis();        // 논블로킹 타이밍\n  if (now - lastReport >= PERIOD) {\n    lastReport = now;\n    noInterrupts();\n    unsigned long c = pulseCount;      // 안전하게 복사\n    interrupts();\n    Serial.println(c);                 // 무거운 일은 loop에서\n  }\n}","cap":"ISR은 카운터만 올리고, millis() 비교로 1초마다 논블로킹으로 결과를 출력합니다."},"key":["delay()는 블로킹이라 그동안 아무 일도 못 하므로 millis() 경과 비교 패턴을 쓴다","ISR은 짧게 유지하고 delay()나 긴 Serial 출력을 넣지 않으며 내부에서 millis()는 증가하지 않는다","ISR과 loop()가 공유하는 변수는 반드시 volatile로 선언한다","기계식 버튼은 채터링 때문에 20~50ms 수준의 디바운싱이 필요하다"]}},{"t":"millis 논블로킹과 버튼 디바운싱","q":[{"t":"choice","k":"uno-button-bounce-symptom","q":"버튼을 한 번만 눌렀는데 카운터가 3~4씩 올라갑니다. 가장 유력한 원인은?","ex":"기계식 스위치는 접촉 순간 수 밀리초 동안 붙었다 떨어지기를 반복해 여러 번의 입력 변화로 읽힙니다.\n💡 개념: 이 현상을 채터링 또는 바운스라 하고, 이를 걸러내는 처리가 디바운싱입니다.\n🛠 실무: 소프트웨어 디바운싱이 가장 쉽고, 노이즈가 심하면 RC 회로나 슈미트 트리거를 추가합니다.","o":["보율이 9600이 아니라 115200이라서","PWM 핀이 아닌 곳에 버튼을 연결해서","기계식 접점이 순간적으로 떨리는 채터링(바운스) 때문","analogRead 의 10비트 분해능이 부족해서 생기는 일"],"a":2},{"t":"choice","k":"uno-delay-blocking-reason","q":"loop()에서 delay(1000)을 쓰면 생기는 문제로 가장 정확한 것은?","ex":"delay()는 블로킹 함수라 지정한 시간 동안 코드 진행이 멈춰 다른 일을 전혀 처리하지 못합니다.\n💡 개념: 전원이나 millis 값에는 영향이 없고 단지 실행 흐름만 붙잡습니다.\n🛠 실무: LED 깜빡임과 버튼 반응을 동시에 원하면 delay 대신 millis 비교로 바꿔야 합니다.","o":["delay 는 호출할 때마다 SRAM 을 1KB 씩 소모해 메모리가 부족해지게 된다","1초 동안 CPU가 그 자리에 묶여 버튼 확인 같은 다른 작업을 하지 못한다","delay 이후 millis() 값이 0으로 초기화된다","1초 동안 보드 전원이 꺼져 재부팅된다"],"a":1},{"t":"input","k":"uno-debounce-typical-ms","q":"기계식 버튼의 소프트웨어 디바운싱에 흔히 쓰는 지연 시간은 대략 몇 밀리초 수준입니까? (예: 50ms, 20~50, 50)","ex":"보통 20~50ms 정도면 접점 떨림이 가라앉아 안정된 상태를 읽을 수 있습니다.\n💡 개념: 너무 짧으면 바운스가 남고 너무 길면 빠른 연속 입력을 놓칩니다.\n🛠 실무: 마지막 상태 변화 시각을 millis()로 저장하고 그 시간이 지난 뒤에만 상태를 확정하는 방식이 표준입니다.","a":["50","50ms","20~50","20~50ms"]},{"t":"choice","k":"uno-millis-nonblocking-pattern","q":"delay 없이 500ms마다 LED를 토글하는 논블로킹 코드로 올바른 것은?","ex":"이전 실행 시각과 현재 millis()의 차이를 목표 간격과 비교하고, 실행 후 기준 시각을 갱신하는 것이 표준 패턴입니다.\n💡 개념: millis()는 계속 증가하므로 특정 값과 == 로 비교하면 그 순간을 놓치기 쉽습니다.\n🛠 실무: 뺄셈 비교 방식은 약 49일 후 millis()가 넘칠 때도 unsigned 연산 덕분에 안전하게 동작합니다.","o":["if (millis() - lastToggle &gt;= 500) { lastToggle = millis(); toggle(); }","while (millis() - lastToggle &lt; 500) { toggle(); lastToggle = millis(); }","if (millis() &gt; 500) { delay(500); toggle(); lastToggle = millis(); }","if (millis() == lastToggle + 500) { toggle(); lastToggle = millis(); }"],"a":0},{"t":"choice","k":"uno-sensor-read-interval","q":"DHT11처럼 데이터시트에 최소 읽기 간격이 있는 센서를 loop()에서 지연 없이 매 루프마다 읽으면 생기는 일은?","ex":"센서마다 내부 측정과 변환에 필요한 최소 시간이 있어 그보다 자주 요청하면 실패하거나 캐시된 값이 나옵니다.\n💡 개념: DHT11은 대략 1초에 한 번 정도가 권장 주기입니다.\n🛠 실무: 센서 읽기도 delay 대신 millis() 비교로 주기를 지키면 다른 작업을 막지 않습니다.","o":["모든 analogWrite 의 듀티 비율이 자동으로 0 이 되어 버린다","보드의 플래시 메모리가 손상된다","센서가 매번 더 정확한 값을 돌려준다","변환 시간이 부족해 읽기가 실패하거나 이전 값이 그대로 반복된다"],"a":3}],"th":{"sum":"Arduino Uno에서 이벤트를 놓치지 않으려면 폴링과 인터럽트의 차이를 알아야 하고, delay()의 블로킹 특성을 millis() 패턴으로 대체해야 합니다. ISR은 짧게 쓰고 공유 변수는 volatile로 선언합니다.","body":[{"h":"폴링과 인터럽트","t":"폴링은 loop()에서 digitalRead를 반복해 상태가 변했는지 계속 확인하는 방식입니다. 코드가 다른 일로 바쁠 때 짧게 지나가는 신호는 폴링으로 놓칠 수 있습니다. 인터럽트는 하드웨어가 신호 변화를 감지해 현재 실행 중인 코드를 멈추고 즉시 ISR을 호출합니다. Uno에서 attachInterrupt를 쓸 수 있는 외부 인터럽트 핀은 2번과 3번입니다."},{"h":"ISR의 제약","t":"ISR은 최대한 짧아야 하며 보통 플래그를 세우거나 카운터만 올리고 즉시 빠져나옵니다. ISR 안에서는 인터럽트가 꺼져 있어 delay()가 동작하지 않고 millis()도 증가하지 않으며 긴 Serial 출력도 피해야 합니다. ISR과 loop()가 함께 쓰는 변수는 컴파일러 최적화로 값이 캐시되지 않도록 volatile로 선언합니다. 무거운 계산이나 출력은 loop()에서 플래그를 확인한 뒤 처리합니다."},{"h":"delay는 블로킹, millis는 논블로킹","t":"delay(1000)은 1초 동안 CPU를 그 자리에 묶어 두므로 그동안 버튼 확인이나 센서 읽기 같은 다른 일을 전혀 못 합니다. millis()는 보드가 켜진 뒤 흐른 밀리초를 돌려주므로 이전 시각과의 차이를 비교해 시간이 됐을 때만 동작을 실행할 수 있습니다. 이 방식이면 loop()가 계속 돌면서 여러 작업을 번갈아 처리할 수 있습니다. 두 개 이상의 주기가 다른 작업을 동시에 굴릴 때 필수 패턴입니다."},{"h":"디바운싱과 센서 읽기 주기","t":"기계식 버튼은 눌리는 순간 접점이 수 밀리초 동안 떨렸다 붙었다를 반복해 한 번 눌러도 여러 번 눌린 것으로 읽힙니다. 마지막 변화 시각을 저장해 두고 약 20~50ms가 지난 뒤에야 상태를 인정하는 디바운싱으로 해결합니다. 센서도 데이터시트가 정한 최소 변환 시간이 있어 DHT11처럼 초당 1회 정도만 읽어야 하는 경우가 있습니다. 필요 이상으로 자주 읽으면 값이 부정확하거나 이전 값이 그대로 반복됩니다."}],"code":{"c":"volatile unsigned long pulseCount = 0; // ISR과 공유 -> volatile\nunsigned long lastReport = 0;\nconst unsigned long PERIOD = 1000;\n\nvoid onPulse() {   // ISR: 짧게! delay/Serial 금지\n  pulseCount++;\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(2, INPUT_PULLUP);            // Uno 외부 인터럽트 핀\n  attachInterrupt(digitalPinToInterrupt(2), onPulse, FALLING);\n}\n\nvoid loop() {\n  unsigned long now = millis();        // 논블로킹 타이밍\n  if (now - lastReport >= PERIOD) {\n    lastReport = now;\n    noInterrupts();\n    unsigned long c = pulseCount;      // 안전하게 복사\n    interrupts();\n    Serial.println(c);                 // 무거운 일은 loop에서\n  }\n}","cap":"ISR은 카운터만 올리고, millis() 비교로 1초마다 논블로킹으로 결과를 출력합니다."},"key":["delay()는 블로킹이라 그동안 아무 일도 못 하므로 millis() 경과 비교 패턴을 쓴다","ISR은 짧게 유지하고 delay()나 긴 Serial 출력을 넣지 않으며 내부에서 millis()는 증가하지 않는다","ISR과 loop()가 공유하는 변수는 반드시 volatile로 선언한다","기계식 버튼은 채터링 때문에 20~50ms 수준의 디바운싱이 필요하다"]}},{"t":"직접 이어 보기 — 센서와 인터럽트 핀","th":{"sum":"센서 대부분은 전원(VCC)·접지(GND)·신호(OUT) 세 가닥이다. 세 가닥이 다 있어야 값을 준다.","body":[{"h":"전원을 빼먹으면","t":"신호선만 잇고 VCC 를 안 걸면 센서가 아예 동작하지 않는다. 값이 0으로 고정되거나 떠다니는데, 코드를 아무리 봐도 원인이 안 보인다. 센서가 이상하면 **전원·접지·신호 세 가닥부터** 확인한다."},{"h":"인터럽트 핀","t":"Uno 에서 외부 인터럽트를 쓸 수 있는 핀은 **D2 와 D3 뿐**이다. 다른 핀에 물리고 `attachInterrupt` 를 부르면 동작하지 않는다. 빠르게 지나가는 신호(회전 센서·엔코더)는 폴링으로 놓치기 쉬워 인터럽트 핀에 물린다."}],"code":{"c":"attachInterrupt(digitalPinToInterrupt(2), onEdge, RISING);\n// Uno 는 D2·D3 만 된다","cap":"센서는 세 가닥, 인터럽트는 D2·D3"},"key":["센서는 VCC·GND·OUT 세 가닥","전원을 빼먹으면 값이 안 나온다","Uno 인터럽트는 D2·D3"]},"q":[{"k":"모션 센서 세 가닥 잇기","cat":"internals","q":"모션 센서를 이으세요. <b>VCC 는 5V</b>, <b>GND 는 GND</b>, <b>OUT 은 인터럽트가 되는 핀</b>에 물려야 합니다.","ex":"Uno 에서 attachInterrupt 를 쓸 수 있는 핀은 D2 와 D3 뿐입니다. D7 에 물리면 코드가 맞아도 인터럽트가 걸리지 않아요. 그리고 VCC 를 빼먹으면 센서 자체가 안 돌아 OUT 값이 의미가 없습니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["D2","D7","5V","GND"]},{"id":"pir","label":"모션 센서","pins":["VCC","OUT","GND"]}],"checks":[{"d":"VCC 가 5V 에 붙는다","link":["pir.VCC","uno.5V"]},{"d":"GND 가 GND 에 붙는다","link":["pir.GND","uno.GND"]},{"d":"OUT 이 인터럽트 핀(D2)으로 간다","link":["pir.OUT","uno.D2"]},{"d":"OUT 이 D7 에 붙어 있지 않다","apart":["pir.OUT","uno.D7"],"wires":true},{"d":"5V 와 GND 가 바로 붙어 있지 않다","apart":["uno.5V","uno.GND"],"wires":true}],"start":[],"sol":[["pir.VCC","uno.5V"],["pir.GND","uno.GND"],["pir.OUT","uno.D2"]]},{"k":"전원을 빼먹은 배선 고치기","cat":"internals","q":"온도 센서의 <b>신호선만</b> 이어져 있습니다. 값이 안 나오는 이유를 찾아 <b>빠진 두 가닥</b>을 마저 이으세요.","ex":"신호선만 이으면 센서에 전원이 없어 아무 값도 만들지 못합니다. A1 은 떠다니는 값을 읽어요 — 숫자가 나오니까 동작하는 것처럼 보여서 더 헷갈립니다. 센서가 이상하면 세 가닥부터 확인하세요.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A1","5V","GND"]},{"id":"tmp","label":"온도 센서","pins":["VCC","OUT","GND"]}],"checks":[{"d":"OUT 이 A1 로 간다","link":["tmp.OUT","uno.A1"]},{"d":"VCC 가 5V 에 붙는다","link":["tmp.VCC","uno.5V"]},{"d":"GND 가 GND 에 붙는다","link":["tmp.GND","uno.GND"]},{"d":"VCC 와 GND 가 서로 붙어 있지 않다","apart":["tmp.VCC","tmp.GND"],"wires":true}],"start":[["tmp.OUT","uno.A1"]],"sol":[["tmp.OUT","uno.A1"],["tmp.VCC","uno.5V"],["tmp.GND","uno.GND"]]}]}],"ord":4},{"t":"UART·I2C·SPI 통신과 전력·메모리 제약","l":[{"t":"UART 보율과 시리얼 디버깅","q":[{"t":"choice","k":"uart-uno-rx-tx-pins","q":"Arduino Uno의 하드웨어 시리얼(UART)이 연결된 디지털 핀 번호는?","ex":"Uno의 하드웨어 UART는 디지털 0번 RX, 1번 TX에 연결되어 있고 USB 통신과 공유됩니다.\n💡 개념: A4/A5는 I2C, 11/12/13은 SPI, 2/3은 외부 인터럽트 핀입니다.\n🛠 실무: 0번과 1번에 모듈을 꽂아 둔 채 업로드하면 실패하므로 업로드 전에 잠시 분리합니다.","o":["A4(SDA)와 A5(SCL)","0번(RX)과 1번(TX)","11번(MOSI)과 12번(MISO)","2번과 3번(소프트웨어 시리얼)"],"a":1},{"t":"input","k":"uart-common-baud-value","q":"아두이노 예제에서 Serial.begin()에 가장 흔히 쓰이는 기본 보율 값은 무엇입니까? (숫자만 입력, 예: 9600)","ex":"아두이노 기본 예제와 시리얼 모니터의 기본값이 모두 9600bps입니다.\n💡 개념: 보율은 초당 전송되는 심볼 수로 9600bps면 한 글자에 대략 1ms 정도가 걸립니다.\n🛠 실무: 로그가 많아 loop가 느려지면 115200으로 올려 전송 시간을 줄이고 모니터 설정도 함께 바꿉니다.","a":["9600","9600bps","9600 bps"]},{"t":"choice","k":"uart-no-clock-line","q":"UART가 I2C나 SPI와 결정적으로 다른 점은?","ex":"UART는 별도의 클럭선 없이 시작 비트와 약속된 보율로 타이밍을 맞추는 비동기 방식입니다.\n💡 개념: I2C의 SCL, SPI의 SCK가 클럭선이며 이들은 동기 통신입니다.\n🛠 실무: 클럭이 없어 배선은 단순하지만 양쪽 클럭 오차가 크면 장거리에서 오류율이 올라갑니다.","o":["클럭 신호선이 없는 비동기 통신이라 양쪽이 같은 보율을 미리 약속해야 한다","통신을 시작할 때에는 언제나 마스터가 슬레이브의 주소를 먼저 전송해야 한다","전이중 통신이 불가능하다","한 선으로 데이터와 클럭을 함께 보낸다"],"a":0},{"t":"choice","k":"uart-baud-mismatch-symptom","q":"Uno 코드에 Serial.begin(9600)을 썼는데 시리얼 모니터를 115200으로 열었습니다. 화면에 나타나는 현상은?","ex":"UART는 클럭선 없이 양쪽이 약속한 보율로 비트를 샘플링하므로 속도가 다르면 비트 경계를 잘못 읽어 깨진 문자가 나옵니다.\n💡 개념: 아두이노 UART에는 보율 자동 협상 기능이 없습니다.\n🛠 실무: 출력이 깨지면 코드의 Serial.begin 값과 모니터 우하단 보율 설정부터 맞춰 보세요.","o":["정상적으로 출력되지만 속도만 느려진다","의미를 알 수 없는 깨진 문자가 출력된다","자동으로 보율이 맞춰져 정상 출력된다","아무것도 출력되지 않은 채로 보드가 그냥 리셋된다"],"a":1},{"t":"choice","k":"uart-two-device-wiring","q":"Uno와 GPS 모듈을 UART로 연결할 때 올바른 배선은?","ex":"한쪽이 보내는 TX는 상대가 받는 RX로 들어가야 하므로 두 선을 교차해서 연결합니다.\n💡 개념: SDA/SCL은 I2C, MOSI/MISO/SCK는 SPI의 배선이라 UART와 다릅니다.\n🛠 실무: GND를 공통으로 묶지 않으면 기준 전압이 달라 통신이 되지 않으니 GND도 반드시 연결합니다.","o":["SDA와 SCL 두 선을 연결하고 풀업 저항을 단다","MOSI, MISO, SCK 세 선을 연결하고 여기에 따로 CS 핀을 추가한다","Uno의 TX를 모듈의 TX에, RX를 모듈의 RX에 연결한다","Uno의 TX를 모듈의 RX에, Uno의 RX를 모듈의 TX에 교차 연결한다"],"a":3}],"th":{"sum":"Arduino Uno는 UART, I2C, SPI 세 가지 통신을 지원하며 각각 선 개수, 속도, 장치 선택 방식이 다릅니다. 동시에 SRAM 2KB와 플래시 32KB라는 좁은 자원 안에서 전력까지 아껴야 합니다.","body":[{"h":"UART와 보율","t":"UART는 TX와 RX 두 선으로 데이터를 주고받는 비동기 통신이라 클럭선이 따로 없습니다. 대신 양쪽이 미리 같은 보율(baud rate)로 약속해야 하고, Serial.begin(9600)과 시리얼 모니터 설정이 다르면 화면에 깨진 문자가 쏟아집니다. Uno에서 하드웨어 시리얼은 디지털 0번(RX)과 1번(TX) 핀에 연결되어 있고 USB 업로드와 공유됩니다. 그래서 0번과 1번 핀에 장치를 연결한 채로 업로드하면 실패하기 쉽습니다."},{"h":"I2C는 2선 공유와 주소","t":"I2C는 SDA(데이터)와 SCL(클럭) 단 두 선을 여러 장치가 함께 씁니다. 마스터가 7비트 주소를 먼저 보내 그 주소를 가진 슬레이브 하나만 응답하게 만들어 장치를 구분합니다. 두 선 모두 풀업 저항이 필요하고 대개 4.7k옴 정도를 씁니다. 같은 주소를 가진 장치를 두 개 붙이면 충돌해서 둘 다 제대로 동작하지 않으므로 주소 점퍼를 바꾸거나 I2C 멀티플렉서를 씁니다. Uno의 I2C 핀은 A4(SDA)와 A5(SCL)입니다."},{"h":"SPI는 빠르지만 핀을 더 쓴다","t":"SPI는 MOSI, MISO, SCK 세 선을 모든 슬레이브가 공유하고, 슬레이브마다 별도의 CS(SS) 선을 하나씩 더 연결해 통신할 상대를 고릅니다. 주소 개념 없이 CS를 LOW로 내려 선택하므로 슬레이브가 늘면 핀도 그만큼 늘어납니다. 대신 클럭 속도가 높고 전이중이라 I2C보다 훨씬 빠릅니다. Uno에서는 11(MOSI), 12(MISO), 13(SCK), 10(기본 SS)이 SPI 핀입니다."},{"h":"전력과 메모리 제약","t":"배터리로 오래 동작해야 하면 avr/sleep.h의 슬립 모드로 CPU를 재우고 인터럽트나 워치독으로 깨우는 방식이 효과적입니다. Uno의 ATmega328P는 SRAM이 2KB뿐이라 문자열이나 배열을 많이 쓰면 금세 부족해지고 재부팅이나 이상 동작이 납니다. Serial.println(F(\"메시지\")) 처럼 F() 매크로로 문자열 리터럴을 32KB 플래시에 남겨 두면 RAM을 아낄 수 있습니다. 컴파일 후 출력되는 전역 변수 사용량 경고를 항상 확인하는 습관이 필요합니다."}],"code":{"c":"#include <Wire.h>\n#include <SPI.h>\n\nconst int CS_PIN = 10; // SPI 슬레이브별 CS\n\nvoid setup() {\n  Serial.begin(9600);          // 시리얼 모니터도 9600으로 맞출 것\n  Serial.println(F(\"boot ok\")); // F(): 문자열을 플래시에 두어 SRAM 절약\n\n  Wire.begin();                // I2C: A4=SDA, A5=SCL (풀업 필요)\n  Wire.beginTransmission(0x3C); // 7비트 주소로 슬레이브 지정\n  Wire.write(0x00);\n  Wire.endTransmission();\n\n  pinMode(CS_PIN, OUTPUT);\n  digitalWrite(CS_PIN, HIGH);  // 평소 비선택\n  SPI.begin();\n}\n\nvoid loop() {\n  digitalWrite(CS_PIN, LOW);   // 이 슬레이브만 선택\n  byte v = SPI.transfer(0x00);\n  digitalWrite(CS_PIN, HIGH);\n  Serial.println(v);\n  delay(1000);\n}","cap":"I2C는 7비트 주소로, SPI는 CS 핀으로 상대를 고르며 F() 매크로로 SRAM을 아낍니다."},"key":["UART는 클럭선 없이 비동기라 양쪽 보율이 다르면 깨진 문자가 나온다","I2C는 SDA/SCL 2선을 공유하고 7비트 주소로 슬레이브를 구분하며 풀업 저항이 필요하다","SPI는 MOSI/MISO/SCK 공유에 슬레이브마다 CS가 필요해 빠르지만 핀을 더 쓴다","Uno는 SRAM 2KB·플래시 32KB이며 F() 매크로로 문자열을 플래시에 두면 RAM을 절약한다"]}},{"t":"I2C 주소 충돌과 SPI 슬레이브 선택","q":[{"t":"choice","k":"i2c-two-wire-names","q":"I2C 통신이 사용하는 두 신호선의 이름은?","ex":"I2C는 데이터선 SDA와 클럭선 SCL 두 가닥을 모든 장치가 공유합니다.\n💡 개념: MOSI/MISO는 SPI, TX/RX는 UART의 신호선이고 VCC/GND는 전원입니다.\n🛠 실무: Uno에서는 A4가 SDA, A5가 SCL이며 보드 상단에 별도 SDA/SCL 핀도 병렬로 나와 있습니다.","o":["VCC와 GND","SDA와 SCL","MOSI와 MISO","TX와 RX"],"a":1},{"t":"choice","k":"i2c-address-collision","q":"같은 7비트 주소 0x68을 가진 I2C 센서 두 개를 하나의 SDA/SCL 버스에 함께 연결하면?","ex":"I2C는 주소로만 상대를 구분하므로 같은 주소 장치가 둘이면 동시에 응답해 데이터가 깨집니다.\n💡 개념: 아두이노에는 주소를 자동 재할당하는 기능이 없습니다.\n🛠 실무: 주소 설정 핀(AD0)이나 점퍼로 주소를 바꾸거나 TCA9548A 같은 I2C 멀티플렉서를 사용합니다.","o":["두 장치가 같은 주소에 동시에 응답해 충돌하고 값이 제대로 읽히지 않는다","SPI 모드로 자동 전환되어 정상 동작한다","아두이노가 자동으로 두 번째 장치에 새 주소를 부여한다","첫 번째 장치만 인식되고 두 번째 장치는 안전하게 무시되어 아무 문제가 없다"],"a":0},{"t":"choice","k":"spi-slave-select-mechanism","q":"SPI 버스에 슬레이브를 3개 연결할 때 통신할 대상을 고르는 방법은?","ex":"SPI에는 주소 개념이 없고 MOSI/MISO/SCK는 공유하되 CS 라인으로 대상을 하나씩 선택합니다.\n💡 개념: 선택되지 않은 슬레이브는 CS가 HIGH라 MISO를 고임피던스로 두어 버스를 방해하지 않습니다.\n🛠 실무: 슬레이브가 늘수록 CS 핀이 하나씩 더 필요해 Uno에서는 핀 부족이 금방 옵니다.","o":["MISO 선을 슬레이브마다 따로 배선한다","통신을 시작하기 전에 각 슬레이브에 7비트 주소를 그때그때 먼저 전송해 대상을 골라낸다","보율을 슬레이브마다 다르게 설정해 구분한다","슬레이브마다 별도의 CS(SS) 핀을 두고 통신할 슬레이브의 CS만 LOW로 내린다"],"a":3},{"t":"choice","k":"spi-vs-i2c-tradeoff","q":"SD 카드처럼 큰 데이터를 빠르게 주고받아야 할 때 I2C보다 SPI가 유리한 이유와 그 대가는?","ex":"SPI는 높은 클럭과 전이중 덕분에 빠르지만 공유선 3개에 더해 슬레이브 수만큼 CS 핀이 필요합니다.\n💡 개념: I2C는 2선으로 끝나 핀이 절약되지만 속도가 낮고 주소 충돌 문제가 있습니다.\n🛠 실무: 디스플레이나 SD 카드처럼 데이터량이 큰 장치는 SPI, 저속 센서는 I2C로 나눠 붙이는 구성이 흔합니다.","o":["SPI는 클럭선이 없어 배선이 줄지만 보율을 맞춰야 한다","SPI가 더 느리지만 선이 2개뿐이라 배선이 간단하다","SPI가 더 빠르지만 슬레이브마다 CS가 필요해 핀을 더 많이 쓴다","SPI 가 더 빠르고 쓰는 선도 I2C 보다 적어서 모든 면에서 유리하다"],"a":2},{"t":"choice","k":"i2c-pullup-requirement","q":"I2C 버스에서 SDA와 SCL에 풀업 저항이 필요한 이유는?","ex":"I2C 장치는 라인을 LOW로 당기기만 할 수 있어서 풀업 저항이 라인을 HIGH로 복귀시켜야 합니다.\n💡 개념: 흔히 4.7k옴 정도를 쓰고, 대부분의 브레이크아웃 보드에는 이미 내장되어 있습니다.\n🛠 실무: 모듈을 여러 개 연결하면 내장 풀업이 병렬로 걸려 저항이 너무 낮아질 수 있으니 일부를 제거하기도 합니다.","o":["서로 다른 5V 장치와 3.3V 장치 사이의 전압을 필요할 때마다 자동으로 변환해 주기 위해","장치들이 라인을 LOW로만 끌 수 있는 오픈 드레인 구조라 HIGH로 되돌릴 수단이 필요해서","슬레이브 주소를 7비트로 제한하기 위해","클럭 속도를 SPI 수준으로 끌어올리기 위해"],"a":1}],"th":{"sum":"Arduino Uno는 UART, I2C, SPI 세 가지 통신을 지원하며 각각 선 개수, 속도, 장치 선택 방식이 다릅니다. 동시에 SRAM 2KB와 플래시 32KB라는 좁은 자원 안에서 전력까지 아껴야 합니다.","body":[{"h":"UART와 보율","t":"UART는 TX와 RX 두 선으로 데이터를 주고받는 비동기 통신이라 클럭선이 따로 없습니다. 대신 양쪽이 미리 같은 보율(baud rate)로 약속해야 하고, Serial.begin(9600)과 시리얼 모니터 설정이 다르면 화면에 깨진 문자가 쏟아집니다. Uno에서 하드웨어 시리얼은 디지털 0번(RX)과 1번(TX) 핀에 연결되어 있고 USB 업로드와 공유됩니다. 그래서 0번과 1번 핀에 장치를 연결한 채로 업로드하면 실패하기 쉽습니다."},{"h":"I2C는 2선 공유와 주소","t":"I2C는 SDA(데이터)와 SCL(클럭) 단 두 선을 여러 장치가 함께 씁니다. 마스터가 7비트 주소를 먼저 보내 그 주소를 가진 슬레이브 하나만 응답하게 만들어 장치를 구분합니다. 두 선 모두 풀업 저항이 필요하고 대개 4.7k옴 정도를 씁니다. 같은 주소를 가진 장치를 두 개 붙이면 충돌해서 둘 다 제대로 동작하지 않으므로 주소 점퍼를 바꾸거나 I2C 멀티플렉서를 씁니다. Uno의 I2C 핀은 A4(SDA)와 A5(SCL)입니다."},{"h":"SPI는 빠르지만 핀을 더 쓴다","t":"SPI는 MOSI, MISO, SCK 세 선을 모든 슬레이브가 공유하고, 슬레이브마다 별도의 CS(SS) 선을 하나씩 더 연결해 통신할 상대를 고릅니다. 주소 개념 없이 CS를 LOW로 내려 선택하므로 슬레이브가 늘면 핀도 그만큼 늘어납니다. 대신 클럭 속도가 높고 전이중이라 I2C보다 훨씬 빠릅니다. Uno에서는 11(MOSI), 12(MISO), 13(SCK), 10(기본 SS)이 SPI 핀입니다."},{"h":"전력과 메모리 제약","t":"배터리로 오래 동작해야 하면 avr/sleep.h의 슬립 모드로 CPU를 재우고 인터럽트나 워치독으로 깨우는 방식이 효과적입니다. Uno의 ATmega328P는 SRAM이 2KB뿐이라 문자열이나 배열을 많이 쓰면 금세 부족해지고 재부팅이나 이상 동작이 납니다. Serial.println(F(\"메시지\")) 처럼 F() 매크로로 문자열 리터럴을 32KB 플래시에 남겨 두면 RAM을 아낄 수 있습니다. 컴파일 후 출력되는 전역 변수 사용량 경고를 항상 확인하는 습관이 필요합니다."}],"code":{"c":"#include <Wire.h>\n#include <SPI.h>\n\nconst int CS_PIN = 10; // SPI 슬레이브별 CS\n\nvoid setup() {\n  Serial.begin(9600);          // 시리얼 모니터도 9600으로 맞출 것\n  Serial.println(F(\"boot ok\")); // F(): 문자열을 플래시에 두어 SRAM 절약\n\n  Wire.begin();                // I2C: A4=SDA, A5=SCL (풀업 필요)\n  Wire.beginTransmission(0x3C); // 7비트 주소로 슬레이브 지정\n  Wire.write(0x00);\n  Wire.endTransmission();\n\n  pinMode(CS_PIN, OUTPUT);\n  digitalWrite(CS_PIN, HIGH);  // 평소 비선택\n  SPI.begin();\n}\n\nvoid loop() {\n  digitalWrite(CS_PIN, LOW);   // 이 슬레이브만 선택\n  byte v = SPI.transfer(0x00);\n  digitalWrite(CS_PIN, HIGH);\n  Serial.println(v);\n  delay(1000);\n}","cap":"I2C는 7비트 주소로, SPI는 CS 핀으로 상대를 고르며 F() 매크로로 SRAM을 아낍니다."},"key":["UART는 클럭선 없이 비동기라 양쪽 보율이 다르면 깨진 문자가 나온다","I2C는 SDA/SCL 2선을 공유하고 7비트 주소로 슬레이브를 구분하며 풀업 저항이 필요하다","SPI는 MOSI/MISO/SCK 공유에 슬레이브마다 CS가 필요해 빠르지만 핀을 더 쓴다","Uno는 SRAM 2KB·플래시 32KB이며 F() 매크로로 문자열을 플래시에 두면 RAM을 절약한다"]}},{"t":"SRAM 2KB 제약과 저전력 설계","q":[{"t":"choice","k":"uno-memory-sizes","q":"Arduino Uno(ATmega328P)의 SRAM과 플래시 용량으로 옳은 것은?","ex":"ATmega328P는 SRAM 2KB, 플래시 32KB, EEPROM 1KB를 갖습니다.\n💡 개념: 플래시는 프로그램 코드가, SRAM은 실행 중 변수가 들어가는 공간입니다.\n🛠 실무: 컴파일 결과에 나오는 전역 변수 사용량이 SRAM의 70%를 넘기 시작하면 불안정해질 수 있습니다.","o":["SRAM 512KB, 플래시 4MB","SRAM 1KB, 플래시 1KB","SRAM 32KB, 플래시 2KB","SRAM 2KB, 플래시 32KB"],"a":3},{"t":"choice","k":"uno-sleep-power-saving","q":"배터리로 몇 달간 동작해야 하는 Uno 기반 센서 노드의 전력 소모를 줄이는 가장 효과적인 방법은?","ex":"delay()는 CPU가 계속 전력을 쓰며 도는 것이라 절전 효과가 없고, 슬립 모드는 CPU와 주변장치를 실제로 꺼 소비 전류를 크게 낮춥니다.\n💡 개념: 깨우는 방법은 외부 인터럽트나 워치독 타이머가 대표적입니다.\n🛠 실무: 보드의 전원 LED와 레귤레이터도 상당한 전류를 먹으므로 저전력 설계에서는 베어 ATmega328P 회로를 따로 만들기도 합니다.","o":["Serial.begin의 보율을 300으로 낮춘다","analogWrite 듀티를 0으로 고정한다","슬립 모드로 CPU를 재우고 인터럽트나 워치독 타이머로 깨운다","loop()에 delay(60000)을 넣어 1분씩 쉬게 한다"],"a":2},{"t":"input","k":"uno-flash-string-macro-name","q":"문자열 리터럴을 플래시 메모리에 두어 SRAM을 아끼게 해 주는 아두이노 매크로의 이름을 적으세요. (예: 괄호 포함 또는 문자 하나)","ex":"정답은 F() 매크로이며 Serial.println(F(\"text\")) 형태로 사용합니다.\n💡 개념: 내부적으로 PROGMEM에 문자열을 두고 필요할 때만 읽어 오는 방식입니다.\n🛠 실무: 변수 배열을 플래시에 두려면 PROGMEM과 pgm_read 계열 함수를 함께 씁니다.","a":["F()","F","f()","F 매크로"]},{"t":"choice","k":"uno-sram-exhaustion-symptom","q":"String 객체와 긴 문자열을 남발한 Uno 스케치가 컴파일은 되지만 실행 중 갑자기 멈추거나 값이 이상해집니다. 가장 유력한 원인은?","ex":"SRAM이 모자라면 힙과 스택이 겹쳐 변수 값이 깨지거나 보드가 멈추는데 컴파일 단계에서는 잡히지 않습니다.\n💡 개념: 플래시 초과는 업로드 전에 오류로 막히므로 실행 중 이상 증상과는 다릅니다.\n🛠 실무: String 대신 고정 크기 char 배열을 쓰고 문자열 리터럴에 F()를 씌우는 것이 기본 처방입니다.","o":["보율이 9600으로 고정되어 데이터가 밀린 것","SRAM 2KB가 부족해 스택과 힙이 충돌한 것","PWM 핀이 아닌 곳에 analogWrite를 한 것","플래시 32KB를 초과해 업로드가 잘린 것"],"a":1},{"t":"choice","k":"uno-f-macro-purpose","q":"Serial.println(F(\"센서 초기화 완료\")) 처럼 F() 매크로를 쓰는 이유는?","ex":"F()가 없으면 문자열 리터럴이 프로그램 시작 시 SRAM으로 복사되지만 F()를 쓰면 플래시에 두고 필요할 때 읽습니다.\n💡 개념: 속도나 인코딩과는 무관하고 오직 메모리 배치의 문제입니다.\n🛠 실무: 디버그 문구가 많은 스케치에서 F()만 씌워도 수백 바이트의 SRAM을 되찾는 경우가 흔합니다.","o":["문자열 리터럴을 플래시에 남겨 두어 SRAM 사용량을 줄이기 때문","출력 속도가 두 배 빨라지기 때문","시리얼 보율을 자동으로 맞춰 주기 때문","한글 문자열을 자동으로 UTF-8 인코딩으로 그대로 변환해 주기 때문"],"a":0}],"th":{"sum":"Arduino Uno는 UART, I2C, SPI 세 가지 통신을 지원하며 각각 선 개수, 속도, 장치 선택 방식이 다릅니다. 동시에 SRAM 2KB와 플래시 32KB라는 좁은 자원 안에서 전력까지 아껴야 합니다.","body":[{"h":"UART와 보율","t":"UART는 TX와 RX 두 선으로 데이터를 주고받는 비동기 통신이라 클럭선이 따로 없습니다. 대신 양쪽이 미리 같은 보율(baud rate)로 약속해야 하고, Serial.begin(9600)과 시리얼 모니터 설정이 다르면 화면에 깨진 문자가 쏟아집니다. Uno에서 하드웨어 시리얼은 디지털 0번(RX)과 1번(TX) 핀에 연결되어 있고 USB 업로드와 공유됩니다. 그래서 0번과 1번 핀에 장치를 연결한 채로 업로드하면 실패하기 쉽습니다."},{"h":"I2C는 2선 공유와 주소","t":"I2C는 SDA(데이터)와 SCL(클럭) 단 두 선을 여러 장치가 함께 씁니다. 마스터가 7비트 주소를 먼저 보내 그 주소를 가진 슬레이브 하나만 응답하게 만들어 장치를 구분합니다. 두 선 모두 풀업 저항이 필요하고 대개 4.7k옴 정도를 씁니다. 같은 주소를 가진 장치를 두 개 붙이면 충돌해서 둘 다 제대로 동작하지 않으므로 주소 점퍼를 바꾸거나 I2C 멀티플렉서를 씁니다. Uno의 I2C 핀은 A4(SDA)와 A5(SCL)입니다."},{"h":"SPI는 빠르지만 핀을 더 쓴다","t":"SPI는 MOSI, MISO, SCK 세 선을 모든 슬레이브가 공유하고, 슬레이브마다 별도의 CS(SS) 선을 하나씩 더 연결해 통신할 상대를 고릅니다. 주소 개념 없이 CS를 LOW로 내려 선택하므로 슬레이브가 늘면 핀도 그만큼 늘어납니다. 대신 클럭 속도가 높고 전이중이라 I2C보다 훨씬 빠릅니다. Uno에서는 11(MOSI), 12(MISO), 13(SCK), 10(기본 SS)이 SPI 핀입니다."},{"h":"전력과 메모리 제약","t":"배터리로 오래 동작해야 하면 avr/sleep.h의 슬립 모드로 CPU를 재우고 인터럽트나 워치독으로 깨우는 방식이 효과적입니다. Uno의 ATmega328P는 SRAM이 2KB뿐이라 문자열이나 배열을 많이 쓰면 금세 부족해지고 재부팅이나 이상 동작이 납니다. Serial.println(F(\"메시지\")) 처럼 F() 매크로로 문자열 리터럴을 32KB 플래시에 남겨 두면 RAM을 아낄 수 있습니다. 컴파일 후 출력되는 전역 변수 사용량 경고를 항상 확인하는 습관이 필요합니다."}],"code":{"c":"#include <Wire.h>\n#include <SPI.h>\n\nconst int CS_PIN = 10; // SPI 슬레이브별 CS\n\nvoid setup() {\n  Serial.begin(9600);          // 시리얼 모니터도 9600으로 맞출 것\n  Serial.println(F(\"boot ok\")); // F(): 문자열을 플래시에 두어 SRAM 절약\n\n  Wire.begin();                // I2C: A4=SDA, A5=SCL (풀업 필요)\n  Wire.beginTransmission(0x3C); // 7비트 주소로 슬레이브 지정\n  Wire.write(0x00);\n  Wire.endTransmission();\n\n  pinMode(CS_PIN, OUTPUT);\n  digitalWrite(CS_PIN, HIGH);  // 평소 비선택\n  SPI.begin();\n}\n\nvoid loop() {\n  digitalWrite(CS_PIN, LOW);   // 이 슬레이브만 선택\n  byte v = SPI.transfer(0x00);\n  digitalWrite(CS_PIN, HIGH);\n  Serial.println(v);\n  delay(1000);\n}","cap":"I2C는 7비트 주소로, SPI는 CS 핀으로 상대를 고르며 F() 매크로로 SRAM을 아낍니다."},"key":["UART는 클럭선 없이 비동기라 양쪽 보율이 다르면 깨진 문자가 나온다","I2C는 SDA/SCL 2선을 공유하고 7비트 주소로 슬레이브를 구분하며 풀업 저항이 필요하다","SPI는 MOSI/MISO/SCK 공유에 슬레이브마다 CS가 필요해 빠르지만 핀을 더 쓴다","Uno는 SRAM 2KB·플래시 32KB이며 F() 매크로로 문자열을 플래시에 두면 RAM을 절약한다"]}},{"t":"직접 이어 보기 — I2C 와 UART","th":{"sum":"I2C 는 두 가닥(SDA·SCL)으로 여러 장치를 잇는다. UART 는 두 가닥이지만 **서로 엇갈려** 이어야 한다.","body":[{"h":"I2C 는 같은 이름끼리","t":"SDA 는 SDA 로, SCL 은 SCL 로 잇는다. Uno 에서는 A4 가 SDA, A5 가 SCL 이다. 여러 장치를 같은 두 가닥에 나란히 붙일 수 있고, 주소로 구분한다. 접지(GND)를 공유하지 않으면 통신이 되지 않는다."},{"h":"UART 는 엇갈려서","t":"내 TX(보내기)는 상대의 RX(받기)로, 내 RX 는 상대의 TX 로 간다. TX 를 TX 에 이으면 둘 다 말만 하고 아무도 듣지 않는다. 이것도 GND 를 공유해야 기준 전압이 맞는다."}],"code":{"c":"// I2C:  SDA↔SDA, SCL↔SCL, GND 공유\n// UART: TX→RX, RX→TX, GND 공유","cap":"I2C 는 같은 이름, UART 는 엇갈려서"},"key":["I2C 는 SDA·SCL 같은 이름끼리","UART 는 TX↔RX 로 엇갈리게","어느 쪽이든 GND 를 공유한다"]},"q":[{"k":"I2C 디스플레이 잇기","cat":"internals","q":"I2C 디스플레이를 이으세요. Uno 의 <b>A4 가 SDA, A5 가 SCL</b> 입니다. 전원과 접지도 함께 이어야 합니다.","ex":"I2C 는 같은 이름끼리 잇습니다 — SDA 를 SCL 에 물리면 통신이 되지 않아요. 그리고 두 장치가 GND 를 공유해야 신호의 기준이 맞습니다. 공유하지 않으면 값이 제멋대로 들어옵니다.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["A4","A5","5V","GND"]},{"id":"oled","label":"I2C 디스플레이","pins":["VCC","GND","SDA","SCL"]}],"checks":[{"d":"SDA 끼리 이어진다 (A4)","link":["oled.SDA","uno.A4"]},{"d":"SCL 끼리 이어진다 (A5)","link":["oled.SCL","uno.A5"]},{"d":"VCC 가 5V 에 붙는다","link":["oled.VCC","uno.5V"]},{"d":"접지를 공유한다","link":["oled.GND","uno.GND"]},{"d":"SDA 와 SCL 이 서로 붙어 있지 않다","apart":["oled.SDA","oled.SCL"],"wires":true}],"start":[],"sol":[["oled.SDA","uno.A4"],["oled.SCL","uno.A5"],["oled.VCC","uno.5V"],["oled.GND","uno.GND"]]},{"k":"UART 를 엇갈려 잇기","cat":"internals","q":"블루투스 모듈을 UART 로 이으세요. <b>TX 는 RX 로, RX 는 TX 로</b> 엇갈려야 합니다. 접지도 공유합니다.","ex":"TX 를 TX 에, RX 를 RX 에 물려 놓았습니다. 둘 다 말만 하고 아무도 듣지 않아 한 글자도 오가지 않아요. 먼저 두 선을 지우고 엇갈려 다시 이으세요.","t":"wire","lv":1,"parts":[{"id":"uno","kind":"board","label":"Arduino Uno","pins":["TX","RX","5V","GND"]},{"id":"bt","label":"블루투스 모듈","pins":["VCC","GND","TX","RX"]}],"checks":[{"d":"모듈의 TX 가 보드의 RX 로 간다","link":["bt.TX","uno.RX"]},{"d":"모듈의 RX 가 보드의 TX 로 간다","link":["bt.RX","uno.TX"]},{"d":"TX 끼리 붙어 있지 않다","apart":["bt.TX","uno.TX"],"wires":true},{"d":"VCC 가 5V 에 붙는다","link":["bt.VCC","uno.5V"]},{"d":"접지를 공유한다","link":["bt.GND","uno.GND"]}],"start":[["bt.TX","uno.TX"],["bt.RX","uno.RX"]],"sol":[["bt.TX","uno.RX"],["bt.RX","uno.TX"],["bt.VCC","uno.5V"],["bt.GND","uno.GND"]]}]}],"ord":5},{"t":"타지 않게 만드는 법 — 전원과 전류","g":"⚡","l":[{"t":"전원과 전류 I","q":[{"t":"choice","k":"저항을 빼면","q":"LED 를 핀에 바로 이어 켰더니 잠깐 아주 밝게 켜졌다가 꺼져 버렸다. 저항이 하는 일은 무엇인가?","code":"핀 → LED → GND          저항 없음\n핀 → 220Ω → LED → GND   저항 있음","o":["저항은 밝기를 줄이려고 다는 것이 아니라 <b>흐르는 전류를 정해 주려고</b> 단다.","저항은 전압을 5V 에서 LED 용으로 바꿔 주는 변압 부품이며, 없으면 전압이 너무 높아 탄다","저항은 없어도 되며, 꺼진 것은 LED 불량이므로 새 LED 로 바꾸면 된다","저항은 극성을 맞춰 주는 부품이라 없으면 LED 가 반대로 연결된 셈이 된다"],"a":0,"ex":"LED 를 태우는 가장 흔한 방법이자, 가장 먼저 배워야 할 것.\n💡 개념: LED 는 전압이 조금만 올라가도 전류가 급격히 늘어나는 부품이라 스스로 전류를 제한하지 못한다. 앞에 저항을 두면 <code>전류 = (공급전압 − LED전압) ÷ 저항</code> 으로 값이 정해진다.\n🛠 실무: 5V 에 순방향 전압 2V 짜리 LED 를 10mA 로 켜려면 <code>(5−2) ÷ 0.01 = 300Ω</code> 이다. 흔히 쓰는 220Ω 이면 약 13.6mA 로 조금 밝다. 색마다 순방향 전압이 다르니(빨강은 낮고 파랑·흰색은 높다) 데이터시트 값으로 계산한다.\n✅ 왜 그 답인가: 저항이 없으면 전류를 제한하는 것이 사실상 없어 LED 나 핀이 견딜 수 있는 값을 넘어선다"},{"t":"choice","k":"핀 하나가 감당하는 양","cat":"design","q":"LED 세 개를 각각 20mA 로 켜려고 한 핀에 나란히 물렸다. Uno 기준으로 무엇이 문제인가?","code":"핀 하나 : 권장 20mA · 절대 최대 40mA\n칩 전체 : 합계 200mA\n\nLED 3개 × 20mA = 60mA  ← 한 핀에서","o":["핀은 전류 한도가 없고 전압만 맞으면 되므로 문제가 없다","핀 하나에서 60mA 를 뽑는 셈이라 <b>절대 최대치 40mA 도 넘는다</b>. 핀마다 따로 나눠 물리거나, 셋을 함께 켜야 한다면 트랜지스터로 스위칭해 전류를 전원에서 직접 받게 한다","핀은 전류 한도가 따로 없고 전압만 맞으면 되므로 아무 문제가 없다. LED 세 개 정도는 흔히 하는 배선이며, 밝기가 조금 줄어들 뿐 보드가 상하는 일은 생기지 않는다. 저항만 제대로 달면 된다","LED 를 병렬로 달면 전류가 3분의 1로 나뉘므로 오히려 안전하다"],"a":1,"ex":"'되긴 되는데' 와 '오래 버티는' 은 다르다 — 한도를 넘으면 당장은 켜져도 칩이 서서히 상한다.\n💡 개념: 병렬로 달면 전류는 나뉘는 것이 아니라 <b>더해진다</b>. 각 가지에 20mA 씩 흐르면 핀은 60mA 를 내보내야 한다. 게다가 핀별 한도와 별개로 칩 전체 합계 한도도 있어서, 핀을 나눠도 총량은 지켜야 한다.\n🛠 실무: 절대 최대치는 '여기까지는 안 부서진다' 는 값이지 권장치가 아니다. 설계는 권장치(핀당 20mA) 안에서 하고, 여러 개를 한꺼번에 켜야 하면 트랜지스터를 쓴다."},{"t":"choice","k":"전류를 내보낼 때와 받을 때","cat":"internals","q":"LED 를 <b>핀 → LED → GND</b> 로 달 때와 <b>5V → LED → 핀</b> 으로 달 때, 켜지는 조건이 어떻게 달라지는가?","code":"A) 핀 → 저항 → LED → GND\nB) 5V → 저항 → LED → 핀","o":["A 와 B 는 완전히 같은 회로이며 그리는 방식만 다르다","B 는 전류가 거꾸로 흘러 회로가 아예 성립하지 않으므로 절대 쓰지 않는 배선이다. LED 는 한 방향으로만 전류를 흘리므로 5V 쪽에서 핀 쪽으로 가는 연결은 어떤 경우에도 불이 들어오지 않는다","A 는 핀이 HIGH 일 때 켜지고(핀이 전류를 <b>내보낸다</b>), B 는 핀이 LOW 일 때 켜진다(핀이 전류를 <b>받아들인다</b>) — 코드의 HIGH·LOW 의미가 정반대가 된다","둘 다 핀이 HIGH 일 때 켜지며 배선 방향은 켜짐 조건과 무관하다"],"a":2,"ex":"같은 부품, 같은 코드인데 동작이 반대로 보이는 이유.\n💡 개념: 핀은 전류를 내보낼 수도 있고 받아들일 수도 있다. B 처럼 달면 핀이 LOW(0V)일 때 5V 와 사이에 전압 차가 생겨 전류가 흐르고, HIGH 면 양쪽이 같은 전압이라 흐르지 않는다.\n🛠 실무: 많은 칩이 <b>받아들이는 쪽 전류를 더 많이 감당</b>하도록 만들어져 있어 B 방식을 쓰는 회로가 흔하다. 남의 회로를 볼 때 LED 가 5V 쪽에 붙어 있으면 <code>digitalWrite(pin, LOW)</code> 가 '켜기' 라는 뜻이니 헷갈리지 않게 코드에 주석을 남긴다."},{"t":"choice","k":"USB 로 줄 수 있는 만큼","cat":"debug","q":"USB 로만 전원을 받는 보드에 서보 모터를 물렸더니 모터가 움직이는 순간 보드가 껐다 켜진 것처럼 처음부터 다시 시작한다. 원인은?","code":"USB 포트가 줄 수 있는 전류: 보통 500mA 안팎\n서보 하나가 움직일 때: 수백 mA ~ 1A 이상","o":["먼저 서보 제어 신호가 잘못되어 코드가 처음부터 다시 실행되는 것이므로 펄스 폭을 알맞게 고쳐 주면 그대로 해결된다. 전원 쪽과는 아무런 관련이 없는 문제로 보면 된다","보드가 과열되어 보호 회로가 동작한 것이므로 방열판을 붙이면 된다","USB 케이블이 데이터용이라 전원이 안 통하는 것이므로 케이블만 바꾸면 된다","모터가 순간적으로 큰 전류를 끌어당겨 <b>전압이 동작 하한 아래로 떨어지고 보드가 리셋</b>된다. 모터는 USB 가 아니라 별도 전원에서 받게 하고 접지만 함께 이어야 한다"],"a":3,"ex":"'코드가 이상하다' 로 며칠을 보내게 만드는 대표적인 전원 문제.\n💡 개념: 전원이 낼 수 있는 전류보다 많이 끌어당기면 전압이 주저앉는다. 마이크로컨트롤러는 전압이 일정 아래로 내려가면 오동작을 막으려 스스로 리셋한다 — 그래서 <b>코드가 처음부터 도는 것처럼</b> 보인다.\n🛠 실무: 모터·릴레이·LED 스트립처럼 큰 전류를 쓰는 것은 반드시 별도 전원으로 뺀다. 리셋이 의심되면 시작 함수에서 한 줄 찍어 보면 금방 확인된다 — 그 줄이 반복해서 찍히면 리셋이다."}],"th":{"sum":"소프트웨어는 틀리면 다시 짜면 됩니다. 회로는 틀리면 <b>부품이 타고 보드가 죽습니다</b>. 그런데 태우는 이유는 대개 한 가지예요 — 전류가 <b>얼마나</b> 흐를지 아무도 정해 주지 않았기 때문입니다.","body":[{"h":"전압은 걸고 전류는 흐른다","t":"전원이 정하는 것은 <b>전압</b>이고, 전류는 <b>회로가 알아서 정합니다</b> — <code>전류 = 전압 ÷ 저항</code>. 저항이 거의 없으면 전류는 부품이 견딜 수 있는 값을 훌쩍 넘어갑니다. LED 앞에 저항을 다는 이유가 '밝기 조절' 이 아니라 <b>전류를 정해 주기 위해서</b>인 까닭입니다."},{"h":"핀은 신호를 내보내는 곳이지 전원이 아니다","t":"보드의 디지털 핀 하나가 감당하는 전류는 <b>수십 mA</b> 수준이고, 칩 전체 합계에도 한도가 있습니다. 모터·릴레이·전구처럼 <b>수백 mA 이상</b>을 먹는 것은 핀으로 직접 켤 수 없어요. 핀은 트랜지스터에게 '켜라' 는 신호만 주고, 실제 전류는 <b>별도 전원에서 부품으로 바로</b> 흐르게 합니다."},{"h":"전원이 흔들리면 코드가 미쳐 보인다","t":"모터가 도는 순간 전압이 훅 떨어지면 보드가 리셋되거나 값이 튑니다. 코드를 아무리 들여다봐도 원인이 안 보이는 버그의 상당수가 <b>전원 문제</b>예요. 별도 전원을 쓰되 <b>접지는 반드시 이어</b> 두고, 부하 가까이에 커패시터를 붙여 순간적인 흔들림을 받아 줍니다."}],"code":{"t":"저항값은 계산해서 정한다","c":"LED 하나 켜기 — 공급 5V, LED 순방향 전압 2V, 목표 전류 10mA\n\n    저항에 걸리는 전압 = 5V - 2V = 3V\n    필요한 저항       = 3V ÷ 0.010A = 300Ω\n    (흔한 220Ω 을 쓰면  3V ÷ 220Ω = 약 13.6mA)\n\n핀 한도 (Uno 기준)\n    핀 하나  : 권장 20mA · 절대 최대 40mA\n    칩 전체  : 합계 200mA\n\n저항을 빼면?  3V ÷ 0(거의 없음) → 전류가 한계를 넘어 LED 나 핀이 죽는다"},"key":["전압은 전원이 정하고 전류는 저항이 정한다","핀은 신호용 — 큰 부하는 트랜지스터로 스위칭한다","전원을 따로 쓰더라도 접지(GND)는 반드시 잇는다","설명 안 되는 버그는 전원부터 의심한다"]}},{"t":"전원과 전류 II","q":[{"t":"choice","k":"모터를 핀에 직접","cat":"design","q":"DC 모터를 디지털 핀과 GND 사이에 바로 연결해 <code>digitalWrite(HIGH)</code> 로 돌리려 한다. 무슨 일이 일어나는가?","code":"핀 → 모터 → GND\n모터 기동 전류: 수백 mA ~ 수 A\n핀 한도       : 40mA","o":["모터가 요구하는 전류가 핀 한도의 수십 배라 <b>핀 회로가 손상된다</b>. 핀은 트랜지스터에 '켜라' 는 신호만 주고, 모터 전류는 별도 전원에서 트랜지스터를 거쳐 흐르게 해야 한다","핀이 자동으로 전류를 40mA 로 제한하므로 안전하다","전압이 5V 밖에 되지 않아 모터가 아예 돌지 않을 뿐이고 보드에는 아무 영향이 없다. 모터가 안 도는 것은 전압이 모자라서이므로 더 높은 전압을 쓰면 그대로 해결되는 문제다","모터가 천천히 돌 뿐 아무 문제도 없다"],"a":0,"ex":"핀은 '신호를 내는 곳' 이지 '전원 공급 단자' 가 아니다.\n💡 개념: 핀에는 전류를 알아서 제한해 주는 장치가 없다. 부하가 요구하는 만큼 흐르려 하고, 그 값이 한도를 넘으면 핀을 구동하는 회로가 상한다. 한 번에 안 죽더라도 조금씩 약해진다.\n🛠 실무: 트랜지스터(또는 MOSFET)를 스위치로 쓴다 — 핀은 트랜지스터의 제어 단자에 작은 전류만 주고, 모터 전류는 <b>별도 전원 → 모터 → 트랜지스터 → GND</b> 로 흐른다. 방향을 바꿔야 하면 모터 드라이버 모듈을 쓴다."},{"t":"choice","k":"코일을 끌 때 튀는 전압","cat":"internals","q":"릴레이를 트랜지스터로 잘 스위칭했는데, <b>끌 때마다</b> 보드가 가끔 리셋되거나 값이 튄다. 원인과 대책은?","code":"코일에 흐르던 전류를 갑자기 끊으면\n→ 코일이 전류를 유지하려 하며 순간적으로 높은 역방향 전압이 생긴다","o":["끄는 명령을 두 번 보내면 확실히 꺼지므로 해결된다","코일은 전류가 끊기는 순간 <b>반대 방향으로 높은 전압</b>을 만든다.","릴레이 접점이 튀는 것이므로 소프트웨어 디바운싱으로 해결한다","트랜지스터가 너무 느려서이므로 더 빠른 부품으로 바꾸면 해결된다"],"a":1,"ex":"'켤 때는 멀쩡한데 끌 때만' 이라는 증상이 거의 확정적인 단서다.\n💡 개념: 코일은 흐르던 전류를 계속 흘리려는 성질이 있다. 갑자기 길을 끊으면 그 에너지가 전압으로 솟아 트랜지스터나 주변 회로를 때린다. 다이오드를 코일과 나란히, 평소에는 전류가 안 흐르는 방향으로 달아 두면 이 순간에만 길을 내어 준다.\n🛠 실무: 릴레이·솔레노이드·DC 모터처럼 코일이 있는 것에는 모두 필요하다. 모듈 형태 릴레이 보드에는 대개 내장되어 있지만, 코일을 직접 물릴 때는 반드시 직접 달아야 한다. 방향을 거꾸로 달면 전원을 넣는 즉시 단락이 되니 극성을 확인한다.\n✅ 왜 그 답인가: 코일과 나란히 다이오드를 반대 방향으로 달아 그 전류가 코일 안에서 돌며 사그라지게 해야 한다"},{"t":"choice","k":"전원을 나누되 접지는 잇는다","cat":"debug","q":"모터에 별도 전원을 쓰기로 하고 전원부를 분리했더니, 이번에는 모터가 전혀 반응하지 않거나 제멋대로 움직인다. 무엇이 빠졌는가?","code":"보드 전원 : USB 5V\n모터 전원 : 어댑터 9V\n두 전원의 GND 는?","o":["별도 전원을 쓸 때는 신호선을 두 가닥으로 늘려야 한다","전원을 분리했으면 접지도 반드시 분리해야 하며, 이으면 단락이 된다","두 전원의 <b>접지를 서로 이어야</b> 한다.","9V 를 5V 로 낮춰야 하며 접지와는 무관하다"],"a":2,"ex":"'전원 분리' 를 배우고 나서 곧바로 만나는 두 번째 함정.\n💡 개념: 전압은 언제나 <b>두 점 사이의 차이</b>다. '3V 가 나온다' 는 말은 'GND 보다 3V 높다' 는 뜻이고, 상대 회로가 다른 GND 를 쓰면 그 3V 가 무엇에 비해 3V 인지 알 수 없다. 접지를 이어야 두 회로가 같은 자를 쓴다.\n🛠 실무: <b>전원(+)은 나누고 접지(−)는 합친다</b> 가 원칙이다. 다만 두 전원의 + 끼리는 절대 잇지 않는다. 보드에 외부 전원을 넣을 때도 USB 와 동시에 물리면 서로 밀어내는 상황이 될 수 있으니 보드가 어떻게 전원을 고르는지 확인한다.\n✅ 왜 그 답인가: 신호의 HIGH·LOW 는 그 회로의 GND 를 기준으로 정해지는데, 기준점이 따로 놀면 상대는 신호를 제대로 읽을 수 없다"},{"t":"choice","k":"레귤레이터가 뜨거운 이유","cat":"perf","q":"보드의 외부 전원 입력에 12V 어댑터를 꽂고 100mA 를 쓰는 회로를 돌렸더니 보드의 레귤레이터가 손을 못 댈 만큼 뜨겁다. 왜 그런가?","code":"입력 12V → 레귤레이터 → 출력 5V\n흐르는 전류 100mA\n버려지는 전압 = 12V - 5V = 7V","o":["12V 는 보드가 허용하는 정상 입력 범위 안에 있으므로 이 정도 발열은 정상이며 성능에도 아무 영향이 없다. 뜨거운 것이 걱정되면 손을 대지 않으면 되고 회로를 바꿀 필요는 없다","전류가 100mA 로 너무 작아 레귤레이터가 불안정해진 것이다","어댑터가 교류를 제대로 정류하지 못한 것이므로 어댑터를 바꾸면 된다","선형 레귤레이터는 남는 전압을 <b>열로 태워 없앤다</b>. <code>7V × 0.1A = 0.7W</code> 가 전부 열이 되므로, 입력 전압을 7~9V 로 낮추거나 열을 안 내는 방식의 전원을 쓴다"],"a":3,"ex":"입력 전압이 높을수록 손해다 — 그 차이가 전부 열이다.\n💡 개념: 선형 레귤레이터는 남는 전압을 저항처럼 소모해 출력을 맞춘다. 버리는 전력은 <code>(입력전압 − 출력전압) × 전류</code> 다. 같은 100mA 라도 입력이 7V 면 0.2W, 12V 면 0.7W 로 세 배 넘게 뜨거워진다.\n🛠 실무: 너무 뜨거우면 보호 기능이 걸려 전압이 끊겼다 붙었다 하고, 그러면 원인 모를 리셋이 된다. 외부 전원은 필요한 만큼만 높게 주고(보통 7~9V), 전류를 많이 쓴다면 열을 거의 안 내는 방식의 전원 모듈을 따로 쓴다."}],"th":{"sum":"소프트웨어는 틀리면 다시 짜면 됩니다. 회로는 틀리면 <b>부품이 타고 보드가 죽습니다</b>. 그런데 태우는 이유는 대개 한 가지예요 — 전류가 <b>얼마나</b> 흐를지 아무도 정해 주지 않았기 때문입니다.","body":[{"h":"전압은 걸고 전류는 흐른다","t":"전원이 정하는 것은 <b>전압</b>이고, 전류는 <b>회로가 알아서 정합니다</b> — <code>전류 = 전압 ÷ 저항</code>. 저항이 거의 없으면 전류는 부품이 견딜 수 있는 값을 훌쩍 넘어갑니다. LED 앞에 저항을 다는 이유가 '밝기 조절' 이 아니라 <b>전류를 정해 주기 위해서</b>인 까닭입니다."},{"h":"핀은 신호를 내보내는 곳이지 전원이 아니다","t":"보드의 디지털 핀 하나가 감당하는 전류는 <b>수십 mA</b> 수준이고, 칩 전체 합계에도 한도가 있습니다. 모터·릴레이·전구처럼 <b>수백 mA 이상</b>을 먹는 것은 핀으로 직접 켤 수 없어요. 핀은 트랜지스터에게 '켜라' 는 신호만 주고, 실제 전류는 <b>별도 전원에서 부품으로 바로</b> 흐르게 합니다."},{"h":"전원이 흔들리면 코드가 미쳐 보인다","t":"모터가 도는 순간 전압이 훅 떨어지면 보드가 리셋되거나 값이 튑니다. 코드를 아무리 들여다봐도 원인이 안 보이는 버그의 상당수가 <b>전원 문제</b>예요. 별도 전원을 쓰되 <b>접지는 반드시 이어</b> 두고, 부하 가까이에 커패시터를 붙여 순간적인 흔들림을 받아 줍니다."}],"code":{"t":"저항값은 계산해서 정한다","c":"LED 하나 켜기 — 공급 5V, LED 순방향 전압 2V, 목표 전류 10mA\n\n    저항에 걸리는 전압 = 5V - 2V = 3V\n    필요한 저항       = 3V ÷ 0.010A = 300Ω\n    (흔한 220Ω 을 쓰면  3V ÷ 220Ω = 약 13.6mA)\n\n핀 한도 (Uno 기준)\n    핀 하나  : 권장 20mA · 절대 최대 40mA\n    칩 전체  : 합계 200mA\n\n저항을 빼면?  3V ÷ 0(거의 없음) → 전류가 한계를 넘어 LED 나 핀이 죽는다"},"key":["전압은 전원이 정하고 전류는 저항이 정한다","핀은 신호용 — 큰 부하는 트랜지스터로 스위칭한다","전원을 따로 쓰더라도 접지(GND)는 반드시 잇는다","설명 안 되는 버그는 전원부터 의심한다"]}},{"t":"전원과 전류 III","q":[{"t":"choice","k":"3.3V 센서를 5V 보드에","cat":"design","q":"3.3V 로 동작하는 센서의 신호선을 5V 보드에 그대로 연결하려 한다. 어느 방향이 위험하며 어떻게 해야 하는가?","code":"센서 → 보드 (센서가 3.3V 를 내보냄)\n보드 → 센서 (보드가 5V 를 내보냄)","o":["<b>보드 → 센서</b> 방향이 위험하다. 5V 신호가 3.3V 부품에 들어가면 손상될 수 있으므로 전압을 낮춰 주어야 하고, 반대 방향은 대개 3.3V 를 HIGH 로 인식해 그대로 써도 되는 경우가 많다","양방향 모두 위험하지 않다. 전압이 다른 부품은 자동으로 맞춰진다","센서 → 보드 방향이 위험하다. 3.3V 신호는 5V 보드에서 HIGH 로 인식되지 않기 때문에 센서 쪽이 손상된다. 반대로 보드에서 센서로 가는 방향은 전압이 높은 쪽에서 낮은 쪽으로 흐르므로 언제나 안전하다","양방향 모두 불가능하므로 3.3V 보드로 바꾸는 것 외에는 방법이 없다"],"a":0,"ex":"방향에 따라 위험이 다르다는 점이 핵심이다.\n💡 개념: 부품은 자기 동작 전압보다 높은 전압이 핀에 들어오는 것을 못 견딘다. 반대로 낮은 전압이 들어오는 것은 '읽히느냐' 의 문제일 뿐 손상은 아니다. 5V 계열은 보통 3V 이상을 HIGH 로 보므로 3.3V 신호는 대개 읽힌다.\n🛠 실무: 내려 주는 쪽만 처리하면 되므로 저항 두 개로 나누는 간단한 방법도 쓸 수 있다 — 예를 들어 1.8kΩ 과 3.3kΩ 을 쓰면 <code>5 × 3.3 ÷ (1.8 + 3.3) ≈ 3.2V</code> 다. 다만 빠른 신호나 양방향 통신에는 전용 레벨 변환 모듈을 쓰는 편이 안전하다. <b>센서 데이터시트의 허용 전압을 먼저 확인</b>한다 — 5V 를 견디게 만들어진 모듈도 많다."},{"t":"choice","k":"기준 전압이 움직이면","cat":"debug","q":"배터리로 돌리는 센서 노드에서, 센서는 그대로인데 배터리가 닳을수록 <code>analogRead</code> 값이 조금씩 커진다. 원인은?","code":"analogRead 값 = 입력전압 ÷ 기준전압 × 1023\n기준 전압이 5.0V → 4.6V 로 내려가면?","o":["배터리가 닳으면 전원에 섞이는 잡음이 늘어나 값이 조금씩 커지는 것이며, 전원 단자 가까이에 커패시터를 하나 달아 주면 그대로 해결된다. 기준 전압이 무엇인지와는 아무런 관계가 없는 현상이다","변환 결과는 <b>기준 전압에 대한 비율</b>이라, 기준 전압이 내려가면 같은 입력도 더 큰 값으로 읽힌다. 기준을 칩 내부의 안정된 전압으로 바꾸거나, 기준 전압 자체를 함께 재서 보정해야 한다","센서가 배터리 전압에 반응하는 불량이므로 센서를 교체해야 한다","변환 값은 절대 전압이라 기준 전압과 무관하며 코드 버그다"],"a":1,"ex":"'천천히 어긋나는' 계측 오류의 단골 원인.\n💡 개념: 아날로그-디지털 변환은 입력을 기준 전압과 견주어 몇 분의 몇인지를 돌려준다. 기준이 곧 자(尺)인데, 그 자가 줄어들면 같은 물건이 더 길게 측정된다.\n🛠 실무: 정확도가 필요하면 칩 내부의 안정된 기준 전압을 쓰거나 외부에 정밀 기준 전압을 단다. 그러면 측정 범위는 좁아지지만 배터리가 닳아도 값이 흔들리지 않는다. 배터리 전압 자체를 감시해 <b>보정하거나 경고</b>하는 것도 함께 한다."},{"t":"choice","k":"부하 가까이 두는 커패시터","q":"센서 값이 평소에는 멀쩡한데 모터가 움직일 때만 크게 튄다. 배선은 맞고 접지도 이어져 있다. 무엇을 더 해야 하는가?","code":"모터 기동 → 순간적으로 큰 전류 → 전압이 잠깐 주저앉음\n              → 그 순간의 센서 측정값은?","o":["센서 읽기를 더 자주 해서 여러 번 평균을 내면 전기적인 문제까지 함께 해결된다 — 소프트웨어 쪽 처리만으로도 충분히 다룰 수 있는 문제다","전원 전압을 5V 에서 9V 로 올리면 흔들림이 줄어든다","부하와 칩의 전원 단자 <b>가까이에 커패시터</b>를 달아 순간적인 전류를 대신 공급하게 한다. 전압이 덜 흔들리면 그 순간의 측정값도 안정된다","모터와 센서의 접지를 서로 분리하면 해결된다"],"a":2,"ex":"소프트웨어 필터로 덮기 전에, 전기적으로 먼저 잡는 편이 낫다.\n💡 개념: 전원선에도 저항과 인덕턴스가 있어서 먼 곳의 전원은 급격한 요구에 즉시 응답하지 못한다. 부품 바로 옆의 커패시터는 그 짧은 순간에 필요한 전하를 대신 내어 주는 작은 저수지 역할을 한다.\n🛠 실무: 작은 값 하나를 칩 전원 핀 <b>바로 옆</b>에 두고, 모터처럼 큰 부하 쪽에는 큰 값을 하나 더 둔다. 거리가 멀면 효과가 크게 줄어드니 '가까이' 가 핵심이다. 그래도 남는 잡음은 이동평균 같은 소프트웨어 필터로 마무리한다."},{"t":"choice","k":"선이 길어지면","cat":"debug","q":"책상에서 잘 되던 센서를 20cm 짜리 점퍼선 여러 가닥으로 늘려 붙였더니 값이 불안정해졌다. 전기적으로 무엇이 달라졌는가?","code":"짧은 선 : 저항·잡음 유입 작음\n긴 선   : 전압 강하 + 주변 잡음을 더 많이 주워 옴","o":["선이 길수록 저항이 줄어 전류가 늘기 때문에 값이 흔들린다","선의 길이는 전기적으로 아무런 영향을 주지 않으므로 접촉 불량만 의심하면 된다. 점퍼선을 하나씩 다시 꽂아 보고 브레드보드의 접점 위치를 바꿔 끼워 보면 대개 그대로 해결되는 문제다","점퍼선은 디지털 신호 전용이라 아날로그 센서에는 원래 쓸 수 없다","선 자체의 저항으로 <b>전압이 조금 떨어지고</b>, 길어진 만큼 주변의 전기적 잡음을 더 많이 주워 온다. 전원선을 굵고 짧게 하고, 신호선은 접지선과 나란히 두거나 차폐된 선을 쓴다"],"a":3,"ex":"'브레드보드에서는 됐는데' 의 상당수가 여기서 나온다.\n💡 개념: 도선에도 저항이 있어 전류가 흐르면 양 끝에 전압 차가 생긴다. 또 긴 선은 안테나처럼 주변의 전자기 잡음을 받아들인다. 아날로그 신호는 이 잡음이 곧바로 측정값 오차가 된다.\n🛠 실무: 전원과 접지는 굵고 짧게, 신호선은 되도록 짧게 한다. 어쩔 수 없이 길어지면 신호선과 접지선을 나란히 붙여 꼬아 두면 잡음이 크게 준다. 그리고 브레드보드의 접촉 자체가 불안정하니, 잘 되던 것이 안 되면 <b>선을 다시 꽂아 보는 것</b>도 진짜 진단이다."}],"th":{"sum":"소프트웨어는 틀리면 다시 짜면 됩니다. 회로는 틀리면 <b>부품이 타고 보드가 죽습니다</b>. 그런데 태우는 이유는 대개 한 가지예요 — 전류가 <b>얼마나</b> 흐를지 아무도 정해 주지 않았기 때문입니다.","body":[{"h":"전압은 걸고 전류는 흐른다","t":"전원이 정하는 것은 <b>전압</b>이고, 전류는 <b>회로가 알아서 정합니다</b> — <code>전류 = 전압 ÷ 저항</code>. 저항이 거의 없으면 전류는 부품이 견딜 수 있는 값을 훌쩍 넘어갑니다. LED 앞에 저항을 다는 이유가 '밝기 조절' 이 아니라 <b>전류를 정해 주기 위해서</b>인 까닭입니다."},{"h":"핀은 신호를 내보내는 곳이지 전원이 아니다","t":"보드의 디지털 핀 하나가 감당하는 전류는 <b>수십 mA</b> 수준이고, 칩 전체 합계에도 한도가 있습니다. 모터·릴레이·전구처럼 <b>수백 mA 이상</b>을 먹는 것은 핀으로 직접 켤 수 없어요. 핀은 트랜지스터에게 '켜라' 는 신호만 주고, 실제 전류는 <b>별도 전원에서 부품으로 바로</b> 흐르게 합니다."},{"h":"전원이 흔들리면 코드가 미쳐 보인다","t":"모터가 도는 순간 전압이 훅 떨어지면 보드가 리셋되거나 값이 튑니다. 코드를 아무리 들여다봐도 원인이 안 보이는 버그의 상당수가 <b>전원 문제</b>예요. 별도 전원을 쓰되 <b>접지는 반드시 이어</b> 두고, 부하 가까이에 커패시터를 붙여 순간적인 흔들림을 받아 줍니다."}],"code":{"t":"저항값은 계산해서 정한다","c":"LED 하나 켜기 — 공급 5V, LED 순방향 전압 2V, 목표 전류 10mA\n\n    저항에 걸리는 전압 = 5V - 2V = 3V\n    필요한 저항       = 3V ÷ 0.010A = 300Ω\n    (흔한 220Ω 을 쓰면  3V ÷ 220Ω = 약 13.6mA)\n\n핀 한도 (Uno 기준)\n    핀 하나  : 권장 20mA · 절대 최대 40mA\n    칩 전체  : 합계 200mA\n\n저항을 빼면?  3V ÷ 0(거의 없음) → 전류가 한계를 넘어 LED 나 핀이 죽는다"},"key":["전압은 전원이 정하고 전류는 저항이 정한다","핀은 신호용 — 큰 부하는 트랜지스터로 스위칭한다","전원을 따로 쓰더라도 접지(GND)는 반드시 잇는다","설명 안 되는 버그는 전원부터 의심한다"]}},{"t":"전원과 전류 IV","q":[{"t":"choice","k":"멀티미터를 대는 자리","q":"회로에 흐르는 전류를 재려고 멀티미터를 전압 잴 때처럼 부품 양끝에 갖다 댔더니 값이 0 에 가깝게 나온다. 무엇이 잘못됐는가?","code":"전압 측정 : 부품 양끝에 나란히 댄다\n전류 측정 : 회로를 끊고 그 사이에 끼워 넣는다","o":["전류는 <b>회로를 끊고 그 자리에 미터를 끼워</b> 전류가 미터를 통과하게 해야 잰다. 전압처럼 나란히 대면 전류가 미터로 흐르지 않아 값이 나오지 않는다","전류를 재려면 전원을 끄고 재야 하며 켜 둔 상태에서는 0 이 나온다","전류도 부품 양끝에 나란히 대는 것이 맞으며, 미터의 측정 범위 설정만 전류 쪽으로 바꿔 주면 값이 제대로 나온다. 다이얼을 A 쪽으로 돌리기만 하면 된다","전류는 멀티미터로 잴 수 없고 전용 장비가 필요하다"],"a":0,"ex":"재는 방법이 다른 이유는 두 값의 성질이 다르기 때문이다.\n💡 개념: 전압은 '두 점 사이의 차이' 라 두 점에 대면 되고, 전류는 '한 지점을 지나는 흐름' 이라 그 흐름 위에 미터를 놓아야 한다. 그래서 전류 측정은 회로를 한 번 끊어야 한다.\n🛠 실무: 전류 모드로 둔 채 전압을 재듯 대면 미터가 거의 단락 상태라 <b>미터 내부 퓨즈가 끊어지거나 회로가 손상</b>된다. 전류를 잰 뒤에는 반드시 전압 모드로 되돌려 놓는 습관을 들인다. 대부분의 문제는 사실 전압 측정만으로도 짚어진다 — 전원 핀에서 정말 5V 가 나오는지부터 본다."},{"t":"choice","k":"처음 전원을 넣기 전에","cat":"ops","q":"새로 만든 회로에 처음 전원을 넣으려 한다. 부품을 태우지 않기 위해 <b>전원을 넣기 전에</b> 확인할 것으로 가장 중요한 것은?","code":"전원 OFF 상태에서 저항 측정\n    5V 와 GND 사이 저항이 0Ω 에 가깝다면?","o":["코드를 먼저 업로드해 두면 회로가 잘못되어도 소프트웨어가 막아 준다","전원을 넣지 않은 상태에서 <b>전원과 접지 사이가 단락되지 않았는지</b> 저항으로 확인하고, 부품 극성과 전원 전압을 함께 점검한다. 단락된 채로 전원을 넣으면 그 순간 부품이 상한다","일단 전원을 넣어 보고 연기가 나는지 눈으로 지켜보는 것이 가장 확실한 확인 방법이다. 문제가 있으면 바로 티가 나므로 그때 전원을 끄면 되고, 미리 하나씩 재 보는 것보다 빠르다","전압을 절반으로 낮춰 넣어 보면 잘못된 회로도 안전하게 확인할 수 있다"],"a":1,"ex":"고칠 기회는 전원을 넣기 전까지만 있다.\n💡 개념: 전원과 접지가 이어져 있으면(단락) 전류를 막는 것이 없어 전원이나 배선이 순식간에 뜨거워진다. 전원을 끈 상태의 저항 측정으로 이걸 미리 잡을 수 있다.\n🛠 실무: 순서를 정해 두면 좋다 — ① 전원 끄고 전원·접지 사이 저항 확인 ② 전해 커패시터·다이오드·IC 의 극성 확인 ③ 어댑터 전압과 극성 확인 ④ 부하를 뺀 상태로 먼저 전원을 넣고 전압 확인 ⑤ 그다음 부하 연결. 소프트웨어는 이미 흐르기 시작한 전류를 막지 못한다."},{"t":"choice","k":"안 쓰는 핀과 남는 선","q":"회로를 정리하면서 쓰지 않는 핀들과 남는 선을 어떻게 두는 것이 좋은가?","code":"쓰지 않는 입력 핀 : 아무 데도 안 이어져 있음\n남는 전원선       : 끝이 노출된 채 굴러다님","o":["남는 선은 길이가 길수록 주변의 잡음을 흡수해 주므로 자르지 말고 그대로 두는 편이 낫다. 쓰지 않는 핀도 손대지 말고 처음 초기 상태 그대로 두면 아무런 문제가 생기지 않는다","쓰지 않는 핀은 모두 출력으로 설정하고 HIGH 를 내보내야 한다","노출된 전원선 끝은 다른 곳에 닿아 <b>단락을 만들 수 있으니</b> 정리하거나 절연한다. 쓰지 않는 입력 핀은 값이 떠다니므로 코드에서 읽지 않거나 내부 풀업을 켜 두는 편이 안전하다","쓰지 않는 핀은 모두 5V 에 이어 두어야 안정된다"],"a":2,"ex":"회로를 태우는 사고의 상당수는 설계가 아니라 <b>정리 안 된 선</b>에서 난다.\n💡 개념: 아무 데도 안 이어진 입력 핀은 주변 전기장에 따라 값이 오르내려 읽을 때마다 다른 값이 나온다. 손상되지는 않지만 읽으면 의미 없는 값이다. 반면 노출된 전원선은 실제 위험이다.\n🛠 실무: 남는 선은 뽑거나 절연한다. 특히 브레드보드에서 전원선이 슬쩍 밀려 옆 열에 닿는 사고가 잦다. 쓰지 않는 핀은 굳이 5V 나 GND 에 직접 잇지 말고 그냥 두거나 내부 풀업을 켠다 — <b>출력으로 설정해 두면 실수로 외부와 부딪칠 때 오히려 위험하다</b>."},{"t":"choice","k":"설명 안 되는 버그","cat":"debug","q":"코드를 몇 번을 봐도 맞는데 동작이 들쭉날쭉하다. 어제는 됐고 오늘은 안 된다. 소프트웨어를 더 파기 전에 무엇을 먼저 확인해야 하는가?","code":"증상: 재현이 잘 안 됨 · 손으로 만지면 달라짐 · 가끔 처음부터 다시 시작","o":["코드를 처음부터 다시 작성하는 것이 가장 빠르다","라이브러리 버전 문제이므로 모든 라이브러리를 최신으로 올린다","보드가 불량이므로 새 보드로 교체하는 것이 우선이다","<b>전원과 접촉</b>을 먼저 본다"],"a":3,"ex":"임베디드에서 '간헐적' 이라는 말은 대개 소프트웨어가 아니라는 뜻이다.\n💡 개념: 소프트웨어 버그는 대체로 <b>같은 조건에서 같게</b> 재현된다. 만질 때마다 달라지고 날마다 다르다면 접촉 저항, 전압 강하, 잡음처럼 물리적인 원인일 가능성이 훨씬 크다.\n🛠 실무: 순서를 정해 두면 시간을 아낀다 — ① 전원 핀에서 실제 전압을 재고 ② 모든 접지가 이어졌는지 확인하고 ③ 점퍼선을 하나씩 다시 꽂아 보고 ④ 부하를 떼어 낸 최소 구성으로 줄여 본다. 여기까지 해서 증상이 사라지면 소프트웨어는 처음부터 문제가 아니었던 것이다.\n✅ 왜 그 답인가: 전원 핀 실제 전압, 접지가 모두 이어졌는지, 브레드보드 접촉과 헐거운 점퍼선. 재현이 안 되고 만지면 달라지는 증상은 소프트웨어보다 전기 쪽 신호다"}],"th":{"sum":"소프트웨어는 틀리면 다시 짜면 됩니다. 회로는 틀리면 <b>부품이 타고 보드가 죽습니다</b>. 그런데 태우는 이유는 대개 한 가지예요 — 전류가 <b>얼마나</b> 흐를지 아무도 정해 주지 않았기 때문입니다.","body":[{"h":"전압은 걸고 전류는 흐른다","t":"전원이 정하는 것은 <b>전압</b>이고, 전류는 <b>회로가 알아서 정합니다</b> — <code>전류 = 전압 ÷ 저항</code>. 저항이 거의 없으면 전류는 부품이 견딜 수 있는 값을 훌쩍 넘어갑니다. LED 앞에 저항을 다는 이유가 '밝기 조절' 이 아니라 <b>전류를 정해 주기 위해서</b>인 까닭입니다."},{"h":"핀은 신호를 내보내는 곳이지 전원이 아니다","t":"보드의 디지털 핀 하나가 감당하는 전류는 <b>수십 mA</b> 수준이고, 칩 전체 합계에도 한도가 있습니다. 모터·릴레이·전구처럼 <b>수백 mA 이상</b>을 먹는 것은 핀으로 직접 켤 수 없어요. 핀은 트랜지스터에게 '켜라' 는 신호만 주고, 실제 전류는 <b>별도 전원에서 부품으로 바로</b> 흐르게 합니다."},{"h":"전원이 흔들리면 코드가 미쳐 보인다","t":"모터가 도는 순간 전압이 훅 떨어지면 보드가 리셋되거나 값이 튑니다. 코드를 아무리 들여다봐도 원인이 안 보이는 버그의 상당수가 <b>전원 문제</b>예요. 별도 전원을 쓰되 <b>접지는 반드시 이어</b> 두고, 부하 가까이에 커패시터를 붙여 순간적인 흔들림을 받아 줍니다."}],"code":{"t":"저항값은 계산해서 정한다","c":"LED 하나 켜기 — 공급 5V, LED 순방향 전압 2V, 목표 전류 10mA\n\n    저항에 걸리는 전압 = 5V - 2V = 3V\n    필요한 저항       = 3V ÷ 0.010A = 300Ω\n    (흔한 220Ω 을 쓰면  3V ÷ 220Ω = 약 13.6mA)\n\n핀 한도 (Uno 기준)\n    핀 하나  : 권장 20mA · 절대 최대 40mA\n    칩 전체  : 합계 200mA\n\n저항을 빼면?  3V ÷ 0(거의 없음) → 전류가 한계를 넘어 LED 나 핀이 죽는다"},"key":["전압은 전원이 정하고 전류는 저항이 정한다","핀은 신호용 — 큰 부하는 트랜지스터로 스위칭한다","전원을 따로 쓰더라도 접지(GND)는 반드시 잇는다","설명 안 되는 버그는 전원부터 의심한다"]}}],"ord":6},{"t":"움직이게 만들기 — 모터와 액추에이터","g":"⚙","l":[{"t":"모터 제어 I","q":[{"t":"choice","k":"무엇으로 움직일까","cat":"design","q":"로봇 팔의 관절을 <b>정해진 각도로</b> 움직이려 한다. DC 모터·서보·스텝모터 중 무엇이 맞고 왜인가?","code":"DC     계속 돈다 · 각도를 모른다\n서보    정해진 각도로 가서 버틴다\n스텝    한 칸씩 정확히 움직인다","o":["<b>서보</b> — 각도를 지시하면 내부에서 현재 위치를 재어 그 각도로 가서 버틴다. DC 는 각도 개념이 없고, 스텝모터는 각도 대신 '몇 칸' 으로 움직여 시작 위치를 따로 알아야 한다","셋 다 각도 제어가 되므로 가장 싼 것을 고르면 된다","DC 모터 — 전압을 조절하면 원하는 각도에서 정확히 멈출 수 있다. 전압과 회전 각도가 비례하므로 각도를 정해 두고 그에 맞는 전압만 걸어 주면 되고, 별도의 위치 센서도 필요 없다","스텝모터 — 각도 제어에는 스텝모터만 쓸 수 있다"],"a":0,"ex":"'무엇을 시키고 싶은가' 가 부품을 정한다.\n💡 개념: 서보는 모터·기어·위치 센서·제어 회로가 한 덩어리로 들어 있다. 그래서 '90도' 라고 지시하면 알아서 그 각도로 가고, 밀려도 되돌아온다. DC 모터는 '돌아라' 만 알아듣고 지금 어디인지 모른다.\n🛠 실무: 스텝모터도 정확하지만 <b>전원을 켠 순간의 위치를 모른다</b> — 그래서 시작할 때 한쪽 끝까지 밀어 기준점을 잡는 과정이 필요하다. 일반 서보는 보통 180도 안쪽만 돌고 계속 회전은 못 한다는 점도 함께 본다."},{"t":"choice","k":"서보에 보내는 신호","cat":"internals","q":"서보의 각도를 정하는 것은 무엇인가?","code":"20ms 주기 안에서\n  1.0ms 펄스 →   0°\n  1.5ms 펄스 →  90°\n  2.0ms 펄스 → 180°","o":["신호의 전압 크기가 각도를 정한다","주기 안에서 <b>신호가 켜져 있는 시간(펄스 폭)</b>이다","PWM 듀티 비율이며 0~255 값이 그대로 0~180도에 대응한다","신호의 주파수가 각도를 정하며 주파수를 높이면 더 돌아간다"],"a":1,"ex":"<code>analogWrite</code> 로 서보를 돌리려다 안 되는 이유가 여기 있다.\n💡 개념: 일반 PWM 은 '한 주기 중 몇 %를 켜 두느냐' 로 평균 전압을 만든다. 서보는 그 평균을 보지 않고 <b>펄스가 얼마나 길었는지</b>를 잰다. 그래서 주기가 달라지면 같은 듀티라도 다른 각도가 된다.\n🛠 실무: 그래서 서보 라이브러리는 각도나 마이크로초를 받아 <b>정확한 폭의 펄스</b>를 만들어 준다. 다만 이 라이브러리가 내부에서 타이머를 쓰기 때문에 특정 PWM 핀과 충돌할 수 있다 — 서보를 붙인 뒤 다른 핀의 PWM 이 이상해지면 이걸 의심한다.\n✅ 왜 그 답인가: 보통 20ms 주기에 1~2ms 범위이며, 듀티 비율 자체가 아니라 <b>밀리초 단위의 폭</b>이 각도를 정한다"},{"t":"choice","k":"몇 칸 움직일까","q":"스텝 각도가 1.8도인 스텝모터를 <b>정확히 한 바퀴</b> 돌리려면 몇 스텝을 보내야 하는가?","code":"한 바퀴 360도 · 스텝 각도 1.8도","o":["360스텝 — 각도 하나당 한 스텝이다","180스텝 — 1.8도이므로 180으로 나눈다","<b>200스텝</b> — 360 ÷ 1.8 = 200 이다.","스텝 수는 속도에 따라 달라지므로 정해진 값이 없다"],"a":2,"ex":"스텝모터의 장점과 불편함이 같은 지점에서 나온다.\n💡 개념: 스텝모터는 코일을 순서대로 켜서 정해진 각도만큼 한 칸씩 밀어 낸다. 그래서 위치 센서 없이도 정확하지만, <b>지금 몇 칸에 있는지는 코드가 세고 있어야</b> 한다.\n🛠 실무: 세부 분할 구동을 쓰면 한 칸을 더 잘게 쪼갤 수 있어 더 부드럽고 조용해진다. 대신 힘이 줄고 계산할 스텝 수가 배로 는다. 그리고 <b>힘에 부쳐 한 칸을 놓치면</b> 코드가 세는 위치와 실제 위치가 어긋나는데, 개루프라 이걸 알아챌 방법이 없다.\n✅ 왜 그 답인가: 각도가 아니라 칸 수로 지시하므로 계산해서 보내야 한다"},{"t":"choice","k":"드라이버가 하는 일","cat":"design","q":"모터 드라이버 칩이 트랜지스터 하나로는 못 하는 것을 해 준다. 무엇인가?","code":"트랜지스터 1개  → 켜기·끄기 (한 방향)\n드라이버       → ?","o":["PWM 신호를 아날로그 전압으로 바꿔 준다","모터의 회전 속도를 정밀하게 재어 알려 준다","모터가 필요한 전류를 스스로 만들어 낸다","<b>회전 방향을 바꾸는 것</b>이다"],"a":3,"ex":"'켜고 끄기' 와 '앞뒤로 돌리기' 는 회로가 다르다.\n💡 개념: 트랜지스터 하나는 전류를 흘리거나 막을 뿐이라 한 방향으로만 돌릴 수 있다. 네 개를 엮으면 어느 쌍을 켜느냐에 따라 전류 방향이 뒤집혀 반대로 돈다. 이 구조를 다리 모양에 빗대어 H 브리지라 부른다.\n🛠 실무: 직접 만들면 <b>같은 쪽 위아래를 동시에 켜는 순간</b> 전원이 그대로 접지로 단락된다 — 방향을 바꿀 때 잠깐 둘 다 끄는 시간을 둬야 한다. 드라이버 칩은 이 보호가 들어 있어 초보 단계에서는 칩을 쓰는 편이 안전하다.\n✅ 왜 그 답인가: 스위치 네 개를 다리처럼 엮어 모터에 걸리는 전압의 방향을 뒤집는다. 여기에 역기전력 보호와 과열·과전류 보호까지 한 칩에 들어 있는 경우가 많다"}],"th":{"sum":"LED 를 켜는 것과 무언가를 <b>움직이는 것</b> 사이에는 큰 턱이 하나 있습니다. 모터는 전류를 수백 배 더 먹고, 멈출 때 전기를 되뿜고, 소프트웨어가 죽어도 <b>혼자 계속 돕니다</b>. 그래서 회로도 코드도 다르게 짜야 합니다.","body":[{"h":"무엇을 움직일지가 부품을 정한다","t":"<b>계속 돌아야 하면</b> DC 모터, <b>정해진 각도로 가야 하면</b> 서보, <b>정확히 몇 칸 움직여야 하면</b> 스텝모터입니다. 셋은 제어 방법도 완전히 달라요 — DC 는 전압을 조절하고, 서보는 <b>펄스 폭으로 각도를 지시</b>하고, 스텝모터는 코일을 순서대로 켜서 한 칸씩 밀어 냅니다."},{"h":"핀은 지시만 하고 전류는 따로 흐른다","t":"모터는 수백 mA 에서 수 A 를 먹으니 핀으로 직접 켤 수 없습니다. 앞에서 배운 트랜지스터 스위치를 쓰되, <b>방향까지 바꾸려면</b> 스위치 네 개를 다리처럼 엮은 <b>H 브리지</b>가 필요해요. 요즘은 이걸 칩 하나로 만든 <b>모터 드라이버</b>를 씁니다."},{"h":"소프트웨어가 멈춰도 모터는 안 멈춘다","t":"화면이 멈추면 사용자가 불편할 뿐이지만, <b>모터가 멈추지 않으면 무언가가 부러집니다</b>. 코드가 무한 루프에 빠져도 정지 신호가 가도록 <b>감시 장치와 물리적 한계 스위치</b>를 둬야 해요. 움직이는 것을 다룰 때는 '잘 도는 코드' 보다 '<b>안전하게 멈추는 코드</b>' 가 먼저입니다."}],"code":{"t":"세 가지 모터, 세 가지 신호","c":"DC 모터     PWM 듀티로 속도 · H 브리지로 방향\n            듀티 0~255 → 평균 전압 → 회전 속도\n\n서보        20ms 주기에 펄스 폭으로 각도를 지시 (PWM 듀티가 아니다)\n            1.0ms → 0°   1.5ms → 90°   2.0ms → 180°\n\n스텝모터     코일을 순서대로 켜 한 칸씩\n            1.8°/스텝 → 한 바퀴 200스텝\n\n전류은 언제나 별도 전원에서 → 드라이버 → 모터\n접지는 보드와 반드시 공유"},"key":["계속 돌리면 DC, 각도면 서보, 정확한 칸이면 스텝모터","서보는 듀티가 아니라 펄스 폭으로 각도를 지시한다","방향까지 바꾸려면 H 브리지가 필요하다","움직이는 것에는 멈추는 장치를 먼저 만든다"]}},{"t":"모터 제어 II","q":[{"t":"choice","k":"속도를 줄이는 방법","cat":"internals","q":"DC 모터를 절반 속도로 돌리려 한다. <b>전압을 절반으로 낮추는 대신 PWM 으로 껐다 켜는</b> 이유는?","code":"방법 A  전압을 12V → 6V 로 낮춤\n방법 B  12V 를 절반만 켜 둠 (듀티 50%)","o":["전압을 낮추려면 남는 전압을 <b>열로 태워야</b> 하지만, 껐다 켜는 방식은 켜졌을 때 완전히 켜지고 꺼졌을 때 완전히 꺼져 <b>거의 열이 안 난다</b> — 모터는 관성이 있어 빠르게 껐다 켜면 평균값으로 부드럽게 돈다","전압을 낮추면 모터가 손상되기 때문이다","PWM 이 전압 조절보다 더 정밀한 속도 제어를 제공하기 때문이며 발열과는 아무 상관이 없다. 두 방법 모두 열은 비슷하게 나지만 PWM 쪽이 단계를 더 잘게 나눌 수 있어서 쓰는 것이고, 모터의 관성과도 무관하다","전압 조절 회로는 존재하지 않기 때문이다"],"a":0,"ex":"앞서 본 레귤레이터 발열과 정확히 같은 이야기다.\n💡 개념: 전압을 떨어뜨리는 소자는 그 차이만큼 전력을 열로 버린다. 스위치는 켜졌을 때 저항이 거의 없고 꺼졌을 때 전류가 없으니 어느 쪽에서도 소모가 적다. 모터와 그 관성이 켜짐·꺼짐을 평균해 준다.\n🛠 실무: 다만 <b>아주 낮은 듀티에서는 아예 안 돈다</b> — 모터가 움직이기 시작하려면 최소한의 힘이 필요하기 때문이다. 그래서 0~255 를 그대로 속도에 대응시키면 앞쪽 구간이 죽어 있다. 실제로 도는 최소 듀티를 재서 그 위에서 매핑한다."},{"t":"choice","k":"모터가 우는 이유","cat":"debug","q":"PWM 으로 모터 속도를 조절했더니 모터에서 <b>높은 소리</b>가 난다. 원인과 대응은?","code":"PWM 주파수 490Hz  → 귀에 들린다\nPWM 주파수 20kHz 이상 → 안 들린다","o":["모터가 고장 나기 직전의 신호이므로 교체해야 한다","PWM 주파수가 <b>사람이 들을 수 있는 대역</b>에 있어 코일이 그 주파수로 떨리기 때문이다 — 주파수를 가청 범위 위로 올리면 소리가 사라진다","전원 전압이 낮아서 생기는 현상이며 전압을 조금 올려 주면 소리가 사라진다. 전압이 모자라면 코일이 제대로 자리를 잡지 못해 떨리게 되는 것이다","듀티가 너무 높아서이며 낮추면 사라진다"],"a":1,"ex":"'삐 소리' 는 대개 고장이 아니라 <b>주파수 선택의 결과</b>다.\n💡 개념: PWM 은 전류를 껐다 켜기를 반복하고, 그 리듬대로 코일이 미세하게 진동한다. 그 진동수가 사람 귀에 들리는 범위라면 소리로 들린다. 주파수를 20kHz 위로 올리면 진동은 그대로지만 귀에 안 들린다.\n🛠 실무: 보드마다 PWM 주파수를 바꾸는 방법이 다르고, 타이머를 건드리면 <b>다른 기능이 함께 영향을 받는다</b>(시간 함수, 다른 핀의 PWM). 그리고 주파수를 올릴수록 스위칭 손실이 늘어 드라이버가 더 뜨거워지니 무작정 높이지는 않는다."},{"t":"choice","k":"가장 많이 먹는 순간","cat":"perf","q":"모터를 고를 때 정격 전류만 보고 전원을 정했다가 <b>기동할 때</b> 문제가 생긴다. 왜 그런가?","code":"정격(돌고 있을 때)  0.3A\n기동·정지 순간      1.5A 이상\n걸려서 멈췄을 때     더 큼","o":["기동 시에는 전압이 올라가 전류가 늘어나는 것이다","정격 전류만 보면 되고 기동할 때의 전류는 제조사가 알아서 보정해 준다. 요즘 드라이버에는 기동 전류를 억제하는 회로가 들어 있어 따로 계산할 필요가 없다","멈춰 있던 모터를 돌리기 시작할 때와 <b>무언가에 걸려 안 돌 때</b> 전류가 정격의 몇 배로 뛴다 — 전원과 드라이버는 그 최댓값을 견딜 수 있어야 한다","정격 전류는 평균값이라 실제로는 항상 그보다 조금 크다"],"a":2,"ex":"'돌 때는 멀쩡한데 시작할 때 보드가 리셋된다' 의 원인.\n💡 개념: 회전이 시작되면 모터 자체가 전류를 억제하는 힘을 만들어 낸다. 멈춰 있을 때는 그 힘이 없어 코일 저항만 남고, 그래서 전류가 크게 흐른다. 무언가에 걸려 멈춘 상태가 가장 나쁘다 — 계속 큰 전류가 흐르며 열이 쌓인다.\n🛠 실무: 전원과 드라이버는 <b>걸려 멈췄을 때의 전류</b>를 기준으로 고른다. 그리고 소프트웨어에서 서서히 속도를 올리면 기동 전류가 완만해지고, 일정 시간 이상 걸려 있으면 꺼 버리는 보호도 함께 넣는다."},{"t":"choice","k":"갑자기 반대로 돌리면","cat":"debug","q":"빠르게 돌던 모터를 <b>곧바로 반대 방향</b>으로 지시했더니 드라이버가 뜨거워지고 가끔 보드가 리셋된다. 무슨 일이 벌어지는가?","code":"정방향 최고 속도 → (즉시) → 역방향 최고 속도","o":["모터는 원래 도는 방향을 바로 바꿀 수 없고 완전히 정지시킨 뒤 다시 시작하는 것만 가능하다. 드라이버가 뜨거워지는 것은 그 제약을 어겨서 생기는 보호 동작이다","역방향 신호가 노이즈로 해석되어 드라이버가 오동작하는 것이다","방향 전환은 전류와 무관하며 드라이버 불량이다","관성으로 계속 돌고 있는 모터에 반대 전압이 걸려 <b>기동보다 큰 전류</b>가 흐른다 — 잠시 멈춤을 두거나 속도를 0 까지 내렸다 반대로 올리는 식으로 완충해야 한다"],"a":3,"ex":"'급정거보다 급후진이 나쁘다' 는 것이 전기적으로도 참이다.\n💡 개념: 돌고 있는 모터는 발전기처럼 전압을 만들어 낸다. 여기에 반대 방향 전압을 걸면 두 전압이 더해진 것처럼 되어 전류가 크게 흐른다. 그 에너지는 전부 드라이버와 모터에서 열이 된다.\n🛠 실무: 속도 명령을 바로 반영하지 말고 <b>목표값을 향해 조금씩 따라가게</b> 만들면 기동·정지·방향 전환이 모두 완만해진다. 코드 몇 줄로 부품 수명이 크게 달라지는 부분이다."}],"th":{"sum":"LED 를 켜는 것과 무언가를 <b>움직이는 것</b> 사이에는 큰 턱이 하나 있습니다. 모터는 전류를 수백 배 더 먹고, 멈출 때 전기를 되뿜고, 소프트웨어가 죽어도 <b>혼자 계속 돕니다</b>. 그래서 회로도 코드도 다르게 짜야 합니다.","body":[{"h":"무엇을 움직일지가 부품을 정한다","t":"<b>계속 돌아야 하면</b> DC 모터, <b>정해진 각도로 가야 하면</b> 서보, <b>정확히 몇 칸 움직여야 하면</b> 스텝모터입니다. 셋은 제어 방법도 완전히 달라요 — DC 는 전압을 조절하고, 서보는 <b>펄스 폭으로 각도를 지시</b>하고, 스텝모터는 코일을 순서대로 켜서 한 칸씩 밀어 냅니다."},{"h":"핀은 지시만 하고 전류는 따로 흐른다","t":"모터는 수백 mA 에서 수 A 를 먹으니 핀으로 직접 켤 수 없습니다. 앞에서 배운 트랜지스터 스위치를 쓰되, <b>방향까지 바꾸려면</b> 스위치 네 개를 다리처럼 엮은 <b>H 브리지</b>가 필요해요. 요즘은 이걸 칩 하나로 만든 <b>모터 드라이버</b>를 씁니다."},{"h":"소프트웨어가 멈춰도 모터는 안 멈춘다","t":"화면이 멈추면 사용자가 불편할 뿐이지만, <b>모터가 멈추지 않으면 무언가가 부러집니다</b>. 코드가 무한 루프에 빠져도 정지 신호가 가도록 <b>감시 장치와 물리적 한계 스위치</b>를 둬야 해요. 움직이는 것을 다룰 때는 '잘 도는 코드' 보다 '<b>안전하게 멈추는 코드</b>' 가 먼저입니다."}],"code":{"t":"세 가지 모터, 세 가지 신호","c":"DC 모터     PWM 듀티로 속도 · H 브리지로 방향\n            듀티 0~255 → 평균 전압 → 회전 속도\n\n서보        20ms 주기에 펄스 폭으로 각도를 지시 (PWM 듀티가 아니다)\n            1.0ms → 0°   1.5ms → 90°   2.0ms → 180°\n\n스텝모터     코일을 순서대로 켜 한 칸씩\n            1.8°/스텝 → 한 바퀴 200스텝\n\n전류은 언제나 별도 전원에서 → 드라이버 → 모터\n접지는 보드와 반드시 공유"},"key":["계속 돌리면 DC, 각도면 서보, 정확한 칸이면 스텝모터","서보는 듀티가 아니라 펄스 폭으로 각도를 지시한다","방향까지 바꾸려면 H 브리지가 필요하다","움직이는 것에는 멈추는 장치를 먼저 만든다"]}},{"t":"모터 제어 III","q":[{"t":"choice","k":"모터가 돌면 값이 튄다","cat":"debug","q":"모터를 켜자 <b>센서 값이 튀고 보드가 가끔 리셋</b>된다. 배선과 접지는 확인했다. 무엇을 더 해야 하는가?","code":"모터 켜짐 → 큰 전류가 갑자기 흐름 + 코일이 잡음을 만듦\n          → 전압 흔들림 + 신호선에 잡음 유입","o":["전원 쪽에는 <b>부하 가까이 커패시터</b>를 달아 순간 전류를 받아 주고, 모터 전원을 보드와 <b>분리</b>하며, 신호선을 모터 배선에서 떼어 놓거나 꼬아 준다","센서 읽기 주기를 늘리면 전기적 잡음도 함께 사라진다","모터와 센서를 같은 전원에 함께 물리면 두 쪽의 전위가 같아져 흔들림이 사라진다. 전원을 나누는 것이 오히려 접지 차이를 만들어 문제를 더 키우게 된다","소프트웨어 평균 필터만으로 충분히 해결되는 문제다"],"a":0,"ex":"앞서 배운 전원 문제가 모터에서는 훨씬 크게 나타난다.\n💡 개념: 모터는 큰 전류를 갑자기 끌어당기고 코일이 전기적 잡음을 뿜는다. 두 가지가 함께 와서 전압을 흔들고 신호선에 잡음을 얹는다. 그래서 <b>전원 쪽 대책과 배선 쪽 대책</b>이 둘 다 필요하다.\n🛠 실무: 소프트웨어 필터는 마지막 단계다 — 전기적으로 잡을 수 있는 것을 코드로 덮으면 원인이 남아 있어 언젠가 더 크게 터진다. 그리고 리셋이 의심되면 시작 함수에서 한 줄 찍어 확인하는 것이 가장 빠르다."},{"t":"choice","k":"지금 어디쯤인가","cat":"design","q":"DC 모터로 물체를 정확한 위치까지 옮겨야 한다. 위치를 알 방법이 없다면 어떤 문제가 생기고, 어떻게 해결하는가?","code":"지시: 3초 동안 돌려라\n실제: 부하·전압·마찰에 따라 이동 거리가 매번 다르다","o":["위치 제어는 DC 모터로는 불가능하므로 다른 방식이 없다","돌린 시간만으로는 <b>실제로 얼마나 갔는지 알 수 없다</b>","모터를 스텝모터로 바꾸면 센서 없이도 실제 위치를 항상 알 수 있다","전압을 정확히 유지하면 시간만으로 위치를 계산할 수 있다"],"a":1,"ex":"'열어 놓고 지시만 하는 것' 과 '결과를 보며 고치는 것' 의 차이.\n💡 개념: 되먹임이 없으면 부하가 조금만 달라져도 결과가 어긋나고, 어긋난 것을 알 방법도 없다. 엔코더는 회전을 세어 알려 주고, 리밋 스위치는 적어도 '끝에 닿았다' 는 확실한 기준점을 준다.\n🛠 실무: 스텝모터도 <b>완전한 해답은 아니다</b> — 힘에 부쳐 칸을 놓치면 코드가 세는 값과 실제가 어긋나고 그걸 감지하지 못한다. 정확도가 중요하면 어떤 모터든 기준점을 잡는 과정과 되먹임을 함께 둔다.\n✅ 왜 그 답인가: 회전을 세는 엔코더나 끝을 알리는 스위치를 달아 <b>실제 위치를 되먹임</b>받아야 한다"},{"t":"choice","k":"서보가 떨린다","cat":"debug","q":"서보를 특정 각도로 두었는데 <b>가만히 있지 않고 미세하게 떨린다</b>. 가장 먼저 의심할 것은?","code":"서보 정지 명령 → 계속 지지직 움직임","o":["서보가 수명을 다한 것이므로 교체해야 한다","각도 값을 정수로 주지 않아 생기는 계산 오차다","<b>전원이 모자라거나 흔들리는 것</b>이다","PWM 주파수가 너무 높아 생기는 현상이다"],"a":2,"ex":"떨림은 대개 <b>기계 문제가 아니라 전원 문제</b>다.\n💡 개념: 서보는 '지시된 각도' 와 '지금 각도' 를 계속 비교해 차이가 있으면 모터를 돌린다. 전압이 흔들리면 이 판단 자체가 흔들려 조금씩 오가게 된다. 보드의 5V 핀에서 서보 전원을 뽑아 쓰면 특히 자주 겪는다.\n🛠 실무: 전원을 분리해도 남는다면 <b>기계적으로 갈 수 없는 각도</b>를 지시하고 있는지 본다 — 끝까지 밀린 상태에서 계속 더 가라고 하면 힘을 쓰며 떨고 발열한다. 사용 범위를 안전한 각도 안으로 제한해 둔다.\n✅ 왜 그 답인가: 서보는 자세를 유지하려고 계속 힘을 쓰므로 전류를 꾸준히 먹고, 전압이 처지면 위치 판단이 흔들려 떨림이 된다. 별도 전원과 커패시터를 먼저 확인한다"},{"t":"choice","k":"여러 개를 함께 돌리면","cat":"design","q":"서보 여섯 개를 붙였더니 하나씩 움직일 때는 멀쩡한데 <b>동시에 움직이면</b> 보드가 리셋된다. 원인과 대응은?","code":"서보 1개 기동  0.5A\n서보 6개 동시   3A 이상\n전원 공급 한계  2A","o":["서보를 여러 개 한 보드에 붙이면 제어 신호끼리 서로 간섭하기 때문이다. 신호선을 서로 멀리 떼어 놓고 각각 다른 핀에 나눠 연결하면 리셋 없이 동시에 움직일 수 있다","서보는 원래 동시에 두 개까지만 제어할 수 있다","핀이 부족해 생기는 문제이며 확장 보드를 쓰면 해결된다","동시에 움직이는 순간 <b>전류가 더해져</b> 전원 한계를 넘기 때문이다 — 전원을 넉넉한 것으로 바꾸거나, 소프트웨어에서 <b>시간을 조금씩 어긋나게</b> 기동시켜 순간 최댓값을 낮춘다"],"a":3,"ex":"'하나씩은 되는데 같이 하면 안 된다' 는 거의 항상 전류 합계 문제다.\n💡 개념: 각 서보의 기동 전류는 겹칠 때 그대로 더해진다. 평균 소비가 아니라 <b>가장 나쁜 순간의 합</b>으로 전원을 정해야 한다.\n🛠 실무: 전원을 키우는 것이 정석이지만, 몇십 밀리초씩 어긋나게 출발시키는 것만으로도 최댓값이 크게 준다 — 사람 눈에는 동시에 움직이는 것으로 보인다. 그리고 <b>움직이지 않을 때 서보 신호를 끊어</b> 힘을 빼 두면 대기 전류와 발열이 함께 줄어든다."}],"th":{"sum":"LED 를 켜는 것과 무언가를 <b>움직이는 것</b> 사이에는 큰 턱이 하나 있습니다. 모터는 전류를 수백 배 더 먹고, 멈출 때 전기를 되뿜고, 소프트웨어가 죽어도 <b>혼자 계속 돕니다</b>. 그래서 회로도 코드도 다르게 짜야 합니다.","body":[{"h":"무엇을 움직일지가 부품을 정한다","t":"<b>계속 돌아야 하면</b> DC 모터, <b>정해진 각도로 가야 하면</b> 서보, <b>정확히 몇 칸 움직여야 하면</b> 스텝모터입니다. 셋은 제어 방법도 완전히 달라요 — DC 는 전압을 조절하고, 서보는 <b>펄스 폭으로 각도를 지시</b>하고, 스텝모터는 코일을 순서대로 켜서 한 칸씩 밀어 냅니다."},{"h":"핀은 지시만 하고 전류는 따로 흐른다","t":"모터는 수백 mA 에서 수 A 를 먹으니 핀으로 직접 켤 수 없습니다. 앞에서 배운 트랜지스터 스위치를 쓰되, <b>방향까지 바꾸려면</b> 스위치 네 개를 다리처럼 엮은 <b>H 브리지</b>가 필요해요. 요즘은 이걸 칩 하나로 만든 <b>모터 드라이버</b>를 씁니다."},{"h":"소프트웨어가 멈춰도 모터는 안 멈춘다","t":"화면이 멈추면 사용자가 불편할 뿐이지만, <b>모터가 멈추지 않으면 무언가가 부러집니다</b>. 코드가 무한 루프에 빠져도 정지 신호가 가도록 <b>감시 장치와 물리적 한계 스위치</b>를 둬야 해요. 움직이는 것을 다룰 때는 '잘 도는 코드' 보다 '<b>안전하게 멈추는 코드</b>' 가 먼저입니다."}],"code":{"t":"세 가지 모터, 세 가지 신호","c":"DC 모터     PWM 듀티로 속도 · H 브리지로 방향\n            듀티 0~255 → 평균 전압 → 회전 속도\n\n서보        20ms 주기에 펄스 폭으로 각도를 지시 (PWM 듀티가 아니다)\n            1.0ms → 0°   1.5ms → 90°   2.0ms → 180°\n\n스텝모터     코일을 순서대로 켜 한 칸씩\n            1.8°/스텝 → 한 바퀴 200스텝\n\n전류은 언제나 별도 전원에서 → 드라이버 → 모터\n접지는 보드와 반드시 공유"},"key":["계속 돌리면 DC, 각도면 서보, 정확한 칸이면 스텝모터","서보는 듀티가 아니라 펄스 폭으로 각도를 지시한다","방향까지 바꾸려면 H 브리지가 필요하다","움직이는 것에는 멈추는 장치를 먼저 만든다"]}},{"t":"모터 제어 IV","q":[{"t":"choice","k":"코드가 멈춰도 모터는 돈다","cat":"ops","q":"코드가 무한 루프에 빠지거나 멈춰도 <b>모터는 마지막 명령대로 계속 돈다</b>. 이 상황을 막는 표준적인 장치는?","code":"코드 멈춤 → 마지막 출력 유지 → 모터 계속 회전 → 무언가 부러짐","o":["정해진 시간마다 코드가 <b>살아 있다는 신호를 보내지 않으면 자동으로 보드를 재시작</b>하는 감시 장치를 켠다 — 재시작하면 핀이 초기화되어 모터가 멈춘다. 여기에 물리적인 한계 스위치를 더한다","모터 드라이버는 제어 신호가 끊기면 자동으로 정지하도록 만들어져 있으므로 따로 감시 장치를 둘 필요가 없다. 코드가 멈추면 제어 신호도 함께 멈추게 되므로 모터는 그 자리에서 저절로 서게 된다","예외 처리를 꼼꼼히 하면 코드가 멈추는 일은 생기지 않는다","루프 안에 지연을 충분히 넣으면 멈춤이 생기지 않는다"],"a":0,"ex":"화면이 멈추는 것과 기계가 멈추지 않는 것은 위험이 다르다.\n💡 개념: 감시 장치는 별도 타이머로 돌아가며, 정해진 시간 안에 신호를 못 받으면 보드를 재시작한다. 코드가 어떤 이유로 멈춰도 이 타이머는 계속 돌기 때문에 확실하게 동작한다.\n🛠 실무: 감시 시간을 정할 때 <b>정상 동작 중 가장 오래 걸리는 구간</b>보다 넉넉히 잡아야 한다 — 짧으면 멀쩡한데도 계속 재시작한다. 그리고 재시작 뒤 위치를 모르는 상태가 되므로, 시작할 때 기준점을 다시 잡는 과정도 함께 설계한다."},{"t":"choice","k":"여기까지만","cat":"design","q":"이동하는 부품이 <b>끝을 넘어가</b> 기구를 망가뜨리지 않게 하려면?","code":"소프트 리밋  코드에서 범위를 벗어난 명령을 거부\n하드 리밋    물리 스위치가 눌리면 즉시 정지","o":["코드에서 각도 범위만 제한하면 충분하다","코드에서 범위를 제한하는 것과 <b>물리 스위치로 막는 것을 함께</b> 둔다 — 코드가 잘못되거나 멈춰도 스위치는 동작하므로, 둘 중 하나만 두면 그 하나가 실패했을 때 막을 것이 없다","물리 스위치만 달아 두면 코드 쪽 제한은 따로 필요 없다. 스위치는 전기적으로 동작하므로 코드보다 확실하고, 두 곳에 같은 제한을 두면 서로 어긋났을 때 오히려 원인을 찾기 어려워진다","모터의 힘을 약하게 설정하면 부딪혀도 안전하다"],"a":1,"ex":"안전 장치는 <b>겹쳐서</b> 둔다 — 하나가 실패해도 다음이 받아야 한다.\n💡 개념: 코드 제한은 평소에 작동하고 디버깅도 쉽지만 코드가 멈추면 함께 멈춘다. 물리 스위치는 코드와 무관하게 동작하지만 부딪히고 나서야 반응한다. 그래서 코드가 먼저 막고, 못 막으면 스위치가 잡는 순서로 둔다.\n🛠 실무: 스위치는 보통 <b>눌리면 열리는</b> 방식으로 달아, 배선이 끊어져도 정지 상태가 되게 한다. 실패했을 때 안전한 쪽으로 기울여 두는 것이 원칙이다."},{"t":"choice","k":"얼마나 오래 돌릴 수 있나","cat":"perf","q":"모터와 드라이버가 <b>계속 돌리면 뜨거워져</b> 보호 기능이 걸린다. 설계에서 무엇을 정해야 하는가?","code":"연속 정격  계속 돌려도 되는 수준\n최대 정격  짧게만 허용","o":["보호 기능이 있으므로 발열은 신경 쓰지 않아도 된다","전압을 낮추면 발열이 사라지므로 시간 제한은 필요 없다","일하는 시간과 쉬는 시간의 비율을 정해야 한다","방열판만 충분히 붙이면 언제까지나 최대치로 쓸 수 있다"],"a":2,"ex":"'스펙에 적힌 최댓값' 은 대개 <b>잠깐만</b> 낼 수 있는 값이다.\n💡 개념: 발열은 쌓인다. 짧게 쓰면 식을 시간이 있어 괜찮지만 계속 쓰면 온도가 올라가 보호가 걸리거나 부품이 상한다. 그래서 데이터시트에는 연속으로 쓸 수 있는 값과 짧게만 쓸 수 있는 값이 따로 적혀 있다.\n🛠 실무: 앞서 CPU 에서 본 것과 같은 이야기다 — <b>순간 성능과 지속 성능이 다르다</b>. 계속 힘을 줘야 하는 자리라면 모터 대신 기계적으로 잡아 주는 구조(기어의 자기 잠금 등)를 쓰는 편이 낫다.\n✅ 왜 그 답인가: 부품마다 <b>계속 돌려도 되는 수준</b>과 <b>짧게만 허용되는 수준</b>이 다르므로, 최대치를 쓰려면 쉬는 시간을 함께 설계한다"},{"t":"choice","k":"멈추는 코드를 먼저","cat":"review","q":"움직이는 것을 다루는 프로젝트에서 <b>가장 먼저</b> 만들어야 할 코드는?","code":"① 모터를 원하는 대로 움직이는 코드\n② 어떤 상황에서든 안전하게 멈추는 코드","o":["움직이는 코드를 먼저 만들어야 무엇을 멈춰야 할지 알 수 있다","둘은 순서와 무관하며 편한 쪽부터 하면 된다","정지는 전원을 뽑으면 되므로 코드로 만들 필요가 없다","<b>멈추는 코드</b>다"],"a":3,"ex":"소프트웨어만 다루다 하드웨어로 넘어올 때 가장 크게 바뀌는 습관.\n💡 개념: 화면 버그는 새로고침하면 끝이지만, 모터가 잘못 돌면 기구가 부러지고 사람이 다칠 수도 있다. 되돌릴 수 없는 결과가 있는 시스템에서는 <b>실패했을 때 안전한 상태로 가는 경로</b>를 먼저 만든다.\n🛠 실무: 구체적으로는 — 시작하면 모든 출력을 꺼진 상태로 두고, 정지 함수를 하나 만들어 어디서든 부를 수 있게 하고, 감시 장치를 켜고, 한계 스위치를 인터럽트로 받는다. 여기까지 되면 그다음부터는 마음 놓고 실험할 수 있다.\n✅ 왜 그 답인가: 정지 명령, 시작할 때의 정지 상태, 감시 장치, 한계 스위치 처리를 먼저 만들어 두고 그 위에 동작을 얹는다. 움직이는 것은 실수가 곧 물리적 손상이기 때문이다"}],"th":{"sum":"LED 를 켜는 것과 무언가를 <b>움직이는 것</b> 사이에는 큰 턱이 하나 있습니다. 모터는 전류를 수백 배 더 먹고, 멈출 때 전기를 되뿜고, 소프트웨어가 죽어도 <b>혼자 계속 돕니다</b>. 그래서 회로도 코드도 다르게 짜야 합니다.","body":[{"h":"무엇을 움직일지가 부품을 정한다","t":"<b>계속 돌아야 하면</b> DC 모터, <b>정해진 각도로 가야 하면</b> 서보, <b>정확히 몇 칸 움직여야 하면</b> 스텝모터입니다. 셋은 제어 방법도 완전히 달라요 — DC 는 전압을 조절하고, 서보는 <b>펄스 폭으로 각도를 지시</b>하고, 스텝모터는 코일을 순서대로 켜서 한 칸씩 밀어 냅니다."},{"h":"핀은 지시만 하고 전류는 따로 흐른다","t":"모터는 수백 mA 에서 수 A 를 먹으니 핀으로 직접 켤 수 없습니다. 앞에서 배운 트랜지스터 스위치를 쓰되, <b>방향까지 바꾸려면</b> 스위치 네 개를 다리처럼 엮은 <b>H 브리지</b>가 필요해요. 요즘은 이걸 칩 하나로 만든 <b>모터 드라이버</b>를 씁니다."},{"h":"소프트웨어가 멈춰도 모터는 안 멈춘다","t":"화면이 멈추면 사용자가 불편할 뿐이지만, <b>모터가 멈추지 않으면 무언가가 부러집니다</b>. 코드가 무한 루프에 빠져도 정지 신호가 가도록 <b>감시 장치와 물리적 한계 스위치</b>를 둬야 해요. 움직이는 것을 다룰 때는 '잘 도는 코드' 보다 '<b>안전하게 멈추는 코드</b>' 가 먼저입니다."}],"code":{"t":"세 가지 모터, 세 가지 신호","c":"DC 모터     PWM 듀티로 속도 · H 브리지로 방향\n            듀티 0~255 → 평균 전압 → 회전 속도\n\n서보        20ms 주기에 펄스 폭으로 각도를 지시 (PWM 듀티가 아니다)\n            1.0ms → 0°   1.5ms → 90°   2.0ms → 180°\n\n스텝모터     코일을 순서대로 켜 한 칸씩\n            1.8°/스텝 → 한 바퀴 200스텝\n\n전류은 언제나 별도 전원에서 → 드라이버 → 모터\n접지는 보드와 반드시 공유"},"key":["계속 돌리면 DC, 각도면 서보, 정확한 칸이면 스텝모터","서보는 듀티가 아니라 펄스 폭으로 각도를 지시한다","방향까지 바꾸려면 H 브리지가 필요하다","움직이는 것에는 멈추는 장치를 먼저 만든다"]}}],"ord":7},{"t":"멈췄을 때, 다시 켰을 때 — 리셋·워치독·설정 보존","g":"🔄","l":[{"t":"멈춤과 되살아남 I","q":[{"t":"choice","k":"전압이 내려앉으면","cat":"debug","q":"모터가 돌기 시작하는 순간 보드가 재시작된다. 코드는 그대로인데 왜 이런 일이 생기는가?","code":"관찰\n  모터 정지 중      전원 전압 5.0V   정상 동작\n  모터 기동 순간    전원 전압 3.9V   보드 재시작\n  모터 정속 회전    전원 전압 4.8V   정상 동작","o":["<b>기동 순간 큰 전류가 흘러 전압이 내려앉았기</b> 때문이다","모터 제어 코드에 무한 루프가 있어 워치독이 리셋한 것이다","모터가 만드는 자기장이 프로그램 코드를 바꿔 버렸기 때문이다","전류가 늘어나면 CPU 클록이 빨라져 명령을 건너뛰기 때문이다"],"a":0,"ex":"가장 많은 전류가 흐르는 순간은 <b>회전 중이 아니라 기동 순간</b>이다 — 모터 단원에서 본 그대로다.\n💡 개념: 전압이 애매하게 낮으면 CPU 는 멈추는 것이 아니라 <b>틀리게 동작한다</b>. 그것이 더 위험해서, 아예 리셋해 버리는 보호 장치가 들어 있다.\n🛠 실무: 재시작 자체는 보호 장치가 제 일을 한 것이다. 고칠 것은 전원 쪽이다 — 모터 전원을 나누거나, 용량이 큰 커패시터를 가까이 두거나, 더 센 전원을 쓴다.\n✅ 왜 그 답인가: 전압이 일정 아래로 떨어지면 CPU 가 잘못 동작하므로 보호 장치가 스스로 리셋한다"},{"t":"choice","k":"메모리가 바닥나면","cat":"debug","q":"센서 값을 저장하는 배열을 늘렸더니 전혀 관계없는 변수가 이상한 값이 된다. 무엇이 일어난 것인가?","code":"SRAM 2048 바이트\n\n  전역 변수 ┃━━━━━━━┫                    ┣━━━━ 스택 (아래로 자란다)\n            힙 (위로 자란다) ━━━━▶\n\n배열을 늘리자 둘이 만났다","o":["배열 크기가 2의 거듭제곱이 아니어서 정렬이 어긋난 것이다","<b>서로 다른 용도의 메모리가 겹쳐 덮어쓰기가 일어난 것</b>이다","컴파일러가 큰 배열을 EEPROM 으로 옮기면서 주소가 밀린 것이다","배열이 커져 접근 속도가 느려지면서 값을 읽는 시점이 어긋난 것이다"],"a":1,"ex":"2048바이트는 <b>정수 배열 1024개</b>면 끝이다. 다른 변수 없이도 그렇다.\n💡 개념: PC 라면 메모리 부족을 알려 주지만 여기서는 아무 신호가 없다. 값이 조용히 바뀌고, 한참 뒤 엉뚱한 곳에서 증상이 나타난다.\n🛠 실무: 컴파일 결과에 나오는 <b>남은 SRAM 표시</b>를 항상 본다. 문자열을 플래시에 두는 방법도 흔한 대책이다 — 경고 문구 스무 줄이면 600바이트, SRAM 의 3할 가까이를 차지한다.\n✅ 왜 그 답인가: 오류 메시지 없이 값만 조용히 망가진다"},{"t":"choice","k":"부팅 중에 죽으면","cat":"debug","q":"장치가 켜졌다 꺼졌다를 계속 반복한다. 가장 먼저 의심할 구조는?","code":"setup() {\n  센서 초기화;\n  네트워크 연결;      ← 여기서 실패하면?\n  설정 읽기;\n}\nloop() { ... }","o":["loop 함수가 너무 빨리 돌아 전원이 따라가지 못하는 것이다","시리얼 모니터가 연결될 때마다 리셋을 걸기 때문이다","<b>초기화 도중 죽고 다시 켜지기를 반복하는 것</b>이다","부트로더가 손상되어 프로그램을 매번 다시 쓰는 것이다"],"a":2,"ex":"리셋은 문제를 <b>없애는 것이 아니라 처음으로 되돌리는 것</b>이다. 문제가 처음에 있으면 소용이 없다.\n💡 개념: 그래서 되살아나기 위한 장치가 오히려 영원한 재부팅을 만들기도 한다. 뒤에서 볼 워치독도 같은 위험을 갖고 있다.\n🛠 실무: 초기화에서 실패할 수 있는 일은 <b>실패해도 넘어가게</b> 만든다. 네트워크가 없어도 센서는 읽고 기록은 남기도록 두면, 적어도 무엇이 문제인지 알 수 있는 상태로 살아 있다.\n✅ 왜 그 답인가: 리셋해도 같은 자리에서 같은 이유로 죽으므로 스스로는 빠져나오지 못한다"},{"t":"choice","k":"왜 리셋됐는지","cat":"ops","q":"현장에 설치한 장치가 가끔 재시작된다. 원인을 좁히기 위해 가장 먼저 갖춰야 할 것은?","code":"재시작의 원인이 될 수 있는 것\n  전원 재투입 · 리셋 핀 · 전압 강하 보호 · 워치독 · 사람이 뽑았다 꽂음\n\n지금은 다시 켜졌다는 사실만 안다","o":["시리얼 모니터를 계속 연결해 두고 사람이 지켜보는 것이다","전원 공급기를 더 큰 것으로 바꿔 보는 것이다","재시작 횟수를 세어 몇 번인지 확인하는 것이다","<b>어떤 이유로 리셋됐는지를 읽어 기록으로 남기는 것</b>이다"],"a":3,"ex":"'전압이 떨어져서' 와 '워치독이 걸려서' 는 <b>고치는 방법이 전혀 다르다</b>.\n💡 개념: 앞의 것은 전원 문제이고 뒤의 것은 코드가 멈춘 것이다. 둘을 구분하지 못하면 엉뚱한 곳을 계속 고치게 된다.\n🛠 실무: 켜질 때 원인을 읽어 EEPROM 에 남기거나 시리얼로 뿌려 둔다. 원인을 읽은 뒤에는 <b>지워 주어야</b> 다음 리셋 때 새 값이 제대로 남는다.\n✅ 왜 그 답인가: 칩이 그 정보를 갖고 있으므로 켜질 때 읽어 두면 원인이 크게 좁혀진다"}],"th":{"sum":"책상 위에서는 문제가 없습니다. 문제는 <b>아무도 안 보는 곳에서 몇 달씩 도는 장치</b>에서 생겨요. 언젠가 멈추고, 언젠가 전원이 나갑니다. 그때 <b>스스로 되살아나는지</b>, 그리고 <b>무엇이 남아 있는지</b>가 이 단원의 주제입니다.","body":[{"h":"멈추는 이유는 코드 밖에도 있다","t":"무한 루프에 빠지는 것만이 아닙니다. <b>전압이 잠깐 내려앉으면</b> CPU 가 엉뚱하게 동작하고, <b>메모리가 바닥나면</b> 변수들이 서로를 덮어씁니다. 우노의 SRAM 은 <b>2048바이트</b>뿐이에요 — 문자열 몇 개면 금방 위태로워집니다."},{"h":"감시견은 스스로 짖는다","t":"워치독은 '<b>정해진 시간 안에 신호를 안 주면 리셋한다</b>' 는 타이머입니다. 프로그램이 멈추면 신호가 끊기고, 장치가 알아서 다시 시작해요. 사람이 가서 전원을 뽑았다 꽂을 필요가 없습니다. 다만 <b>어디서 신호를 줄지</b>가 설계의 전부입니다."},{"h":"전원이 나가면 SRAM 은 비워진다","t":"변수에 담아 둔 값은 <b>전원과 함께 사라집니다</b>. 남기려면 EEPROM 에 써야 하는데, 우노는 <b>1024바이트</b>뿐이고 <b>한 자리에 약 10만 번</b>밖에 못 씁니다. 매 루프마다 쓰면 <b>2분도 안 되어</b> 그 자리가 망가져요."},{"h":"다시 켜질 때가 가장 위험하다","t":"저장해 둔 값이 <b>반쯤 쓰이다 만 상태</b>일 수 있고, 처음 켜는 장치라면 아예 비어 있습니다. 그 값을 그대로 믿고 모터를 돌리면 사고가 나요. 그래서 <b>온전한지 확인하고, 아니면 안전한 기본값으로</b> 시작하는 것이 기본입니다."}],"code":{"t":"무엇이 남고 무엇이 사라지나","c":"아두이노 우노 (ATmega328P)\n\n  플래시   32768 바이트   프로그램이 들어간다\n                          전원이 나가도 남는다 · 약 1만 번 쓸 수 있다\n\n  SRAM      2048 바이트   변수가 산다\n                          전원이 나가면 사라진다 · 쓰기 제한 없음\n\n  EEPROM    1024 바이트   설정을 남긴다\n                          전원이 나가도 남는다 · 약 10만 번 쓸 수 있다\n\nEEPROM 한 자리의 수명\n  루프마다 쓰면 (1000회/초)     1.7분\n  1초마다 쓰면                  1.2일\n  1분마다 쓰면                  69일\n  10분마다 쓰면                 694일"},"key":["전압 강하와 메모리 고갈은 코드가 멀쩡해도 장치를 멈춘다","워치독은 멈춘 장치를 스스로 되살린다","SRAM 은 전원과 함께 비워지고 EEPROM 만 남는다","EEPROM 은 쓰기 횟수에 한계가 있다","다시 켤 때는 저장값을 검사하고 안전한 기본값을 준비한다"]}},{"t":"멈춤과 되살아남 II","q":[{"t":"choice","k":"감시견의 동작","cat":"knowledge","q":"워치독 타이머의 동작을 가장 정확히 설명한 것은?","code":"워치독 설정: 2초\n\n  프로그램이 2초 안에 '나 살아 있다' 신호를 보낸다  →  타이머가 처음으로\n  2초 동안 신호가 없다                            →  장치를 리셋한다","o":["<b>정해진 시간 안에 신호가 오지 않으면 장치를 리셋하는 별도의 타이머</b>다","코드에 무한 루프가 있는지 컴파일할 때 검사하는 기능이다","프로그램이 오류를 낼 때마다 자동으로 그 함수를 다시 실행하는 장치다","메모리 사용량을 감시하다가 한계를 넘으면 경고를 내는 장치다"],"a":0,"ex":"핵심은 <b>프로그램과 따로 돈다</b>는 점이다. 프로그램이 멈춰도 함께 멈추지 않는다.\n💡 개념: 그래서 감시가 성립한다. 프로그램 안에서 '내가 멈췄는지' 를 확인하려는 시도는 멈추면 그 확인도 함께 멈추므로 소용이 없다.\n🛠 실무: 시간은 대개 몇십 밀리초에서 8초 사이에서 고른다. 짧게 잡으면 정상 동작 중에도 잘못 걸리고, 길게 잡으면 멈춘 채로 오래 방치된다.\n✅ 왜 그 답인가: 프로그램이 멈춰도 이 타이머는 따로 돌기 때문에 동작한다"},{"t":"choice","k":"어디서 신호를 줄까","cat":"design","q":"메인 루프 맨 앞에서 워치독 신호를 주도록 했다. 어떤 문제가 남는가?","code":"loop() {\n  워치독_신호();          ← 여기\n  센서_읽기();\n  판단하기();\n  모터_제어();\n}\n\n센서 읽기가 응답 없는 센서를 기다리며 멈춘다면?","o":["루프 맨 앞은 신호를 주기에 너무 이른 위치라 감시견의 타이밍이 어긋난다 — 루프의 맨 끝으로 옮겨 주면 주기가 정확히 맞아떨어져 문제가 사라진다","루프가 도는 한 신호는 계속 나가므로, <b>루프 안의 어느 단계가 잘못돼도 감시견은 만족한다</b> — 진짜 멈춘 것만 잡고 잘못 도는 것은 못 잡는다","신호를 한 번만 주면 워치독이 영구히 비활성화된다","문제 없다 — 루프 어디서 주든 효과는 같다"],"a":1,"ex":"워치독이 확인하는 것은 '<b>루프가 도는가</b>' 이지 '<b>일을 제대로 하는가</b>' 가 아니다.\n💡 개념: 센서 읽기 안에서 멈추면 루프도 멈추므로 그건 잡힌다. 문제는 센서가 계속 엉뚱한 값을 주는데 루프는 잘 도는 경우다.\n🛠 실무: 그래서 신호를 주기 전에 조건을 건다 — '최근 5초 안에 센서 값이 갱신됐고, 통신이 살아 있으면' 신호를 준다. 감시견에게 <b>무엇을 확인할지 알려 주는</b> 셈이다."},{"t":"choice","k":"감춰지는 문제","cat":"review","q":"워치독을 켠 뒤로 장치가 멈추는 일이 없어졌다. 이것을 어떻게 받아들여야 하는가?","code":"켜기 전   일주일에 한 번 멈춰서 사람이 가서 전원을 뽑았다 꽂았다\n\n켠 뒤     멈추는 일이 없다\n          (실제로는 일주일에 한 번 조용히 재시작하고 있다)","o":["워치독이 코드의 버그를 자동으로 고쳐 준 것이다","재시작이 일어나지 않게 되었으므로 기록도 필요 없다","<b>증상이 가려졌을 뿐 원인은 그대로</b>다","원인이 해결된 것이므로 더 볼 것이 없다"],"a":2,"ex":"워치독은 <b>회복 수단이지 진단 수단이 아니다</b>.\n💡 개념: 사람이 가는 수고는 없어졌으니 분명 이득이다. 다만 '문제가 없다' 와 '문제가 안 보인다' 를 구분하지 않으면, 재시작이 하루 한 번으로 늘어도 모르게 된다.\n🛠 실무: 워치독으로 재시작한 횟수를 세어 EEPROM 에 남기고, 가끔 들여다본다. 숫자가 늘고 있으면 <b>무언가 나빠지고 있다는 신호</b>다.\n✅ 왜 그 답인가: 장애 시간은 줄었지만, 원인을 찾을 기회도 함께 사라졌으므로 재시작 횟수를 기록해야 한다"},{"t":"choice","k":"감시견 때문에 무한 재부팅","cat":"debug","q":"워치독을 켠 뒤 장치가 끝없이 재시작한다. 어떤 구조에서 이런 일이 생기는가?","code":"setup() {\n  워치독_켜기(2초);\n  긴_초기화();        ← 3초 걸린다\n}\nloop() { 워치독_신호(); ... }","o":["리셋될 때마다 워치독 시간이 절반으로 줄어들기 때문이다","워치독을 setup 에서 켜 버리면 loop 안에서는 신호를 줄 수 없게 되기 때문이다 — loop 가 시작된 뒤에 켜야 정상 동작한다","워치독은 한 번 켜면 끌 수 없어 계속 리셋을 거는 것이다","<b>초기화가 워치독 시간보다 오래 걸려 loop 에 닿기 전에 리셋되는 것</b>이다 — 리셋 뒤에도 같은 자리에서 같은 일이 반복된다"],"a":3,"ex":"앞에서 본 부팅 중 실패와 <b>같은 모양</b>이다 — 되살리는 장치가 되살아날 기회를 없앤다.\n💡 개념: 워치독을 언제 켜느냐가 중요하다. 오래 걸리는 초기화가 있다면 그것이 끝난 뒤에 켜거나, 초기화 중에도 중간중간 신호를 주어야 한다.\n🛠 실무: 이 상태가 되면 새 프로그램을 올릴 시간조차 없어 곤란해진다. 그래서 워치독 코드를 넣을 때는 <b>되돌릴 방법을 먼저</b> 확인해 둔다."}],"th":{"sum":"책상 위에서는 문제가 없습니다. 문제는 <b>아무도 안 보는 곳에서 몇 달씩 도는 장치</b>에서 생겨요. 언젠가 멈추고, 언젠가 전원이 나갑니다. 그때 <b>스스로 되살아나는지</b>, 그리고 <b>무엇이 남아 있는지</b>가 이 단원의 주제입니다.","body":[{"h":"멈추는 이유는 코드 밖에도 있다","t":"무한 루프에 빠지는 것만이 아닙니다. <b>전압이 잠깐 내려앉으면</b> CPU 가 엉뚱하게 동작하고, <b>메모리가 바닥나면</b> 변수들이 서로를 덮어씁니다. 우노의 SRAM 은 <b>2048바이트</b>뿐이에요 — 문자열 몇 개면 금방 위태로워집니다."},{"h":"감시견은 스스로 짖는다","t":"워치독은 '<b>정해진 시간 안에 신호를 안 주면 리셋한다</b>' 는 타이머입니다. 프로그램이 멈추면 신호가 끊기고, 장치가 알아서 다시 시작해요. 사람이 가서 전원을 뽑았다 꽂을 필요가 없습니다. 다만 <b>어디서 신호를 줄지</b>가 설계의 전부입니다."},{"h":"전원이 나가면 SRAM 은 비워진다","t":"변수에 담아 둔 값은 <b>전원과 함께 사라집니다</b>. 남기려면 EEPROM 에 써야 하는데, 우노는 <b>1024바이트</b>뿐이고 <b>한 자리에 약 10만 번</b>밖에 못 씁니다. 매 루프마다 쓰면 <b>2분도 안 되어</b> 그 자리가 망가져요."},{"h":"다시 켜질 때가 가장 위험하다","t":"저장해 둔 값이 <b>반쯤 쓰이다 만 상태</b>일 수 있고, 처음 켜는 장치라면 아예 비어 있습니다. 그 값을 그대로 믿고 모터를 돌리면 사고가 나요. 그래서 <b>온전한지 확인하고, 아니면 안전한 기본값으로</b> 시작하는 것이 기본입니다."}],"code":{"t":"무엇이 남고 무엇이 사라지나","c":"아두이노 우노 (ATmega328P)\n\n  플래시   32768 바이트   프로그램이 들어간다\n                          전원이 나가도 남는다 · 약 1만 번 쓸 수 있다\n\n  SRAM      2048 바이트   변수가 산다\n                          전원이 나가면 사라진다 · 쓰기 제한 없음\n\n  EEPROM    1024 바이트   설정을 남긴다\n                          전원이 나가도 남는다 · 약 10만 번 쓸 수 있다\n\nEEPROM 한 자리의 수명\n  루프마다 쓰면 (1000회/초)     1.7분\n  1초마다 쓰면                  1.2일\n  1분마다 쓰면                  69일\n  10분마다 쓰면                 694일"},"key":["전압 강하와 메모리 고갈은 코드가 멀쩡해도 장치를 멈춘다","워치독은 멈춘 장치를 스스로 되살린다","SRAM 은 전원과 함께 비워지고 EEPROM 만 남는다","EEPROM 은 쓰기 횟수에 한계가 있다","다시 켤 때는 저장값을 검사하고 안전한 기본값을 준비한다"]}},{"t":"멈춤과 되살아남 III","q":[{"t":"choice","k":"세 가지 기억","cat":"knowledge","q":"아두이노 우노의 세 가지 메모리를 용도에 맞게 짝지은 것은?","code":"플래시   32768 바이트\nSRAM      2048 바이트\nEEPROM    1024 바이트","o":["프로그램은 <b>플래시</b>, 실행 중 변수는 <b>SRAM</b>, 전원이 나가도 남겨야 할 설정은 <b>EEPROM</b> 에 둔다","프로그램은 EEPROM, 변수는 플래시, 설정은 SRAM 에 둔다","셋 다 같은 용도이며 크기만 다르므로 아무 데나 두면 된다","프로그램과 실행 중 변수를 모두 SRAM 에 두고, 플래시는 백업 용도로만 따로 쓰며 EEPROM 은 쓰지 않는다"],"a":0,"ex":"구분하는 기준은 두 가지다 — <b>전원이 나가도 남는가</b>, 그리고 <b>얼마나 자주 쓸 수 있는가</b>.\n💡 개념: SRAM 만 휘발성이지만 쓰기 제한이 없다. 나머지 둘은 남지만 쓸 수 있는 횟수가 정해져 있다.\n🛠 실무: 크기 차이도 크다. EEPROM 1024바이트는 설정 몇십 개 분량이지 기록을 쌓아 둘 자리가 아니다. 데이터를 계속 모아야 한다면 SD 카드 같은 별도 저장 장치가 필요하다."},{"t":"choice","k":"쓸 수 있는 횟수","cat":"perf","q":"센서 값을 매 루프마다 EEPROM 에 저장하는 코드를 발견했다. 아래 계산이 뜻하는 것은?","code":"EEPROM 한 자리는 약 10만 번 쓸 수 있다\n\n  루프마다 쓰면 (1000회/초)     1.7분\n  1초마다 쓰면                  1.2일\n  1분마다 쓰면                  69일\n  10분마다 쓰면                 694일","o":["10만 번을 넘으면 쓰기가 느려질 뿐 값은 정상적으로 남는다","그 자리가 <b>2분도 안 되어 못 쓰게 된다</b>","루프 속도가 느려져 프로그램 전체가 지연된다는 뜻이다","EEPROM 이 가득 차서 더 이상 쓸 공간이 없어진다는 뜻이다"],"a":1,"ex":"다 쓰고 나면 그 자리는 <b>쓴 값이 남지 않게</b> 된다. 되돌릴 방법이 없다.\n💡 개념: 이 한계는 자리마다 따로 세어진다. 같은 주소에 계속 쓰는 것이 문제이고, 여러 자리에 나눠 쓰면 그만큼 오래 버틴다.\n🛠 실무: 첫 대책은 간단하다 — <b>값이 실제로 달라졌을 때만 쓴다</b>. 대부분의 설정은 거의 안 바뀌므로 이것만으로 쓰기 횟수가 몇 자릿수씩 줄어든다.\n✅ 왜 그 답인가: 쓰기 주기를 늘리거나 값이 바뀔 때만 쓰도록 고쳐야 한다"},{"t":"choice","k":"나눠 쓰기","cat":"design","q":"1초마다 남겨야 하는 값이 있다. EEPROM 수명을 늘리는 방법으로 적절한 것은?","code":"한 자리에만 쓰면        1.2일\n\n  100자리를 돌아가며 쓰면?\n  각 자리에 순번을 함께 적어 두면 어느 것이 최신인지 알 수 있다","o":["값을 압축해서 저장하면 쓰기 횟수가 줄어든다","EEPROM 대신 SRAM 에 쓰면 전원이 나가도 남으면서 수명 제한도 없다","<b>여러 자리를 돌아가며 쓰고 순번으로 최신 값을 찾는 것</b>이다","쓰기 전에 항상 지우기를 먼저 하면 수명이 회복된다"],"a":2,"ex":"쓰기 횟수 자체는 그대로인데 <b>한 자리가 감당하는 몫이 줄어든다</b>.\n💡 개념: 이것을 마모 분산이라고 하고, SSD 안에서도 같은 일이 훨씬 정교하게 일어난다. 발상은 같다 — 닳는 것을 한곳에 몰지 않는다.\n🛠 실무: 최신 값을 찾으려면 순번이나 시각을 함께 적어야 한다. 그리고 순번이 한 바퀴 돌 때 어떻게 되는지도 정해 두어야 한다 — 안 그러면 <b>가장 오래된 값을 최신으로 착각</b>하게 된다.\n✅ 왜 그 답인가: 100자리를 쓰면 한 자리당 쓰기가 100분의 1로 줄어 그만큼 오래 버틴다"},{"t":"choice","k":"쓰는 도중 전원이 나가면","cat":"internals","q":"설정 여러 바이트를 EEPROM 에 쓰는 중에 전원이 나갔다. 다시 켜면 어떤 상태인가?","code":"설정 구조   [모드][속도 상위][속도 하위][한계값]\n\n쓰는 중 전원이 나가면\n            [새 모드][새 상위][옛 하위][옛 한계값]\n              ↑ 여기까지 썼다","o":["쓰기가 실패했으므로 전부 옛 값 그대로 남는다","EEPROM 이 손상되어 읽기 자체가 실패한다","다시 켜질 때 EEPROM 이 자동으로 마지막 온전한 값으로 되돌려 준다 — 쓰기가 끝까지 끝나지 않으면 아예 반영되지 않도록 되어 있기 때문이다","<b>일부만 새 값이고 나머지는 옛 값인, 어느 쪽도 아닌 상태</b>가 된다 — 형식은 멀쩡해 보이므로 그대로 읽으면 엉뚱한 설정으로 동작한다"],"a":3,"ex":"가장 나쁜 결과는 오류가 아니라 <b>그럴듯해 보이는 틀린 값</b>이다.\n💡 개념: 속도의 상위 바이트만 새것이면 값이 엉뚱하게 커지거나 작아진다. 읽는 쪽에서는 그것이 정상 범위 안이면 알아챌 방법이 없다.\n🛠 실무: 그래서 값들과 함께 <b>검사 합계를 적어 둔다</b>. 읽을 때 다시 계산해 맞지 않으면 저장값을 버리고 기본값으로 시작한다 — 다음 문제의 주제다."}],"th":{"sum":"책상 위에서는 문제가 없습니다. 문제는 <b>아무도 안 보는 곳에서 몇 달씩 도는 장치</b>에서 생겨요. 언젠가 멈추고, 언젠가 전원이 나갑니다. 그때 <b>스스로 되살아나는지</b>, 그리고 <b>무엇이 남아 있는지</b>가 이 단원의 주제입니다.","body":[{"h":"멈추는 이유는 코드 밖에도 있다","t":"무한 루프에 빠지는 것만이 아닙니다. <b>전압이 잠깐 내려앉으면</b> CPU 가 엉뚱하게 동작하고, <b>메모리가 바닥나면</b> 변수들이 서로를 덮어씁니다. 우노의 SRAM 은 <b>2048바이트</b>뿐이에요 — 문자열 몇 개면 금방 위태로워집니다."},{"h":"감시견은 스스로 짖는다","t":"워치독은 '<b>정해진 시간 안에 신호를 안 주면 리셋한다</b>' 는 타이머입니다. 프로그램이 멈추면 신호가 끊기고, 장치가 알아서 다시 시작해요. 사람이 가서 전원을 뽑았다 꽂을 필요가 없습니다. 다만 <b>어디서 신호를 줄지</b>가 설계의 전부입니다."},{"h":"전원이 나가면 SRAM 은 비워진다","t":"변수에 담아 둔 값은 <b>전원과 함께 사라집니다</b>. 남기려면 EEPROM 에 써야 하는데, 우노는 <b>1024바이트</b>뿐이고 <b>한 자리에 약 10만 번</b>밖에 못 씁니다. 매 루프마다 쓰면 <b>2분도 안 되어</b> 그 자리가 망가져요."},{"h":"다시 켜질 때가 가장 위험하다","t":"저장해 둔 값이 <b>반쯤 쓰이다 만 상태</b>일 수 있고, 처음 켜는 장치라면 아예 비어 있습니다. 그 값을 그대로 믿고 모터를 돌리면 사고가 나요. 그래서 <b>온전한지 확인하고, 아니면 안전한 기본값으로</b> 시작하는 것이 기본입니다."}],"code":{"t":"무엇이 남고 무엇이 사라지나","c":"아두이노 우노 (ATmega328P)\n\n  플래시   32768 바이트   프로그램이 들어간다\n                          전원이 나가도 남는다 · 약 1만 번 쓸 수 있다\n\n  SRAM      2048 바이트   변수가 산다\n                          전원이 나가면 사라진다 · 쓰기 제한 없음\n\n  EEPROM    1024 바이트   설정을 남긴다\n                          전원이 나가도 남는다 · 약 10만 번 쓸 수 있다\n\nEEPROM 한 자리의 수명\n  루프마다 쓰면 (1000회/초)     1.7분\n  1초마다 쓰면                  1.2일\n  1분마다 쓰면                  69일\n  10분마다 쓰면                 694일"},"key":["전압 강하와 메모리 고갈은 코드가 멀쩡해도 장치를 멈춘다","워치독은 멈춘 장치를 스스로 되살린다","SRAM 은 전원과 함께 비워지고 EEPROM 만 남는다","EEPROM 은 쓰기 횟수에 한계가 있다","다시 켤 때는 저장값을 검사하고 안전한 기본값을 준비한다"]}},{"t":"멈춤과 되살아남 IV","q":[{"t":"choice","k":"온전한지 확인하기","cat":"impl","q":"저장된 설정이 온전한지 확인하는 가장 실용적인 방법은?","code":"저장할 때   [설정 바이트들][그 바이트들로 계산한 검사값]\n\n읽을 때     저장된 바이트들로 검사값을 다시 계산한다\n            같으면 → 쓴다\n            다르면 → ?","o":["<b>검사값이 맞지 않으면 저장값을 버리고 안전한 기본값으로 시작</b>한다 — 깨진 설정으로 도는 것보다 초기 설정으로 도는 편이 낫다","검사값이 맞지 않더라도 저장된 값을 그대로 쓰되 로그에 경고만 남겨 둔다 — 기본값으로 되돌리면 사용자의 설정이 사라지기 때문이다","검사값이 맞지 않으면 장치를 정지시키고 사람을 기다린다","검사값 대신 저장한 날짜를 비교하면 더 정확하다"],"a":0,"ex":"검사값은 <b>깨졌다는 사실을 알려 줄 뿐</b> 고쳐 주지는 않는다. 그래서 대비책이 함께 있어야 한다.\n💡 개념: 두 번째 보기도 상황에 따라 맞다 — 사람이 곁에 있는 장비라면 멈추는 편이 안전할 수 있다. 무인 장치라면 기본값으로라도 도는 쪽이 낫다.\n🛠 실무: 처음 켜는 장치는 EEPROM 이 지워진 상태라 대개 전부 같은 값으로 차 있다. 그 상태도 검사값이 맞지 않으므로 <b>같은 경로로 자연스럽게 처리</b>된다."},{"t":"choice","k":"켜지는 순간의 출력","cat":"security","q":"전원이 들어오는 순간 모터가 마지막 상태로 돌아가게 만들었다. 어떤 위험이 있는가?","code":"저장   모터 속도 80% 로 돌던 중 정전\n\n복구   전원이 들어오자마자 80% 로 회전 시작\n       (사람이 정비하려고 뚜껑을 열어 둔 상태일 수도 있다)","o":["저장된 속도값이 낡아서 현재 부하에 맞지 않을 수 있다","<b>사람이 왜 전원이 나갔는지 모르는 상태에서 기계가 갑자기 움직인다</b> — 출력은 정지 상태로 시작하고 사람이 다시 시작시키게 하는 것이 안전하다","위험하지 않다 — 마지막 상태로 돌아가는 것이야말로 사용자가 기대하는 동작이며, 전원이 다시 복구되면 하던 일을 그대로 이어서 하는 것이 자연스럽다","모터가 기동 전류를 두 번 쓰게 되어 전원에 부담이 된다"],"a":1,"ex":"정전은 <b>사고가 났다는 신호일 수도</b> 있다. 그 상태에서 자동으로 되돌아가는 것은 위험하다.\n💡 개념: 그래서 '무엇을 복구할 것인가' 를 나눠 생각한다. 설정값은 복구해도 되고, <b>움직이는 것의 상태는 복구하지 않는</b> 것이 기본이다.\n🛠 실무: 자동 재시작이 꼭 필요한 무인 설비라면 조건을 붙인다 — 짧은 정전이었고, 안전 회로가 정상이고, 사람이 없다는 신호가 있을 때만. 그리고 재시작 전에 소리나 불빛으로 알린다."},{"t":"choice","k":"현장에서 추적하기","cat":"ops","q":"재시작이 한 달에 몇 번 일어난다. 책상에서는 재현되지 않을 때 가장 도움이 되는 것은?","code":"남길 수 있는 것\n  재시작 원인 · 재시작 횟수 · 마지막으로 지나간 단계 ·\n  그때의 전압 · 남은 SRAM · 켜져 있던 시간","o":["재현될 때까지 시리얼 모니터를 연결해 두고 기다리는 것이다","같은 장치를 하나 더 만들어 책상에서 오래 돌려 보는 것이다 — 시간을 충분히 오래 들이면 언젠가는 똑같은 증상이 그대로 재현된다","<b>다시 켜질 때마다 그 값들을 EEPROM 에 남겨 두는 것</b>이다 — 현장에 갈 수 없으니 장치가 스스로 흔적을 남겨야 한다","재시작이 드무므로 무시하고 다른 문제에 집중하는 것이다"],"a":2,"ex":"한 달에 몇 번이면 <b>지켜보는 방식으로는 사실상 잡히지 않는다</b>.\n💡 개념: 남길 값을 고르는 기준은 '이 값이 원인을 갈라 주는가' 다. 리셋 원인은 전원 문제와 코드 멈춤을 가르고, 남은 SRAM 은 메모리 고갈을 가른다.\n🛠 실무: 다만 EEPROM 은 1024바이트에 쓰기 횟수도 한정돼 있다. <b>재시작할 때만 쓰므로</b> 이 용도에는 잘 맞는다 — 한 달에 몇 번이면 수명 걱정이 없다."},{"t":"choice","k":"무엇을 남길 것인가","cat":"design","q":"새 장치를 설계하며 EEPROM에 무엇을 남길지 정한다. 판단 기준으로 가장 적절한 것은?","code":"후보\n  a) 사용자가 설정한 임계값\n  b) 장치 일련번호\n  c) 1초마다 갱신되는 센서 최근값\n  d) 재시작 횟수와 마지막 리셋 원인","o":["잃으면 안 되는 값은 무엇이든 전부 남긴다","크기가 작은 값부터 남기고 1024바이트가 찰 때까지 채운다","센서값처럼 자주 바뀌는 것일수록 우선 남겨야 복구가 정확하다","<b>드물게 바뀌면서 잃으면 곤란한 것만</b> 남긴다"],"a":3,"ex":"기준은 두 축이다 — <b>얼마나 자주 바뀌는가</b>, 그리고 <b>잃으면 곤란한가</b>.\n💡 개념: 자주 바뀌면서 잃어도 괜찮은 것(센서 최근값)은 SRAM 에 둔다. 드물게 바뀌면서 잃으면 곤란한 것만 EEPROM 으로 간다. 자주 바뀌면서 잃으면 곤란한 것이 있다면 <b>설계를 다시 봐야</b> 한다.\n🛠 실무: 센서값을 꼭 남겨야 한다면 EEPROM 이 아니라 SD 카드 같은 다른 저장 장치를 쓴다. 도구를 고르는 일이지 아껴 쓰기로 해결할 문제가 아니다.\n✅ 왜 그 답인가: 임계값·일련번호·재시작 기록이 여기 해당하고, 자주 갱신되는 센서값은 맞지 않는다"}],"th":{"sum":"책상 위에서는 문제가 없습니다. 문제는 <b>아무도 안 보는 곳에서 몇 달씩 도는 장치</b>에서 생겨요. 언젠가 멈추고, 언젠가 전원이 나갑니다. 그때 <b>스스로 되살아나는지</b>, 그리고 <b>무엇이 남아 있는지</b>가 이 단원의 주제입니다.","body":[{"h":"멈추는 이유는 코드 밖에도 있다","t":"무한 루프에 빠지는 것만이 아닙니다. <b>전압이 잠깐 내려앉으면</b> CPU 가 엉뚱하게 동작하고, <b>메모리가 바닥나면</b> 변수들이 서로를 덮어씁니다. 우노의 SRAM 은 <b>2048바이트</b>뿐이에요 — 문자열 몇 개면 금방 위태로워집니다."},{"h":"감시견은 스스로 짖는다","t":"워치독은 '<b>정해진 시간 안에 신호를 안 주면 리셋한다</b>' 는 타이머입니다. 프로그램이 멈추면 신호가 끊기고, 장치가 알아서 다시 시작해요. 사람이 가서 전원을 뽑았다 꽂을 필요가 없습니다. 다만 <b>어디서 신호를 줄지</b>가 설계의 전부입니다."},{"h":"전원이 나가면 SRAM 은 비워진다","t":"변수에 담아 둔 값은 <b>전원과 함께 사라집니다</b>. 남기려면 EEPROM 에 써야 하는데, 우노는 <b>1024바이트</b>뿐이고 <b>한 자리에 약 10만 번</b>밖에 못 씁니다. 매 루프마다 쓰면 <b>2분도 안 되어</b> 그 자리가 망가져요."},{"h":"다시 켜질 때가 가장 위험하다","t":"저장해 둔 값이 <b>반쯤 쓰이다 만 상태</b>일 수 있고, 처음 켜는 장치라면 아예 비어 있습니다. 그 값을 그대로 믿고 모터를 돌리면 사고가 나요. 그래서 <b>온전한지 확인하고, 아니면 안전한 기본값으로</b> 시작하는 것이 기본입니다."}],"code":{"t":"무엇이 남고 무엇이 사라지나","c":"아두이노 우노 (ATmega328P)\n\n  플래시   32768 바이트   프로그램이 들어간다\n                          전원이 나가도 남는다 · 약 1만 번 쓸 수 있다\n\n  SRAM      2048 바이트   변수가 산다\n                          전원이 나가면 사라진다 · 쓰기 제한 없음\n\n  EEPROM    1024 바이트   설정을 남긴다\n                          전원이 나가도 남는다 · 약 10만 번 쓸 수 있다\n\nEEPROM 한 자리의 수명\n  루프마다 쓰면 (1000회/초)     1.7분\n  1초마다 쓰면                  1.2일\n  1분마다 쓰면                  69일\n  10분마다 쓰면                 694일"},"key":["전압 강하와 메모리 고갈은 코드가 멀쩡해도 장치를 멈춘다","워치독은 멈춘 장치를 스스로 되살린다","SRAM 은 전원과 함께 비워지고 EEPROM 만 남는다","EEPROM 은 쓰기 횟수에 한계가 있다","다시 켤 때는 저장값을 검사하고 안전한 기본값을 준비한다"]}}],"ord":8},{"t":"끊기지 않는 통신 — 프레이밍·버퍼·체크섬","g":"📡","l":[{"t":"흐름에 경계 만들기 I","q":[{"t":"choice","k":"한 번에 온다는 보장","cat":"debug","q":"보낸 쪽이 <code>Serial.print(\"TEMP,23.5\\n\")</code> 를 한 번 호출했다. 받는 쪽에서 무엇을 가정할 수 있는가?","code":"if (Serial.available()) {\n  String s = Serial.readString();   /* 한 건이 다 왔다고 믿는다 */\n}","o":["아무것도 가정할 수 없다","한 번에 보냈으므로 한 번에 다 도착한다","줄바꿈이 있으므로 드라이버가 한 건 단위로 잘라 준다","9600bps 이하에서는 항상 한 번에 도착한다"],"a":0,"ex":"직렬 통신은 <b>바이트 흐름</b>이지 메시지 단위가 아니다.\n💡 개념: <code>Serial.available()</code> 이 알려 주는 것은 '지금 버퍼에 몇 바이트 있나' 뿐이다. 한 건이 다 왔는지는 우리가 <b>경계 규칙</b>으로 판단해야 한다.\n🛠 실무: 책상에서는 대개 한 번에 오기 때문에 이 코드가 잘 도는 것처럼 보인다. 현장에서 케이블이 길어지고 부하가 늘면 그때부터 간헐적으로 깨진다 — 재현이 어려운 대표적인 버그다.\n✅ 왜 그 답인가: 바이트 몇 개만 와 있을 수도 있고 다음 건이 붙어 있을 수도 있다"},{"t":"choice","k":"나뉘어 오는 경우","q":"<code>[\"A,1\\nB,\", \"2\\nC,3\"]</code> 두 덩어리로 도착했다. 줄바꿈으로 나누는 코드가 만들어 내는 결과는?","code":"// 남은 조각을 들고 있다가 다음 덩어리 앞에 이어 붙이는 방식","o":["프레임 세 개가 모두 완성된다","완성된 프레임 두 개(<code>A,1</code>, <code>B,2</code>)와 아직 안 끝난 조각 <code>C,3</code> 가 남는다","덩어리 경계에서 데이터가 깨져 버리기 때문에 결국 아무것도 만들어 내지 못한다","프레임 하나만 나오고 나머지는 버려진다"],"a":1,"ex":"실행해 확인한 결과다 — frames <code>['A,1','B,2']</code>, 남은 것 <code>'C,3'</code>.\n💡 개념: 핵심은 <b>남은 조각을 버리지 않고 들고 있는 것</b>이다. 이 한 줄이 빠지면 덩어리 경계에 걸친 프레임이 매번 사라진다.\n🛠 실무: 남은 조각 버퍼에는 반드시 상한을 둔다. 구분자가 영영 안 오면(상대가 죽었거나 형식이 틀렸으면) 무한히 자라 메모리를 다 먹는다."},{"t":"choice","k":"구분자가 데이터에 있으면","cat":"debug","q":"이름 필드에 줄바꿈이 섞인 데이터가 왔다. 줄바꿈 구분자 방식은 어떻게 되는가?","code":"입력: \"이름:김\\n철수\\n\"\n결과: ?","o":["파싱 오류가 나서 두 건 모두 버려진다","구분자가 데이터에 있으면 자동으로 무시된다","한 건이 <code>이름:김</code> 과 <code>철수</code> 두 건으로 쪼개진다","두 건으로 쪼개지지만 다음 프레임과 다시 합쳐져 복구된다"],"a":2,"ex":"실행해 확인했다 — <code>['이름:김', '철수']</code>.\n💡 개념: 구분자 방식은 <b>데이터에 구분자가 절대 없다는 약속</b> 위에 서 있다. 그 약속이 깨지면 조용히 잘못된 프레임이 만들어진다.\n🛠 실무: 텍스트 프로토콜을 쓴다면 보내는 쪽에서 구분자를 이스케이프하거나(<code>\\n</code> → <code>\\\\n</code>), 아예 길이 접두 방식으로 바꾼다. 사람이 읽기 좋은 것과 안전한 것 사이의 맞바꿈이다.\n✅ 왜 그 답인가: 뒤엣것은 형식에 안 맞는 쓰레기가 된다"},{"t":"choice","k":"길이를 앞에 붙이면","q":"<code>[3,10,20,30, 1,40, 2,50,60]</code> 이 도착했다. 길이 접두로 해석하면?","code":"형식: [길이][페이로드 ...]","o":["프레임 네 개 — 맨 앞의 길이 바이트도 하나의 프레임으로 세기 때문이다","프레임 하나 — 전체가 한 건이다","해석 불가 — 구분자가 없어 경계를 못 찾는다","프레임 세 개 — <code>[10,20,30]</code>, <code>[40]</code>, <code>[50,60]</code>"],"a":3,"ex":"실행해 확인했다.\n💡 개념: 길이 접두는 <b>데이터 안에 무엇이 들어 있든</b> 경계가 흔들리지 않는다. 이진 데이터를 그대로 보낼 수 있다는 것이 가장 큰 장점이다.\n🛠 실무: 길이 바이트의 최댓값이 곧 프레임 최대 크기다. 1바이트면 255, 그 이상이 필요하면 2바이트를 쓰고 <b>바이트 순서를 명시</b>해야 한다."}],"th":{"sum":"직렬 통신에는 '한 건' 이라는 경계가 없다. 경계를 만드는 것도, 흘러넘치는 버퍼를 관리하는 것도, 깨진 것을 알아채는 것도 전부 우리 몫이다.","body":[{"t":"UART 로 오는 것은 <b>바이트 흐름</b>뿐이다. 보낸 쪽이 한 번에 <code>ABC\\n</code> 를 썼어도 받는 쪽에서는 <code>AB</code> 와 <code>C\\n</code> 로 두 번에 나뉘어 도착할 수 있고, 반대로 두 건이 한 번에 붙어 올 수도 있다. 그래서 <b>경계를 정하는 규칙</b>이 필요하다."},{"t":"가장 흔한 두 가지는 <b>구분자</b>(줄바꿈 같은 특별한 바이트로 끊기)와 <b>길이 접두</b>(앞에 길이를 적고 그만큼 읽기)다. 구분자는 사람이 읽기 좋지만 데이터 안에 그 바이트가 들어가면 깨진다. 길이 접두는 그 문제가 없지만 길이가 깨지면 이후 전체가 어긋난다."},{"t":"보드의 수신 버퍼는 작다(우노 기준 64바이트). 루프가 다른 일을 하는 동안 그보다 많이 들어오면 <b>넘친 만큼 조용히 사라진다</b>. 오류도 안 나고 로그도 안 남는다. 그래서 루프 한 바퀴가 길어지는 것 자체가 통신 문제로 나타난다."},{"t":"깨진 것을 알아채려면 <b>체크섬</b>을 붙인다. 더하기나 XOR 은 만들기 쉽지만 바이트 순서가 바뀐 것이나 짝수 번 뒤집힌 비트를 놓친다. CRC 는 같은 1바이트로도 훨씬 잘 잡는다. 그래도 길이와 일련번호를 함께 확인하는 편이 안전하다."}],"code":{"c":"/* 길이 접두 프레임: [길이][페이로드...][체크섬] */\nwhile (Serial.available()) {\n  buf[n++] = Serial.read();\n  if (n >= 1 && n == buf[0] + 2) { handle(buf); n = 0; }\n}"},"key":["직렬 통신에는 경계가 없다 — 한 번에 보낸 것이 나뉘어 오고, 두 건이 붙어 온다","수신 버퍼가 넘치면 조용히 버려진다. 루프가 길어지는 것이 곧 통신 문제다","구분자 방식은 데이터에 그 바이트가 들어가면 깨진다","더하기·XOR 체크섬은 순서 바뀜을 못 잡는다"]}},{"t":"흐름에 경계 만들기 II","q":[{"t":"choice","k":"중간에서 끊기면","q":"위 스트림의 앞 7바이트만 도착했다. 어떻게 처리해야 하는가?","code":"받은 것: [3,10,20,30, 1,40, 2]\n마지막 2 는 '길이 2' 인데 페이로드가 아직 안 왔다","o":["완성된 두 프레임만 처리하고 <b>남은 1바이트는 들고 있다가</b> 다음에 온 것과 이어 붙인다","전체를 버리고 상대에게 재전송을 요청한다","길이만큼 0을 채워 프레임을 완성시킨다","남은 1바이트는 그냥 버리고 다음에 오는 덩어리부터 처음부터 새로 시작해서 읽어 나간다"],"a":0,"ex":"실행해 확인했다 — frames 2개, 남은 바이트 1개.\n💡 개념: 이 '남은 것 들고 있기' 가 프레이밍 코드의 절반이다. 버리면 그 프레임이 사라지고, 그다음 바이트부터는 길이 해석이 통째로 어긋난다.\n🛠 실무: 여기서도 상한이 필요하다. 길이가 200 인데 3바이트만 오고 상대가 죽으면 영원히 기다리게 되므로, <b>시한</b>을 두고 지나면 버퍼를 비우고 다시 동기를 맞춘다."},{"t":"choice","k":"버퍼가 넘치면","cat":"debug","q":"64바이트 수신 버퍼에 80바이트가 들어왔다. 무슨 일이 일어나는가?","code":"rx.push(50바이트);\nrx.push(30바이트);\n// 담긴 ? · 버려진 ?","o":["버퍼가 자동으로 늘어나 80바이트가 모두 담긴다","64바이트만 담기고 16바이트가 <b>조용히 사라진다</b>","오버플로 인터럽트가 걸려 프로그램이 멈춘다","오래된 것부터 밀려나 마지막 64바이트가 남는다"],"a":1,"ex":"재현해 확인했다 — 담긴 64, 버려진 16.\n💡 개념: 조용히 사라지는 것이 이 문제의 성질이다. 남은 것은 '가끔 데이터가 이상하다' 는 증상뿐이고, 그 자리에서는 원인이 안 보인다.\n🛠 실무: 넘친 횟수를 세어 주기적으로 내보내면 이 문제가 눈에 보이게 된다. 세는 코드 몇 줄이 현장 진단 시간을 크게 줄인다.\n✅ 왜 그 답인가: 오류도 로그도 없다"},{"t":"choice","k":"왜 넘치는가","cat":"debug","q":"9600bps 로 연속 수신하는데 가끔 데이터가 빠진다. 루프 안에 500ms 짜리 센서 읽기가 있다. 무엇을 계산해 봐야 하는가?","code":"9600bps · 8N1 → 한 바이트에 10비트 → 약 960바이트/초","o":["케이블 길이다 — 1m 를 넘어가면 9600bps 에서도 통신이 불안정해지기 때문이다","전원 용량이다 — 전류가 모자라면 UART 가 바이트를 잃는다","500ms 동안 들어올 양이다 — 약 480바이트로 64바이트 버퍼를 훨씬 넘는다","센서의 정확도다 — 읽기가 부정확하면 통신도 흔들린다"],"a":2,"ex":"960바이트/초 × 0.5초 = 480바이트, 버퍼는 64바이트다.\n💡 개념: 통신 문제로 보이지만 원인은 <b>루프가 오래 붙들려 있는 것</b>이다. 버퍼를 비워 줄 사람이 500ms 동안 없었다.\n🛠 실무: 대책은 두 가지다 — 무거운 일을 쪼개 루프를 짧게 유지하거나, 흐름 제어를 두어 상대가 기다리게 한다. 버퍼 크기를 키우는 것은 시간을 조금 벌 뿐이다."},{"t":"choice","k":"더하기 체크섬의 구멍","q":"페이로드 <code>[0x41,0x42,0x43,0x44]</code> 에서 앞 두 바이트의 <b>순서만</b> 바뀌었다. 더하기 체크섬과 XOR 체크섬은 이것을 잡는가?","code":"원본   41 42 43 44 → sum8 10 · xor8 4\n순서만 42 41 43 44 → sum8 ?  · xor8 ?","o":["둘 다 잡는다 — 두 방식 모두 계산에 그대로 위치별 가중치가 들어가기 때문이다","더하기는 못 잡지만 XOR 은 잡는다","XOR 은 못 잡지만 더하기는 잡는다","둘 다 못 잡는다 — 더하기도 XOR 도 순서와 무관하므로 값이 그대로다"],"a":3,"ex":"실행해 확인했다 — 순서를 바꿔도 sum8 은 10, xor8 은 4 로 그대로다.\n💡 개념: 더하기와 XOR 은 모두 <b>교환법칙이 성립</b>한다. 순서를 바꿔도 결과가 같다는 뜻이고, 그래서 순서 오류를 원리적으로 못 잡는다.\n🛠 실무: 같은 페이로드를 CRC-8 로 계산하면 98 과 229 로 갈린다. 계산 비용이 조금 늘 뿐이므로 새로 만든다면 CRC 를 쓰는 편이 낫다."}],"th":{"sum":"직렬 통신에는 '한 건' 이라는 경계가 없다. 경계를 만드는 것도, 흘러넘치는 버퍼를 관리하는 것도, 깨진 것을 알아채는 것도 전부 우리 몫이다.","body":[{"t":"UART 로 오는 것은 <b>바이트 흐름</b>뿐이다. 보낸 쪽이 한 번에 <code>ABC\\n</code> 를 썼어도 받는 쪽에서는 <code>AB</code> 와 <code>C\\n</code> 로 두 번에 나뉘어 도착할 수 있고, 반대로 두 건이 한 번에 붙어 올 수도 있다. 그래서 <b>경계를 정하는 규칙</b>이 필요하다."},{"t":"가장 흔한 두 가지는 <b>구분자</b>(줄바꿈 같은 특별한 바이트로 끊기)와 <b>길이 접두</b>(앞에 길이를 적고 그만큼 읽기)다. 구분자는 사람이 읽기 좋지만 데이터 안에 그 바이트가 들어가면 깨진다. 길이 접두는 그 문제가 없지만 길이가 깨지면 이후 전체가 어긋난다."},{"t":"보드의 수신 버퍼는 작다(우노 기준 64바이트). 루프가 다른 일을 하는 동안 그보다 많이 들어오면 <b>넘친 만큼 조용히 사라진다</b>. 오류도 안 나고 로그도 안 남는다. 그래서 루프 한 바퀴가 길어지는 것 자체가 통신 문제로 나타난다."},{"t":"깨진 것을 알아채려면 <b>체크섬</b>을 붙인다. 더하기나 XOR 은 만들기 쉽지만 바이트 순서가 바뀐 것이나 짝수 번 뒤집힌 비트를 놓친다. CRC 는 같은 1바이트로도 훨씬 잘 잡는다. 그래도 길이와 일련번호를 함께 확인하는 편이 안전하다."}],"code":{"c":"/* 길이 접두 프레임: [길이][페이로드...][체크섬] */\nwhile (Serial.available()) {\n  buf[n++] = Serial.read();\n  if (n >= 1 && n == buf[0] + 2) { handle(buf); n = 0; }\n}"},"key":["직렬 통신에는 경계가 없다 — 한 번에 보낸 것이 나뉘어 오고, 두 건이 붙어 온다","수신 버퍼가 넘치면 조용히 버려진다. 루프가 길어지는 것이 곧 통신 문제다","구분자 방식은 데이터에 그 바이트가 들어가면 깨진다","더하기·XOR 체크섬은 순서 바뀜을 못 잡는다"]}},{"t":"흐름에 경계 만들기 III","q":[{"t":"choice","k":"짝수 번 뒤집히면","cat":"internals","q":"두 바이트에서 <b>같은 자리 비트가 하나씩</b> 뒤집혔다. XOR 체크섬은 이것을 잡는가?","code":"원본       41 42 43 44 → xor8 4\n두 곳 뒤집힘 40 43 43 44 → xor8 ?","o":["못 잡는다 — 같은 자리에서 두 번 뒤집히면 XOR 결과가 원래대로 돌아온다","바이트 수가 짝수일 때만 잡는다","잡지만 어느 바이트가 깨졌는지는 모른다","잡는다 — 비트가 하나라도 바뀌면 XOR 의 결과는 언제나 반드시 달라지기 때문이다"],"a":0,"ex":"실행해 확인했다 — 원본도 뒤집힌 것도 xor8 이 4 로 같다. 같은 데이터에 CRC-8 은 98 과 31 로 갈린다.\n💡 개념: XOR 은 같은 자리 비트가 짝수 번 뒤집히면 <b>구조적으로</b> 못 잡는다. 확률 문제가 아니라 원리 문제다.\n🛠 실무: 전기 잡음은 여러 비트를 한꺼번에 뒤집는 경우가 많아 이 구멍이 실제로 걸린다. 잡음이 있는 환경일수록 XOR 체크섬을 믿으면 안 된다."},{"t":"choice","k":"얼마나 놓치나","cat":"internals","q":"8바이트 프레임에 무작위 2비트 오류를 20만 번 넣고 더하기 체크섬과 CRC-8 이 각각 몇 번 놓치는지 셌다. 결과는?","code":"sum8 놓침 : ?\ncrc8 놓침 : ?","o":["둘 다 256분의 1 정도로 비슷하게 놓친다","sum8 은 6% 넘게 놓치고 CRC-8 은 한 번도 안 놓친다 — 같은 1바이트인데 결과가 갈린다","둘 다 한 번도 안 놓친다 — 2비트 오류는 어느 방식으로도 잡힌다","CRC-8 이 오히려 더 많이 놓친다 — 나눗셈으로 계산하는 과정에서 정보 일부를 잃어버리기 때문이다"],"a":1,"ex":"직접 20만 번 돌려 센 값이다 — sum8 12,351회(6.18%), CRC-8 0회.\n💡 개념: CRC 는 짧은 프레임의 2비트 오류를 <b>설계상 전부</b> 잡도록 다항식이 골라져 있다. 더하기는 자리 올림이 서로 상쇄되며 자주 놓친다.\n🛠 실무: 프레임이 길어지면 CRC-8 도 놓치기 시작한다. 길이가 길면 CRC-16 으로 올리거나, 프레임을 짧게 나눈다."},{"t":"choice","k":"체크섬만으로 충분한가","q":"CRC 를 붙였는데도 데이터가 어긋난다. 체크섬은 매번 통과한다. 무엇을 더 확인해야 하는가?","code":"받은 프레임: [길이][페이로드][CRC]  — CRC 는 항상 맞음","o":["전송 속도를 낮추면 해결된다","체크섬을 두 개 붙이면 해결된다","프레임이 <b>빠졌거나 중복</b>됐을 수 있다","CRC 다항식을 더 긴 것으로 바꾸면 해결된다"],"a":2,"ex":"체크섬은 <b>한 프레임 안의</b> 오류만 본다.\n💡 개념: 프레임 하나가 통째로 사라져도 남은 프레임은 각자 온전하므로 체크섬은 전부 통과한다. 누락·중복·순서 뒤바뀜은 다른 장치가 필요하다.\n🛠 실무: 1바이트 일련번호만 붙여도 '몇 번이 빠졌다' 를 알 수 있다. 그 정보가 있어야 재전송을 요청하거나 최소한 로그에 남길 수 있다.\n✅ 왜 그 답인가: 일련번호를 넣어야 순서와 누락이 보인다"},{"t":"choice","k":"동기를 잃었을 때","q":"길이 필드가 잡음으로 깨져 200 으로 읽혔다. 실제 프레임은 5바이트였다. 이후 어떻게 되는가?","code":"받은 길이: 200 (실제 5)","o":["길이 필드는 잡음에 강해 이런 일이 생기지 않는다","200바이트가 안 오면 자동으로 복구된다","체크섬이 틀리게 나오므로 그 프레임 하나만 버리고 그냥 넘어가면 다음부터는 곧바로 정상으로 돌아온다","다음 프레임들을 페이로드로 잘못 삼켜 <b>이후 전체가 어긋난다</b> — 동기를 다시 맞출 방법이 필요하다"],"a":3,"ex":"길이 접두 방식의 대표적인 약점이다.\n💡 개념: 구분자 방식은 다음 구분자에서 저절로 동기가 맞지만, 길이 접두는 <b>한 번 어긋나면 스스로 못 돌아온다</b>.\n🛠 실무: 그래서 실제 프로토콜은 프레임 앞에 <b>시작 표시</b>(0xAA 0x55 같은)를 두고, 길이에 상한을 두고, 시한을 넘기면 버퍼를 비우고 시작 표시를 다시 찾는다. 세 가지를 함께 두어야 스스로 회복한다."}],"th":{"sum":"직렬 통신에는 '한 건' 이라는 경계가 없다. 경계를 만드는 것도, 흘러넘치는 버퍼를 관리하는 것도, 깨진 것을 알아채는 것도 전부 우리 몫이다.","body":[{"t":"UART 로 오는 것은 <b>바이트 흐름</b>뿐이다. 보낸 쪽이 한 번에 <code>ABC\\n</code> 를 썼어도 받는 쪽에서는 <code>AB</code> 와 <code>C\\n</code> 로 두 번에 나뉘어 도착할 수 있고, 반대로 두 건이 한 번에 붙어 올 수도 있다. 그래서 <b>경계를 정하는 규칙</b>이 필요하다."},{"t":"가장 흔한 두 가지는 <b>구분자</b>(줄바꿈 같은 특별한 바이트로 끊기)와 <b>길이 접두</b>(앞에 길이를 적고 그만큼 읽기)다. 구분자는 사람이 읽기 좋지만 데이터 안에 그 바이트가 들어가면 깨진다. 길이 접두는 그 문제가 없지만 길이가 깨지면 이후 전체가 어긋난다."},{"t":"보드의 수신 버퍼는 작다(우노 기준 64바이트). 루프가 다른 일을 하는 동안 그보다 많이 들어오면 <b>넘친 만큼 조용히 사라진다</b>. 오류도 안 나고 로그도 안 남는다. 그래서 루프 한 바퀴가 길어지는 것 자체가 통신 문제로 나타난다."},{"t":"깨진 것을 알아채려면 <b>체크섬</b>을 붙인다. 더하기나 XOR 은 만들기 쉽지만 바이트 순서가 바뀐 것이나 짝수 번 뒤집힌 비트를 놓친다. CRC 는 같은 1바이트로도 훨씬 잘 잡는다. 그래도 길이와 일련번호를 함께 확인하는 편이 안전하다."}],"code":{"c":"/* 길이 접두 프레임: [길이][페이로드...][체크섬] */\nwhile (Serial.available()) {\n  buf[n++] = Serial.read();\n  if (n >= 1 && n == buf[0] + 2) { handle(buf); n = 0; }\n}"},"key":["직렬 통신에는 경계가 없다 — 한 번에 보낸 것이 나뉘어 오고, 두 건이 붙어 온다","수신 버퍼가 넘치면 조용히 버려진다. 루프가 길어지는 것이 곧 통신 문제다","구분자 방식은 데이터에 그 바이트가 들어가면 깨진다","더하기·XOR 체크섬은 순서 바뀜을 못 잡는다"]}},{"t":"흐름에 경계 만들기 IV","q":[{"t":"choice","k":"시작 표시가 데이터에 있으면","q":"프레임 시작 표시로 0xAA 를 쓰는데 페이로드에도 0xAA 가 나올 수 있다. 어떻게 다루는가?","code":"[0xAA][길이][페이로드 ... 0xAA 포함 가능 ...][CRC]","o":["시작 표시만으로 프레임 시작을 <b>확정하지 않고</b>, 길이와 CRC 까지 맞을 때 비로소 프레임으로 인정한다","시작 표시를 4바이트로 늘리면 완전히 해결된다","페이로드에서 0xAA 라는 값을 아예 금지한다 — 프로토콜 규칙에서 보낼 수 없는 값으로 못 박아 둔다","0xAA 가 두 번 연속 나오면 시작으로 본다"],"a":0,"ex":"시작 표시는 <b>후보를 좁히는 힌트</b>이지 확정 신호가 아니다.\n💡 개념: 표시를 길게 하면 우연히 겹칠 확률은 줄지만 0이 되지 않는다. 결국 길이와 CRC 로 확인해야 하고, 안 맞으면 한 바이트 밀어 다음 후보를 찾는다.\n🛠 실무: 값 자체를 금지하는 방법(이스케이프)도 실제로 쓰인다. 다만 페이로드 길이가 데이터에 따라 달라져 버퍼 계산이 복잡해진다."},{"t":"choice","k":"무엇을 먼저 확인하나","cat":"debug","q":"현장에서 '가끔 값이 튄다' 는 신고가 왔다. 로그에는 아무것도 없다. 무엇부터 넣는가?","code":"// 지금 코드는 프레임을 받아 처리만 하고 아무것도 세지 않는다","o":["체크섬을 CRC-16 으로 올린다","버려진 프레임 수·체크섬 실패 수·버퍼 넘침 수를 세어 주기적으로 내보낸다 — 세지 않으면 영원히 안 보인다","케이블을 차폐선으로 바꾼다","전송 속도를 절반으로 낮춘다 — 현장에서는 전송 속도가 문제인 경우가 대부분이므로 대개 그것만으로 그대로 해결된다"],"a":1,"ex":"조용히 사라지는 문제는 세기 시작해야 보인다.\n💡 개념: 세 가지 카운터(넘침·체크섬 실패·형식 오류)만 있으면 원인이 대개 하나로 좁혀진다. 넘침이 크면 루프가 긴 것이고, 체크섬 실패가 크면 전기적 문제다.\n🛠 실무: 카운터는 int 하나씩이면 충분하다. 10초마다 한 줄 내보내는 것만으로 현장 진단이 완전히 달라진다."},{"t":"choice","k":"흐름 제어","q":"상대가 계속 빠르게 보내는데 우리 루프가 못 따라간다. 프로토콜 차원의 대책은?","code":"// 보드 → PC: \"준비됨\" / \"잠깐\" 을 돌려보낼 수 있다","o":["루프에서 delay 를 없앤다 — 그것만으로 항상 해결된다","전송 속도를 115200 으로 올린다 — 그만큼 더 빨리 받아 내면 처리가 밀리지 않게 된다","받을 준비가 됐을 때만 보내게 한다 — 상대가 우리 속도에 맞추게 하는 것이 근본 대책이다","수신 버퍼를 1024바이트로 늘린다 — 그것으로 끝난다"],"a":2,"ex":"받는 쪽이 못 따라가면 결국 어딘가에서 버려진다.\n💡 개념: 버퍼를 키우는 것은 <b>평균이 감당되는데 순간만 몰릴 때</b> 유효하다. 평균 자체가 넘치면 아무리 키워도 밀린다 — 시간 문제일 뿐이다.\n🛠 실무: 요청-응답 방식으로 바꾸는 것이 가장 단순하다. 보드가 '다음' 이라고 할 때만 상대가 한 건을 보내면 버퍼가 넘칠 수 없다."},{"t":"choice","k":"설계를 고른다","cat":"design","q":"센서 12개 값을 초당 20번 PC 로 보내야 한다. 값은 이진 데이터이고 잡음이 있는 환경이다. 어떤 형식을 고르겠는가?","code":"// 후보 A: \"v1,v2,...,v12\\n\" 텍스트 CSV\n// 후보 B: [0xAA][길이][이진 페이로드][일련번호][CRC-8]","o":["A — 이진 형식은 엔디안 문제 때문에 쓸 수 없다","둘 다 같다 — 형식은 취향의 문제다","A — 사람이 눈으로 읽을 수 있어야 디버깅이 가능하므로 어떤 경우에도 텍스트 형식이 낫다. 잡음이 있어도 눈으로 확인하면 된다","B — 이진 값에 구분자 충돌이 없고, 잡음 환경에서 CRC 와 일련번호가 필요하며, 바이트 수도 적어 대역폭에 여유가 생긴다"],"a":3,"ex":"조건 세 가지(이진 값·잡음·주기적 대량 전송)가 모두 B 를 가리킨다.\n💡 개념: 텍스트가 유리한 경우도 분명히 있다 — 사람이 터미널로 붙어 보는 진단 채널이나 전송량이 적을 때다. <b>조건을 보고 고르는 것</b>이지 한쪽이 늘 낫지 않다.\n🛠 실무: 실제로는 둘 다 두는 경우가 많다. 평소에는 이진으로 보내고, 진단 모드에서만 사람이 읽을 수 있는 텍스트를 내보낸다."}],"th":{"sum":"직렬 통신에는 '한 건' 이라는 경계가 없다. 경계를 만드는 것도, 흘러넘치는 버퍼를 관리하는 것도, 깨진 것을 알아채는 것도 전부 우리 몫이다.","body":[{"t":"UART 로 오는 것은 <b>바이트 흐름</b>뿐이다. 보낸 쪽이 한 번에 <code>ABC\\n</code> 를 썼어도 받는 쪽에서는 <code>AB</code> 와 <code>C\\n</code> 로 두 번에 나뉘어 도착할 수 있고, 반대로 두 건이 한 번에 붙어 올 수도 있다. 그래서 <b>경계를 정하는 규칙</b>이 필요하다."},{"t":"가장 흔한 두 가지는 <b>구분자</b>(줄바꿈 같은 특별한 바이트로 끊기)와 <b>길이 접두</b>(앞에 길이를 적고 그만큼 읽기)다. 구분자는 사람이 읽기 좋지만 데이터 안에 그 바이트가 들어가면 깨진다. 길이 접두는 그 문제가 없지만 길이가 깨지면 이후 전체가 어긋난다."},{"t":"보드의 수신 버퍼는 작다(우노 기준 64바이트). 루프가 다른 일을 하는 동안 그보다 많이 들어오면 <b>넘친 만큼 조용히 사라진다</b>. 오류도 안 나고 로그도 안 남는다. 그래서 루프 한 바퀴가 길어지는 것 자체가 통신 문제로 나타난다."},{"t":"깨진 것을 알아채려면 <b>체크섬</b>을 붙인다. 더하기나 XOR 은 만들기 쉽지만 바이트 순서가 바뀐 것이나 짝수 번 뒤집힌 비트를 놓친다. CRC 는 같은 1바이트로도 훨씬 잘 잡는다. 그래도 길이와 일련번호를 함께 확인하는 편이 안전하다."}],"code":{"c":"/* 길이 접두 프레임: [길이][페이로드...][체크섬] */\nwhile (Serial.available()) {\n  buf[n++] = Serial.read();\n  if (n >= 1 && n == buf[0] + 2) { handle(buf); n = 0; }\n}"},"key":["직렬 통신에는 경계가 없다 — 한 번에 보낸 것이 나뉘어 오고, 두 건이 붙어 온다","수신 버퍼가 넘치면 조용히 버려진다. 루프가 길어지는 것이 곧 통신 문제다","구분자 방식은 데이터에 그 바이트가 들어가면 깨진다","더하기·XOR 체크섬은 순서 바뀜을 못 잡는다"]}}],"ord":9},{"t":"실행형 실전 — 신호를 길들인다","l":[{"t":"디바운스·값 매핑·이동평균","xp":80,"th":{"sum":"하드웨어의 신호는 더럽다 — **튀고(채터링), 어긋나고(범위), 흔들린다(노이즈)**. 셋 다 몇 줄의 필터로 길들일 수 있다.","body":[{"h":"믿을 때까지 기다린다","t":"기계식 버튼은 누르는 순간 수 ms 동안 붙었다 떨어졌다를 반복한다. 디바운스는 '같은 값이 충분히 유지될 때만 믿는다' — 값이 흔들리면 **대기 시간을 리셋**하는 것이 핵심이다. delay() 로 기다리면 다른 일이 전부 멈추므로, 시각을 인자로 받는 비차단 구조라야 한다."},{"h":"범위를 옮기고 노이즈를 눌러 담는다","t":"10비트 ADC 를 8비트 PWM 으로 옮길 때는 **곱셈 먼저, 나눗셈 나중** — 정수 나눗셈이 먼저 오면 거의 항상 0이 된다. 내장 map() 은 범위 밖 입력을 자르지 않으므로 clamp 를 함께 쓴다. 이동평균 링 버퍼는 **차기 전에는 받은 개수로** 나눠야 초반 값이 왜곡되지 않는다."}],"code":{"c":"// 흔들리면 대기 시간을 다시 시작\nif (reading !== cand) { cand = reading; since = now; }\nif (cand !== stable && now - since >= ms) stable = cand;","cap":"리셋 없는 디바운스는 채터링 중간에 확정해 버린다"},"key":["디바운스는 유지 시간 + 리셋","비차단 구조라야 루프가 계속 돈다","정수 연산은 곱셈 먼저","이동평균 분모는 min(받은 개수, n)"]},"q":[{"t":"code","run":"js","k":"버튼 디바운스","cat":"internals","q":"기계식 버튼의 <b>디바운스</b>를 구현하세요. <code>makeDebounce(ms)</code> 는 <code>(reading, now)</code> 를 받는 함수를 돌려줍니다. 새 읽기값이 <b><code>ms</code> 밀리초 동안 유지될 때만</b> 안정값을 그 값으로 바꾸고, 항상 현재 안정값을 돌려줍니다. 읽기값이 흔들리면 대기 시간은 <b>다시 시작</b>됩니다. 초기 안정값은 0 입니다.","src":"function makeDebounce(ms) {\n  // TODO: 후보가 ms 동안 유지되면 안정값 갱신\n  return (reading, now) => reading;\n}","sol":"function makeDebounce(ms) {\n  let stable = 0, cand = 0, since = 0;\n  return (reading, now) => {\n    if (reading !== cand) { cand = reading; since = now; }\n    if (cand !== stable && now - since >= ms) stable = cand;\n    return stable;\n  };\n}","tests":[{"in":"(() => { const d=makeDebounce(50); return [d(1,0), d(1,30), d(1,50)]; })()","out":"[0,0,1]"},{"in":"(() => { const d=makeDebounce(50); d(1,0); d(0,20); d(1,40); return d(1,100); })()","out":"1"},{"in":"(() => { const d=makeDebounce(50); d(1,0); d(0,20); return d(1,60); })()","out":"0"},{"in":"(() => { const d=makeDebounce(50); d(1,0); d(1,50); d(0,60); return [d(0,100), d(0,110)]; })()","out":"[1,0]"}],"edge":[{"in":"(() => { const d=makeDebounce(0); return d(1,5); })()","out":"1"},{"in":"(() => { const d=makeDebounce(50); return [d(0,0), d(0,100)]; })()","out":"[0,0]"}],"ex":"🎯 기계식 접점은 누르는 순간 수 밀리초 동안 <b>붙었다 떨어졌다를 반복</b>합니다(채터링). 그대로 읽으면 한 번 눌렀는데 인터럽트가 수십 번 발생합니다 — 카운터가 몇 씩 뛰는 고전적 증상입니다.\n💡 해법은 '<b>같은 값이 충분히 오래 유지될 때만 믿는다</b>' 입니다. 값이 흔들리면 <code>since</code> 를 지금으로 리셋해 대기 시간을 다시 시작하는 것이 핵심입니다 — 리셋 없이 첫 변화 시각만 기억하면 채터링 중간에 잘못 확정됩니다.\n⚠️ <code>delay(50)</code> 으로 기다리는 방식은 그동안 <b>다른 입력·통신이 전부 멈춥니다</b>. 시각을 인자로 받는 이 구조(비차단)라야 루프가 계속 돌 수 있고, 테스트도 가능해집니다.\n🔧 같은 패턴이 소프트웨어에도 그대로 있습니다 — 검색창의 디바운스, 알림 묶어 보내기, 헬스체크의 연속 N회 실패 조건이 모두 '흔들림을 걸러 안정 신호만 통과' 시키는 같은 필터입니다."},{"t":"code","run":"js","k":"아날로그 값 매핑","cat":"internals","q":"센서 값을 다른 범위로 <b>매핑</b>하세요. <code>mapRange(x, inLo, inHi, outLo, outHi)</code> 는 <code>x</code> 를 입력 범위에서 출력 범위로 비례 변환합니다. <b>입력 범위를 벗어나면 잘라내고(clamp)</b>, 결과는 <b>내림(floor)</b>으로 정수화합니다. 출력 범위는 뒤집혀 있을 수도 있습니다.","src":"function mapRange(x, inLo, inHi, outLo, outHi) {\n  // TODO: clamp 후 비례 변환, floor\n  return x;\n}","sol":"function mapRange(x, inLo, inHi, outLo, outHi) {\n  const cx = Math.min(Math.max(x, inLo), inHi);\n  return Math.floor((cx - inLo) * (outHi - outLo) / (inHi - inLo) + outLo);\n}","tests":[{"in":"mapRange(512,0,1023,0,255)","out":"127"},{"in":"mapRange(0,0,1023,0,255)","out":"0"},{"in":"mapRange(1023,0,1023,0,255)","out":"255"},{"in":"mapRange(2000,0,1023,0,255)","out":"255"}],"edge":[{"in":"mapRange(-5,0,1023,0,255)","out":"0"},{"in":"mapRange(5,0,10,100,0)","out":"50"}],"ex":"🎯 10비트 ADC(0~1023)를 8비트 PWM(0~255)으로 옮기는 것이 아두이노의 가장 흔한 계산입니다. 공식은 '<b>입력에서의 비율을 출력 범위에 다시 펼치기</b>' — <code>(x−inLo)·(outHi−outLo)/(inHi−inLo)+outLo</code> 입니다.\n💡 <b>곱셈을 먼저, 나눗셈을 나중에</b> 해야 정수 연산에서 정밀도를 잃지 않습니다. <code>x/1023*255</code> 를 정수로 계산하면 <code>x/1023</code> 이 거의 항상 0이 됩니다 — C 정수 나눗셈의 고전적 함정입니다.\n⚠️ 아두이노의 내장 <code>map()</code> 은 <b>범위를 벗어난 입력을 자르지 않습니다</b>. 센서 스파이크가 그대로 출력 범위 밖으로 나가 서보를 한계 밖으로 밀 수 있어, 실전에서는 <code>constrain()</code> 을 함께 쓰는 것이 정석입니다.\n🔧 출력 범위를 <code>(100, 0)</code> 처럼 뒤집으면 <b>반전 매핑</b>이 공짜로 됩니다 — 밝을수록 LED 를 어둡게 하는 조도 반응이 한 줄로 끝납니다."},{"t":"code","run":"js","k":"링 버퍼 이동평균","cat":"internals","q":"노이즈 낀 센서 값을 <b>이동평균</b>으로 부드럽게 만드세요. <code>makeAvg(n)</code> 은 값을 하나 받을 때마다 <b>최근 n개의 평균</b>을 돌려주는 함수를 만듭니다. 링 버퍼로 구현하고, <b>버퍼가 차기 전에는 지금까지 받은 개수로</b> 나눠야 합니다.","src":"function makeAvg(n) {\n  const buf = [];\n  return (v) => {\n    buf.push(v);\n    return buf.reduce((a, b) => a + b, 0) / n;\n  };\n}","sol":"function makeAvg(n) {\n  const buf = new Array(n).fill(0);\n  let idx = 0, count = 0, sum = 0;\n  return (v) => {\n    if (count === n) sum -= buf[idx];\n    else count++;\n    buf[idx] = v; sum += v;\n    idx = (idx + 1) % n;\n    return sum / count;\n  };\n}","tests":[{"in":"(() => { const a=makeAvg(3); return [a(3), a(6), a(9), a(12)]; })()","out":"[3,4.5,6,9]"},{"in":"(() => { const a=makeAvg(2); a(10); a(20); return a(30); })()","out":"25"},{"in":"(() => { const a=makeAvg(4); return a(8); })()","out":"8"},{"in":"(() => { const a=makeAvg(3); a(10); a(10); return a(100); })()","out":"40"}],"edge":[{"in":"(() => { const a=makeAvg(1); a(5); return a(9); })()","out":"9"},{"in":"(() => { const a=makeAvg(2); a(1); return a(2); })()","out":"1.5"}],"ex":"🎯 시작 코드의 버그는 <b>분모</b>입니다. 버퍼가 차기 전에 n 으로 나누면 첫 값들이 실제보다 작게 나옵니다 — 전원을 켠 직후 몇 초간 센서가 '낮게' 읽히는 미스터리의 정체가 대개 이것입니다.\n💡 링 버퍼는 <b>메모리가 고정</b>이고, 합계를 증분으로 유지하면(나갈 값 빼고 들어올 값 더하기) 매번 전체를 다시 더하지 않아 <b>O(1)</b> 입니다. 마이크로컨트롤러의 2KB RAM 에서는 이 차이가 생존의 문제입니다.\n⚠️ 창 크기 n 은 트레이드오프입니다 — 크면 부드럽지만 <b>반응이 느려지고</b>, 작으면 빠르지만 노이즈가 남습니다. 스파이크 노이즈(순간 튐)에는 평균보다 <b>중앙값 필터</b>가 훨씬 강합니다.\n🔧 같은 원리가 서버 모니터링의 이동평균 그래프, 주가의 MA 선, 지수이동평균(EMA, 버퍼 없이 <code>avg += α(v−avg)</code>)으로 이어집니다."}]}],"ord":11},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"신호 시뮬레이션","lv":2,"cat":"internals","q":"<b>PWM 듀티</b>가 평균 전압으로 어떻게 바뀌는지 보이세요. <code>analogWrite(pin, v)</code> 의 <code>v</code> 는 0~255 이고 듀티는 <code>v/255</code>, 평균 전압은 <code>5V × 듀티</code> 입니다. 값마다 <code>snap(값, {duty, volt}, {v})</code> 를 남기고 <b>[v=64 의 평균 전압, v=191 의 평균 전압, LED 밝기를 절반으로 보이게 하려면 넣어야 할 대략적인 v]</b> 를 소수 둘째 자리로 반올림해 돌려주세요. 사람 눈은 밝기를 대략 <b>제곱근</b>으로 느끼므로 절반 밝기는 듀티 0.25 입니다.","src":"const VCC = 5, MAX = 255;\nconst VALUES = [0, 64, 128, 191, 255];\n\nfunction pwm() {\n  return [0, 0, 0];\n}\n\nRESULT = pwm();","tests":[{"d":"v=64 는 약 1.25V","js":"RESULT[0]===1.25"},{"d":"v=191 은 약 3.75V","js":"RESULT[1]===3.75"},{"d":"체감 절반 밝기는 v≈64","js":"RESULT[2]===64"},{"d":"값마다 장면이 남는다","js":"FRAMES.length===5"},{"d":"듀티와 전압이 비례한다","js":"FRAMES[4].value.volt===5&&FRAMES[0].value.volt===0"},{"d":"가운데 값은 절반 전압","js":"Math.abs(FRAMES[2].value.volt-2.51)<0.02"}],"ex":"PWM 은 전압을 <b>낮추는 것이 아니라 빠르게 껐다 켜는</b> 것입니다 — 핀은 언제나 0V 아니면 5V 이고, 평균만 그 사이 값이 됩니다. 그래서 LED·모터에는 잘 통하지만 <b>진짜 아날로그 전압이 필요한 곳</b>(오디오 기준 전압, 센서 바이어스)에는 쓸 수 없고 DAC 나 RC 저역통과 필터가 필요합니다. 또 하나, <b>듀티 50% 가 밝기 50% 로 보이지 않습니다</b> — 사람 눈은 로그에 가깝게 반응해서 절반으로 <b>보이게</b> 하려면 듀티를 25% 근처까지 낮춰야 합니다. 밝기 곡선을 선형으로 넣고 '중간이 너무 밝다' 고 느끼는 이유입니다."},{"t":"sim","k":"신호 시뮬레이션","lv":3,"cat":"internals","q":"<b>10비트 ADC</b> 의 양자화를 계산하세요. 0~5V 를 0~1023 으로 읽으므로 한 칸은 <code>5/1023</code> V 입니다. 입력 전압마다 <code>analogRead</code> 값은 <code>round(V/5×1023)</code> 이고, 그 값을 다시 전압으로 되돌리면 <b>원래 값과 조금 다릅니다</b>. 전압마다 <code>snap(V, {raw, back, err}, {mv})</code> 를 남기고 <b>[한 칸의 크기(mV, 소수 둘째 자리), 3.3V 를 읽은 raw 값, 최대 오차(mV, 소수 둘째 자리)]</b> 를 돌려주세요.","src":"const VREF = 5, BITS = 10;\nconst SAMPLES = [0.5, 1.0, 3.3, 4.9];\n\nfunction adc() {\n  return [0, 0, 0];\n}\n\nRESULT = adc();","tests":[{"d":"한 칸은 약 4.89mV","js":"RESULT[0]===4.89"},{"d":"3.3V 는 675 로 읽힌다","js":"RESULT[1]===675"},{"d":"최대 오차는 반 칸(약 2.44mV) 이하","js":"RESULT[2]<=2.45"},{"d":"표본마다 장면이 남는다","js":"FRAMES.length===4"},{"d":"되돌린 전압이 원래 값과 아주 가깝다","js":"FRAMES.every(function(f){return Math.abs(f.value.err)<3;})"},{"d":"raw 값은 0~1023 안에 있다","js":"FRAMES.every(function(f){return f.value.raw>=0&&f.value.raw<=1023;})"}],"ex":"10비트 ADC 는 5V 를 <b>1024칸</b>으로 나누므로 아무리 잘해도 <b>±2.4mV</b> 의 양자화 오차가 남습니다. 미세한 신호를 재려면 방법은 셋입니다 — <b>기준 전압을 낮추거나</b>(<code>analogReference(INTERNAL)</code> 로 1.1V 를 쓰면 한 칸이 1mV 로 줄어듭니다), <b>증폭</b>하거나, <b>여러 번 읽어 평균</b>내는 것(오버샘플링)입니다. 반대로 흔한 실수는 <b>정수 나눗셈</b>입니다: <code>raw * 5 / 1023</code> 을 int 로 계산하면 전부 0 이나 1 이 되고, <code>raw * 5.0 / 1023</code> 로 써야 소수가 살아납니다. 그리고 <code>analogRead</code> 는 약 100µs 가 걸려 <b>빠른 루프에서 여러 채널을 읽으면</b> 그 자체가 병목이 됩니다."},{"t":"sim","k":"타이밍 시뮬레이션","lv":3,"cat":"internals","q":"버튼 <b>채터링</b>을 걸러 내세요. 접점이 튀어 짧은 시간에 여러 번 바뀝니다. <b>마지막으로 인정한 시각에서 50ms 가 지나지 않은 변화는 무시</b>합니다(가상 시계). 신호마다 <code>snap(시각+'ms', {state, accepted}, {t, accepted})</code> 를 남기고 <b>[디바운싱 없이 센 눌림 횟수, 디바운싱 뒤 눌림 횟수, 인정된 시각 배열]</b> 을 돌려주세요.","src":"// [시각(ms), 상태]  1=눌림 0=뗌\nconst SIGNAL = [[0,1],[5,0],[9,1],[12,0],[15,1],[300,0],[400,1],[600,0]];\nconst DEBOUNCE = 50;\n\nfunction debounce() {\n  return [0, 0, []];\n}\n\nRESULT = debounce();","tests":[{"d":"그대로 세면 눌림이 4번","js":"RESULT[0]===4"},{"d":"디바운싱하면 2번","js":"RESULT[1]===2"},{"d":"인정된 눌림 시각은 0ms 와 400ms","js":"JSON.stringify(RESULT[2])===JSON.stringify([0,400])"},{"d":"신호마다 장면이 남는다","js":"FRAMES.length===8"},{"d":"튀는 구간은 무시된다","js":"FRAMES[2].opt.accepted===false&&FRAMES[4].opt.accepted===false"},{"d":"충분히 지난 뒤의 변화는 인정된다","js":"FRAMES[6].opt.accepted===true"}],"ex":"기계식 접점은 붙는 순간 <b>수 밀리초 동안 수십 번</b> 튑니다. 그대로 세면 한 번 눌렀는데 네 번 눌린 것이 되므로, <b>마지막으로 인정한 시각</b>을 기억해 두고 일정 시간(보통 20~50ms) 안의 변화를 버립니다. 여기서 중요한 것은 구현 방식입니다 — <code>delay(50)</code> 으로 기다리면 <b>그동안 아무것도 못 합니다</b>(다른 버튼도, 통신도 멈춥니다). 그래서 <code>millis()</code> 로 시각을 기억하는 <b>논블로킹</b> 방식을 씁니다. 참고로 <code>millis()</code> 는 약 49일에 한 번 감기는데, <code>now - last &gt;= 50</code> 처럼 <b>뺄셈으로 비교</b>하면 unsigned 연산이라 감겨도 정확히 동작합니다 — <code>now &gt;= last + 50</code> 으로 쓰면 그때 깨집니다."},{"t":"sim","k":"타이밍 시뮬레이션","lv":3,"cat":"internals","q":"짧은 펄스를 <b>폴링</b>과 <b>인터럽트</b>로 각각 잡아 보세요. 루프 한 바퀴가 <b>20ms</b> 걸려 그 순간에만 핀을 읽습니다(폴링). 펄스는 <b>5ms</b> 동안만 높아지므로 루프 시점과 겹쳐야 잡힙니다. 인터럽트는 <b>모두</b> 잡습니다. 펄스마다 <code>snap(펄스, {polled, missed}, {at})</code> 를 남기고 <b>[폴링이 잡은 수, 놓친 수, 인터럽트가 잡은 수]</b> 를 돌려주세요.","src":"const LOOP_MS = 20, PULSE_MS = 5;\nconst PULSES = [0, 17, 33, 40, 55, 61, 80];   // 펄스 시작 시각(ms)\n\nfunction capture() {\n  return [0, 0, 0];\n}\n\nRESULT = capture();","tests":[{"d":"폴링은 4개만 잡는다","js":"RESULT[0]===4"},{"d":"3개를 놓친다","js":"RESULT[1]===3"},{"d":"인터럽트는 7개 전부 잡는다","js":"RESULT[2]===7"},{"d":"펄스마다 장면이 남는다","js":"FRAMES.length===7"},{"d":"루프 시점(0·40·80)과 겹친 펄스만 잡힌다","js":"FRAMES[0].value.polled===true&&FRAMES[3].value.polled===true&&FRAMES[6].value.polled===true"},{"d":"루프 사이에 끼인 33ms 펄스는 놓친다","js":"FRAMES[2].value.missed===true"}],"ex":"폴링은 <b>루프가 도는 순간에만</b> 세상을 봅니다 — 루프가 20ms 인데 신호가 5ms 라면 <b>절반 가까이 놓칩니다</b>(여기서는 7개 중 3개). 게다가 루프에 <code>delay()</code> 나 느린 <code>Serial.print</code> 가 하나 끼면 주기가 늘어나 어제까지 되던 코드가 오늘 안 되기도 합니다. 인터럽트는 신호가 오는 <b>즉시</b> 실행되므로 짧은 펄스(엔코더, 초음파 에코, 낙하 감지)에 적합합니다. 대신 ISR 안에서는 <b>오래 걸리는 일을 하면 안 됩니다</b> — <code>delay()</code>·<code>Serial.print</code>·동적 할당은 금지이고, 플래그만 세우고 본 루프에서 처리합니다. 그리고 ISR 과 공유하는 변수는 반드시 <code>volatile</code> 로, 여러 바이트 값이면 <b>인터럽트를 잠깐 끄고</b> 읽어야 찢어진 값을 피합니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"타이밍 시뮬레이션","lv":4,"cat":"internals","q":"<code>millis()</code> 는 <b>32비트 unsigned</b> 라 약 49.7일에 0 으로 감깁니다. 감기는 순간을 넘겨 두 가지 비교 방식을 시험하세요 — <b>뺄셈</b>(<code>now - last >= 1000</code>)과 <b>덧셈</b>(<code>now >= last + 1000</code>). 두 방식 모두 <b>32비트 unsigned 연산</b>입니다. 시점마다 <code>snap(라벨, {diff, byDiff, byAdd}, {now})</code> 를 남기고 <b>[뺄셈 방식이 참이 된 횟수, 덧셈 방식이 참이 된 횟수, 감긴 뒤 두 방식이 갈리는지]</b> 를 돌려주세요.","src":"const U32 = 4294967296, INTERVAL = 1000;\nconst LAST = U32 - 500;                       // 감기기 500ms 전에 마지막 처리\nconst NOWS = [U32 - 400, U32 - 100, 100, 600, 1500];   // 100 이후는 감긴 뒤\n\nfunction wrap() {\n  return [0, 0, false];\n}\n\nRESULT = wrap();","tests":[{"d":"뺄셈 방식은 두 번 참","js":"RESULT[0]===2"},{"d":"덧셈 방식은 4번 참 — 아직 1초가 지나지 않았는데 발동한다","js":"RESULT[1]===4"},{"d":"감김 근처에서 두 방식의 판정이 갈린다","js":"RESULT[2]===true"},{"d":"시점마다 장면이 남는다","js":"FRAMES.length===5"},{"d":"감긴 직후에도 뺄셈은 올바른 경과 시간을 준다","js":"FRAMES[2].value.diff===600"},{"d":"100ms 밖에 안 지난 시점에서 덧셈 방식만 참이 된다","js":"FRAMES[0].value.diff===100&&FRAMES[0].value.byDiff===false&&FRAMES[0].value.byAdd===true"}],"ex":"<code>millis()</code> 가 감기는 것은 <b>49.7일마다 반드시</b> 일어나는 일입니다 — 오래 켜 두는 장치라면 언젠가 만납니다. <code>now - last</code> 는 두 값이 모두 unsigned 라 <b>감김을 넘어서도 정확한 경과 시간</b>이 나옵니다(모듈로 2³² 연산의 성질). 반면 <code>last + 1000</code> 은 그 자체가 넘쳐 <b>500</b> 같은 작은 수가 되어 버립니다 — 그러면 아직 100ms 밖에 안 지났는데 조건이 참이 되어 <b>일찍 발동</b>하고, 감김 직후에는 반대로 한동안 거짓이 되어 <b>건너뜁니다</b>. 어느 쪽이든 타이밍이 무너집니다. 규칙은 하나입니다 — <b>시간 비교는 언제나 뺄셈으로.</b> 같은 이유로 타임아웃 검사도 <code>if (millis() - start &gt; TIMEOUT)</code> 형태로 씁니다. 변수를 <code>int</code> 로 선언해도 같은 사고가 나므로 <b><code>unsigned long</code></b> 을 지켜야 합니다."},{"t":"sim","k":"메모리 시뮬레이션","lv":3,"cat":"internals","q":"<b>SRAM 2,048바이트</b> 예산을 계산하세요. 전역 배열과 버퍼가 자리를 먹고, 스택은 그 위에서 자랍니다. 문자열 리터럴을 <code>Serial.print(\"...\")</code> 로 쓰면 <b>RAM 에 복사</b>되지만 <code>F(\"...\")</code> 로 감싸면 <b>플래시에 남습니다</b>. 항목마다 <code>snap(항목, {used, free}, {kind})</code> 을 남기고 <b>[문자열을 그대로 뒀을 때 남는 바이트, F() 로 감쌌을 때 남는 바이트, 스택 여유 512바이트를 확보할 수 있는지(F 적용 후)]</b> 를 돌려주세요.","src":"const SRAM = 2048, STACK_NEED = 512;\nconst ITEMS = [\n  { name: 'sensorBuf[256] (int)', bytes: 512, kind: 'global' },\n  { name: 'logBuf[400] (char)',   bytes: 400, kind: 'global' },\n  { name: '문자열 리터럴 30개',    bytes: 900, kind: 'string' },\n  { name: '기타 전역',            bytes: 120, kind: 'global' }\n];\n\nfunction sram() {\n  return [0, 0, false];\n}\n\nRESULT = sram();","tests":[{"d":"그대로 두면 116바이트만 남는다","js":"RESULT[0]===116"},{"d":"F() 로 감싸면 1,016바이트가 남는다","js":"RESULT[1]===1016"},{"d":"그때는 스택 512바이트를 확보할 수 있다","js":"RESULT[2]===true"},{"d":"항목마다 장면이 남는다","js":"FRAMES.length===4"},{"d":"문자열이 가장 큰 덩어리다","js":"FRAMES[2].opt.kind==='string'"},{"d":"누적 사용량이 계속 는다","js":"FRAMES.every(function(f,i){return i===0||f.value.used>FRAMES[i-1].value.used;})"}],"ex":"아두이노 우노의 SRAM 은 <b>2KB 뿐</b>이고, 여기에 전역·힙·스택이 <b>모두</b> 들어갑니다. 초보자가 가장 많이 흘리는 곳이 <b>문자열</b>입니다 — <code>Serial.print(\"온도가 높습니다\")</code> 같은 리터럴은 프로그램이 시작할 때 플래시에서 RAM 으로 복사되므로, 메시지 서른 개면 1KB 가 사라집니다. <code>F(\"...\")</code> 로 감싸면 플래시에 그대로 두고 읽어 오므로 RAM 이 그만큼 살아납니다. 남은 RAM 이 부족하면 증상이 <b>컴파일 오류가 아니라 이상 동작</b>입니다 — 스택이 전역 영역을 침범해 변수가 저절로 바뀌거나 리셋이 반복됩니다. 그래서 임베디드에서는 동적 할당(<code>String</code>·<code>malloc</code>)을 피하고 <b>고정 크기 버퍼</b>를 씁니다."},{"t":"sim","k":"통신 시뮬레이션","lv":3,"cat":"internals","q":"<b>I2C 표준 모드(100kHz)</b> 의 전송 시간을 계산하세요. 한 비트는 <code>1/100000</code> 초이고, 바이트마다 <b>8비트 + ACK 1비트 = 9비트</b> 가 나갑니다. 한 번의 읽기는 <b>주소 1바이트 + 레지스터 1바이트 + 재시작 주소 1바이트 + 데이터 N바이트</b> 입니다. 시나리오마다 <code>snap(라벨, {bytes, bits, us}, {n})</code> 를 남기고 <b>[2바이트 읽기의 소요 시간(µs, 반올림), 6바이트 읽기의 소요 시간, 센서 3개를 각각 6바이트씩 100Hz 로 읽을 때 한 주기에서 I2C 가 차지하는 비율(%, 반올림)]</b> 을 돌려주세요.","src":"const HZ = 100000, BITS_PER_BYTE = 9, OVERHEAD_BYTES = 3;\nconst READS = [2, 6];\nconst SENSORS = 3, RATE_HZ = 100;\n\nfunction i2c() {\n  return [0, 0, 0];\n}\n\nRESULT = i2c();","tests":[{"d":"2바이트 읽기는 450µs","js":"RESULT[0]===450"},{"d":"6바이트 읽기는 810µs","js":"RESULT[1]===810"},{"d":"센서 3개를 100Hz 로 읽으면 주기의 24%","js":"RESULT[2]===24"},{"d":"시나리오마다 장면이 남는다","js":"FRAMES.length===2"},{"d":"오버헤드 3바이트가 항상 붙는다","js":"FRAMES[0].value.bytes===5&&FRAMES[1].value.bytes===9"},{"d":"데이터가 3배여도 시간은 2배가 안 된다","js":"RESULT[1]<RESULT[0]*3"}],"ex":"I2C 는 느립니다 — 100kHz 에서 <b>1바이트에 90µs</b> 이고, 주소·레지스터·재시작 같은 <b>고정 오버헤드가 3바이트</b>나 붙습니다. 그래서 <b>1바이트를 여섯 번 읽는 것보다 6바이트를 한 번에 읽는 것</b>이 두 배 넘게 빠릅니다(가속도계처럼 여러 축을 연속 레지스터로 제공하는 이유입니다). 센서 셋을 100Hz 로 돌리면 벌써 10ms 주기의 <b>4분의 1</b>을 통신이 먹으므로, 더 필요하면 <b>400kHz 고속 모드</b>로 올리거나 갱신 주기를 낮춰야 합니다. 그리고 이 계산은 <b>순수 전송 시간</b>일 뿐, 센서의 변환 대기 시간과 라이브러리 오버헤드는 따로입니다 — 그래서 실제 측정이 늘 계산보다 느립니다."},{"t":"sim","k":"전력 시뮬레이션","lv":3,"cat":"internals","q":"<b>배터리 수명</b>을 계산하세요. 장치는 주기마다 잠깐 깨어 측정·송신하고 나머지는 잠듭니다. 평균 전류는 <code>(깨어있는시간×활성전류 + 자는시간×수면전류) / 주기</code> 이고, 수명(시간)은 <code>배터리용량(mAh) / 평균전류(mA)</code> 입니다. 설정마다 <code>snap(라벨, {avgMa, days}, {awakeMs})</code> 를 남기고 <b>[항상 깨어 있을 때의 수명(일, 반올림), 100ms 만 깨어 있을 때의 수명(일), 몇 배 늘어나는지(반올림)]</b> 를 돌려주세요.","src":"const BATTERY_MAH = 2000;\nconst ACTIVE_MA = 20, SLEEP_MA = 0.05;\nconst PERIOD_MS = 10000;              // 10초마다 한 번\nconst AWAKE = [10000, 100];           // 항상 깨어 있음 vs 100ms 만\n\nfunction battery() {\n  return [0, 0, 0];\n}\n\nRESULT = battery();","tests":[{"d":"항상 깨어 있으면 4일","js":"RESULT[0]===4"},{"d":"100ms 만 깨면 334일","js":"RESULT[1]===334"},{"d":"약 84배 늘어난다","js":"RESULT[2]===84"},{"d":"설정마다 장면이 남는다","js":"FRAMES.length===2"},{"d":"평균 전류가 20mA 에서 0.25mA 로 준다","js":"FRAMES[0].value.avgMa===20&&Math.abs(FRAMES[1].value.avgMa-0.25)<0.01"},{"d":"듀티를 1%로 낮추면 수명이 수십 배가 된다","js":"FRAMES[1].value.days>FRAMES[0].value.days*50"}],"ex":"배터리 장치의 수명은 <b>깨어 있는 비율</b>이 정합니다 — 같은 하드웨어가 4일에서 <b>334일</b>로 84배 갑니다. 그래서 설계의 첫 질문은 '어떤 부품을 쓸까' 가 아니라 <b>'얼마나 자주, 얼마나 짧게 깨울까'</b> 입니다. 계산에서 눈여겨볼 점은 듀티가 1% 로 내려가면 <b>수면 전류가 지배</b>하기 시작한다는 것입니다(여기서 평균 0.2495mA 중 0.0495mA 가 수면분). 그래서 더 줄이려면 깨는 시간이 아니라 <b>수면 전류</b>를 낮춰야 하고, 대개 그 범인은 MCU 가 아니라 <b>레귤레이터·LED·풀업 저항</b>처럼 늘 켜져 있는 주변 회로입니다. 무선 송신은 활성 전류가 수십~수백 mA 라, 데이터를 <b>모아서 한 번에 보내는</b> 것이 자주 보내는 것보다 훨씬 유리합니다."},{"t":"sim","k":"신호 시뮬레이션","lv":2,"cat":"internals","q":"버튼 회로에서 <code>digitalRead</code> 가 무엇을 읽는지 판정하세요. 규칙 — <b><code>INPUT</code> 인데 저항이 없으면</b> 핀이 <b>떠 있어(플로팅)</b> 값이 불안정합니다. <b><code>INPUT_PULLUP</code></b> 은 내부 저항이 핀을 <b>HIGH 로 끌어올려</b> 두고, 버튼을 누르면 GND 로 이어져 <b>LOW</b> 가 됩니다(논리가 뒤집힙니다). <b>외부 풀다운</b>은 평소 LOW, 누르면 HIGH 입니다. 경우마다 <code>snap(라벨, {읽는값, 안정})</code> 을 남기고 <b>[풀업에서 안 눌렀을 때 값, 풀업에서 눌렀을 때 값, 풀다운에서 눌렀을 때 값, 값이 불안정한 경우의 수, 풀업 회로에서 <code>if (digitalRead(p))</code> 가 참이면 버튼이 눌린 것인가]</b> 를 돌려주세요.","src":"const CASES = [\n  { name: 'INPUT · 저항 없음 · 안 누름', mode: 'INPUT',        pull: null,   pressed: false },\n  { name: 'INPUT_PULLUP · 안 누름',      mode: 'INPUT_PULLUP', pull: 'up',   pressed: false },\n  { name: 'INPUT_PULLUP · 누름',         mode: 'INPUT_PULLUP', pull: 'up',   pressed: true  },\n  { name: 'INPUT · 외부 풀다운 · 안 누름', mode: 'INPUT',      pull: 'down', pressed: false },\n  { name: 'INPUT · 외부 풀다운 · 누름',   mode: 'INPUT',       pull: 'down', pressed: true  }\n];\n\nfunction read(c) {\n  return 1;\n}\n\nfunction scene() {\n  return [0, 0, 0, 0, true];\n}\n\nRESULT = scene();","tests":[{"d":"풀업은 평소 HIGH","js":"RESULT[0]===1"},{"d":"누르면 LOW 로 떨어진다","js":"RESULT[1]===0"},{"d":"풀다운은 반대로 누를 때 HIGH","js":"RESULT[2]===1"},{"d":"저항 없는 INPUT 하나만 불안정하다","js":"RESULT[3]===1"},{"d":"풀업에서 참이면 버튼은 떼어진 상태다","js":"RESULT[4]===false"},{"d":"다섯 경우가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"같은 '안 누름' 인데 풀업과 풀다운의 값이 반대다","js":"FRAMES[1].value.읽는값!==FRAMES[3].value.읽는값"}],"ex":"디지털 입력 핀은 <b>HIGH 도 LOW 도 아닌 상태로 있을 수 없습니다</b> — 아무것도 연결하지 않으면 주변 전자기 잡음을 안테나처럼 주워 <b>제멋대로 0 과 1 을 오갑니다</b>(플로팅). 그래서 버튼 회로에는 <b>반드시 풀업이나 풀다운</b>이 있어야 하고, 아두이노는 내부 풀업을 내장하고 있어 <code>pinMode(p, INPUT_PULLUP)</code> 한 줄이면 <b>저항 없이</b> 해결됩니다. 대신 <b>논리가 뒤집힌다</b>는 것을 반드시 기억하세요 — 눌렀을 때가 <b>LOW(0)</b> 이라, <code>if (digitalRead(p))</code> 는 '눌렸다' 가 아니라 '<b>떼어졌다</b>' 는 뜻입니다. 이 한 줄 때문에 동작이 정반대가 되는 실수가 아주 흔합니다(<code>if (digitalRead(p) == LOW)</code> 라고 명시적으로 쓰는 편이 안전합니다). 왜 풀업이 표준이 됐는지도 알아 두면 좋습니다: 버튼의 한쪽을 <b>GND 에 묶기만 하면</b> 되어 배선이 단순하고, 마이크로컨트롤러는 대체로 <b>싱크(끌어내리는) 전류</b>를 더 잘 감당하기 때문입니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"타이밍 시뮬레이션","lv":3,"cat":"internals","q":"인터럽트가 바꾼 값을 루프가 <b>못 보는</b> 상황을 재현하세요. 규칙 — 공유 변수에 <code>volatile</code> 이 없으면 컴파일러가 <b>루프 밖에서 한 번 읽어 캐시</b>해 두므로, ISR 이 아무리 바꿔도 루프는 <b>처음 값만</b> 봅니다. 또 ISR 이 도는 동안에는 다른 인터럽트가 <b>막히므로</b>, ISR 이 길면 그 사이에 온 것들을 <b>놓칩니다</b>. 인터럽트가 <b>10ms 마다 5번</b> 발생하고 ISR 이 <b>100ms</b> 걸리는 경우를 계산하며 <code>snap(\"인터럽트 \"+n, {volatile없이, volatile있게})</code> 를 남기고 <b>[volatile 없이 루프가 감지한 횟수, volatile 있을 때, ISR 이 100ms 도는 동안 놓치는 인터럽트 수(10ms 주기), ISR 안에서 하면 안 되는 동작의 수, ISR 이 길수록 놓치는 개수는]</b> 를 돌려주세요.","src":"const EVENTS = 5, PERIOD_MS = 10, ISR_MS = 100;\nconst IN_ISR = [\n  { name: 'delay()',        ok: false },\n  { name: 'Serial.print()', ok: false },\n  { name: 'millis() 가 늘기를 기다리기', ok: false },\n  { name: '플래그 하나 세우기', ok: true }\n];\n\nfunction scene() {\n  return [0, 0, 0, 0, ''];\n}\n\nRESULT = scene();","tests":[{"d":"volatile 이 없으면 한 번도 못 본다","js":"RESULT[0]===0"},{"d":"volatile 이 있으면 다섯 번 다 본다","js":"RESULT[1]===5"},{"d":"ISR 이 100ms 면 아홉 개를 놓친다","js":"RESULT[2]===9"},{"d":"ISR 안에서 하면 안 되는 것이 셋","js":"RESULT[3]===3"},{"d":"ISR 이 길수록 더 놓친다","js":"RESULT[4]==='늘어난다'"},{"d":"다섯 인터럽트가 장면으로 남는다","js":"FRAMES.length===5"},{"d":"volatile 없는 쪽은 끝까지 0 이다","js":"FRAMES.every(function(f){return f.value.volatile없이===0;})"}],"ex":"<code>volatile</code> 은 컴파일러에게 '<b>이 변수는 네가 모르는 곳에서 바뀐다</b>' 고 알려 주는 표시입니다. 없으면 <code>while (!flag) {}</code> 같은 코드에서 컴파일러가 <b>flag 를 레지스터에 한 번만 읽어 두고</b> 무한 루프를 도는, <b>최적화를 켰을 때만 나타나는</b> 가장 찾기 어려운 버그가 생깁니다. 다만 <code>volatile</code> 이 해 주는 것은 <b>'매번 다시 읽기' 뿐</b>입니다 — <b>원자성은 보장하지 않습니다</b>. 8비트 MCU 에서 <code>volatile long counter</code> 를 루프가 읽는 도중 ISR 이 끼어들면 <b>절반만 갱신된 값</b>을 읽을 수 있으므로, 여러 바이트짜리 공유 변수는 <code>noInterrupts()</code>/<code>interrupts()</code> 로 감싸 읽어야 합니다. ISR 자체의 규칙은 하나로 요약됩니다 — <b>짧게, 정말 짧게</b>. 안에서 <code>delay()</code> 를 부르면 타이머 인터럽트가 막혀 <b>영영 끝나지 않고</b>, <code>Serial.print()</code> 는 버퍼가 찰 때까지 기다리므로 같은 이유로 위험합니다. ISR 은 <b>플래그만 세우고</b>, 실제 일은 <code>loop()</code> 에서 하세요."},{"t":"sim","k":"회로 시뮬레이션","lv":2,"cat":"internals","q":"LED 에 붙일 저항과 <b>핀이 감당할 수 있는 개수</b>를 계산하세요. 공급 5V, LED 순방향 전압 <b>2V</b> 이므로 저항에 걸리는 전압은 <b>3V</b> 이고 <code>I = 3 / R</code> 입니다. 아두이노 핀 하나는 <b>40mA</b>, 칩 전체는 <b>200mA</b> 가 한계입니다. 저항마다 <code>snap(R+\"Ω\", {전류mA, 핀한계초과})</code> 를 남기고 <b>[10mA 를 흘리려면 필요한 저항(Ω), 220Ω 일 때 전류(mA, 소수 첫째), 100Ω 일 때 전류(mA), 220Ω LED 를 한 핀에 몇 개까지, 전체 200mA 로는 몇 개까지]</b> 를 돌려주세요.","src":"const VCC = 5, VF = 2;\nconst RESISTORS = [220, 100, 330];\nconst PIN_MAX_MA = 40, CHIP_MAX_MA = 200, TARGET_MA = 10;\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"10mA 를 위해 300Ω","js":"RESULT[0]===300"},{"d":"220Ω 이면 13.6mA","js":"RESULT[1]===13.6"},{"d":"100Ω 이면 30mA — 권장치를 훌쩍 넘는다","js":"RESULT[2]===30"},{"d":"한 핀에는 두 개까지","js":"RESULT[3]===2"},{"d":"칩 전체로는 열네 개까지","js":"RESULT[4]===14"},{"d":"세 저항이 장면으로 남는다","js":"FRAMES.length===3"},{"d":"저항이 작을수록 전류가 커진다","js":"FRAMES[1].value.전류mA > FRAMES[0].value.전류mA"}],"ex":"LED 는 <b>전압이 조금만 올라도 전류가 폭발하는</b> 소자라, 저항 없이 핀에 바로 물리면 <b>LED 와 핀이 함께 죽습니다</b>. 계산은 옴의 법칙 한 줄입니다 — <b>저항이 감당할 전압은 (공급 − LED 순방향 전압)</b> 이고, 그 전압을 원하는 전류로 나누면 저항값이 나옵니다. 실무에서 놓치기 쉬운 것은 <b>한계가 두 겹</b>이라는 점입니다: <b>핀 하나당 40mA</b>(권장은 20mA), 그리고 <b>칩 전체 200mA</b>. 핀마다 20mA 씩 흘리면 <b>열 개만 켜도 전체 한계</b>에 닿습니다 — 데이터시트의 절대 최대 정격은 '이 값까지는 안 죽는다' 이지 '<b>계속 이렇게 써도 된다</b>' 가 아닙니다. LED 를 많이 켜야 하면 정공법은 셋입니다: <b>트랜지스터나 MOSFET 으로 외부 전원을 스위칭</b>하기, <b>전용 드라이버 IC</b>(정전류) 쓰기, <b>멀티플렉싱</b>으로 한 번에 한 줄씩만 켜기. 참고로 순방향 전압은 색마다 달라(빨강 ~1.8V, 파랑·흰색 ~3.2V) 같은 저항이라도 색이 바뀌면 전류가 달라집니다."},{"t":"sim","k":"신호 시뮬레이션","lv":3,"cat":"internals","q":"센서 값에 <b>튀는 값 하나</b>가 섞였을 때 두 필터가 어떻게 다른지 비교하세요. 창 크기 <b>3</b> 으로 훑으면서 <b>이동 평균</b>(세 값의 평균, 반올림)과 <b>중앙값</b>(세 값을 정렬한 가운데)을 각각 구하세요. 창마다 <code>snap(\"창 \"+n, {평균, 중앙값, 스파이크포함})</code> 을 남기고 <b>[원본의 최댓값, 이동 평균 출력의 최댓값, 중앙값 출력의 최댓값, 이동 평균 출력 중 스파이크가 섞인 개수, 중앙값 출력에 스파이크 값이 그대로 나온 개수]</b> 를 돌려주세요.","src":"const READINGS = [500, 502, 498, 501, 999, 499, 503, 500, 497, 502];\nconst W = 3, SPIKE = 999;\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"원본에는 999 가 있다","js":"RESULT[0]===999"},{"d":"이동 평균은 667 까지 끌려 올라간다","js":"RESULT[1]===667"},{"d":"중앙값은 503 을 넘지 않는다","js":"RESULT[2]===503"},{"d":"평균은 세 개의 출력이 오염된다","js":"RESULT[3]===3"},{"d":"중앙값 출력에는 999 가 한 번도 안 나온다","js":"RESULT[4]===0"},{"d":"여덟 개의 창이 장면으로 남는다","js":"FRAMES.length===8"},{"d":"스파이크가 낀 창에서 두 필터의 차이가 가장 크다","js":"FRAMES[3].value.평균-FRAMES[3].value.중앙값 > 100"}],"ex":"필터를 고르는 기준은 '<b>어떤 종류의 잡음인가</b>' 입니다. 센서 값이 참값 주변에서 <b>고르게 떨리는</b> 잡음이라면 <b>이동 평균</b>이 잘 듣습니다 — 평균이 흔들림을 상쇄해 주니까요. 하지만 접촉 불량이나 전기 스파크로 <b>가끔 한 번씩 크게 튀는</b> 값(임펄스 잡음)에는 평균이 최악입니다: 튄 값이 <b>창 크기만큼의 출력에 골고루 번져</b> 오염 구간을 오히려 넓힙니다(여기서는 하나의 스파이크가 <b>세 개의 출력</b>을 망쳤습니다). <b>중앙값 필터</b>는 정렬해서 가운데를 고르므로 <b>극단값을 아예 버립니다</b> — 창 안에서 튄 값이 절반 미만이면 흔적조차 남지 않습니다. 실무에서는 <b>중앙값으로 스파이크를 걷어낸 뒤 이동 평균으로 다듬는</b> 2단 구성이 흔합니다. 마이크로컨트롤러에서 쓸 때의 요령도 있습니다: 창을 배열로 들고 다니기 부담스러우면 <b>지수 이동 평균</b>(<code>y += (x − y) &gt;&gt; k</code>)이 <b>메모리 한 칸과 시프트 연산</b>만으로 비슷한 효과를 냅니다."},{"t":"sim","k":"통신 시뮬레이션","lv":3,"cat":"internals","q":"루프가 느리면 시리얼로 들어온 데이터가 <b>버퍼에서 넘쳐 사라집니다</b>. 규칙 — 한 바이트는 <b>시작 1 + 데이터 8 + 정지 1 = 10비트</b> 이므로 초당 도착 바이트는 <code>보율 / 10</code> 이고, 수신 버퍼는 <b>64바이트</b> 입니다. 루프 한 바퀴 동안 도착한 양이 버퍼를 넘으면 <b>넘친 만큼 버려집니다</b>. 경우마다 <code>snap(라벨, {도착, 유실})</code> 을 남기고 <b>[9600bps · 루프 100ms 에서 도착하는 바이트, 그때 잃는 바이트, 115200bps 에서 잃는 바이트, 루프를 10ms 로 줄였을 때 9600bps 에서 잃는 바이트, 9600bps 에서 하나도 안 잃는 최대 루프 시간(ms, 반올림)]</b> 을 돌려주세요.","src":"const BUFFER = 64, BITS_PER_BYTE = 10;\nconst CASES = [\n  { baud: 9600,   loopMs: 100 },\n  { baud: 115200, loopMs: 100 },\n  { baud: 9600,   loopMs: 10  },\n  { baud: 115200, loopMs: 10  }\n];\n\nfunction scene() {\n  return [0, 0, 0, 0, 0];\n}\n\nRESULT = scene();","tests":[{"d":"9600bps 로 100ms 면 96바이트가 온다","js":"RESULT[0]===96"},{"d":"버퍼가 64 라 32바이트를 잃는다","js":"RESULT[1]===32"},{"d":"115200bps 면 1,088바이트가 사라진다","js":"RESULT[2]===1088"},{"d":"루프를 10ms 로 줄이면 하나도 안 잃는다","js":"RESULT[3]===0"},{"d":"9600bps 에서 안전한 루프 한도는 67ms","js":"RESULT[4]===67"},{"d":"네 경우가 장면으로 남는다","js":"FRAMES.length===4"},{"d":"같은 루프 시간이라도 보율이 높으면 훨씬 많이 잃는다","js":"FRAMES[1].value.유실 > FRAMES[0].value.유실*10"}],"ex":"시리얼 수신은 <b>하드웨어가 알아서 받아 64바이트 버퍼에 쌓아 두는</b> 구조입니다 — 여러분의 <code>loop()</code> 가 <code>Serial.read()</code> 로 퍼 가지 않으면 <b>버퍼가 차고, 그 뒤에 온 것은 조용히 버려집니다</b>. 오류도 예외도 없이 <b>데이터만 사라지므로</b>, 증상은 '가끔 명령이 씹힌다' 처럼 나타나 원인을 찾기 어렵습니다. 계산은 단순합니다: <b>초당 바이트 = 보율 / 10</b>. 9600bps 는 초당 960바이트라 <b>67ms</b> 면 버퍼가 차고, 115200bps 는 초당 11,520바이트라 <b>불과 5.6ms</b> 면 찹니다 — 보율을 올리는 것이 <b>여유를 줄이는 일</b>이라는 점이 직관과 반대입니다. 대책은 셋입니다: ① <code>loop()</code> 안에서 <b><code>delay()</code> 를 없애고</b>(<code>millis()</code> 논블로킹으로 바꾸기) 매 바퀴 <code>Serial.available()</code> 을 비우기, ② 보내는 쪽 속도를 <b>흐름 제어나 요청-응답</b>으로 묶기, ③ 정말 빠른 스트림이라면 <b>버퍼 크기를 키우거나</b> DMA 를 지원하는 보드를 쓰기. 그리고 <b>보내는 쪽 <code>Serial.print</code> 도 버퍼가 차면 블로킹</b>된다는 점을 잊지 마세요 — 로그를 과하게 찍으면 그 자체가 루프를 느리게 만듭니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}],"ord":10}]);
